_DERIVED_RE = re.compile(r"^([A-Z][a-z]?)_total(_nomb)?$")


def derived_info(label):
    """'Ti_total' -> ('Ti', False), 'Ti_total_nomb' -> ('Ti', True), anything else -> None."""
    m = _DERIVED_RE.match(label)
    return (m.group(1), bool(m.group(2))) if m else None


def derived_terms(label, available):
    """How a summed channel is built from the channels that are present.
    Returns (plus, minus) with value = sum(plus) - sum(f * ref for ref, f in minus), or None if it cannot be built."""
    info = derived_info(label)
    if info is None:
        return None
    el, nomb = info
    have = set(available)
    plus = [f"{m}{el}" for m in SUM_ISOTOPES.get(el, []) if f"{m}{el}" in have]
    minus = []
    if nomb:
        added = 0
        for mass, interferer, ref in NOMB_CORRECTIONS.get(el, []):
            target, refl = f"{mass}{el}", f"{interferer_mass(ref)}{element_symbol(ref)}"
            if target in have and refl in have:
                plus.append(target)
                minus.append((refl, NATURAL_ABUNDANCE[interferer] / NATURAL_ABUNDANCE[ref]))
                added += 1
        if not added:
            return None
    return (plus, minus) if plus else None


# isotopes that stay individual when the summed total of the element is kept: the U-Th-Pb chain and the Hg correction
KEEP_ISOTOPES = {"199Hg", "200Hg", "201Hg", "202Hg", "203Tl", "205Tl", "209Bi", "204Hg", "204Pb", "206Pb", "207Pb", "208Pb", "232Th", "235U", "238U"}


def prefer_totals(want, have):
    """Swap individual isotopes for the element's summed total (better counting statistics) wherever one can be built.
    Isotopes in KEEP_ISOTOPES stay, and so does every isotope of an element that has no total."""
    have = set(have)
    tot = {derived_info(l)[0] for l in have if derived_info(l) and not derived_info(l)[1]}
    out = set()
    for l in want:
        if derived_info(l) or l not in have:
            out.add(l)
            continue
        el = element_of(l)
        if el in tot and l not in KEEP_ISOTOPES:
            out.add(f"{el}_total")
        else:
            out.add(l)
    return out


def element_symbol(iso):
    return re.match(r"([A-Z][a-z]?)", iso).group(1)


def interferer_mass(iso):
    return re.search(r"(\d+)$", iso).group(1)


def derived_labels(real_labels, nomb=False):
    """The summed channels that can be made from the isotopes in this file, plain sums first. The _nomb variants (natural abundance
    subtraction without mass bias) are offered only with nomb=True: the interference corrections applied to the counts do the same job
    with the mass bias included, so the corrected plain total is the more accurate one."""
    have = set(real_labels)
    plain = [f"{el}_total" for el in SUM_ISOTOPES if derived_terms(f"{el}_total", have)]
    corr = [f"{el}_total_nomb" for el in NOMB_CORRECTIONS if nomb and derived_terms(f"{el}_total_nomb", have)]
    return plain + corr


def derived_description(label, available):
    t = derived_terms(label, available)
    if t is None:
        return ""
    plus, minus = t
    s = " + ".join(plus)
    for ref, f in minus:
        s += f" - {f:.4g} x {ref}"
    return s



def safe_filename(s):
    return re.sub(r"[^\w.+-]+", "_", s.replace("/", "_over_")).strip("_") or "x"


def _natural_key(s):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", s)]


# --------------------------------------------------------------------------- reading
class VitSource:
    """A .vit file (zip of csv files) or a folder of csv files."""

    def __init__(self, path):
        self.path = str(path)
        self.zf = None
        if not os.path.isdir(self.path):
            try:
                self.zf = zipfile.ZipFile(self.path)
            except zipfile.BadZipFile as e:
                raise ValueError(f"{os.path.basename(self.path)} is not a zip archive or folder") from e

    def members(self):
        if self.zf is not None:
            names = [n for n in self.zf.namelist()
                     if n.lower().endswith(".csv") and "__MACOSX" not in n
                     and not os.path.basename(n).startswith(".")]
        else:
            names = []
            for root, _, files in os.walk(self.path):
                for f in files:
                    if f.lower().endswith(".csv") and not f.startswith("."):
                        names.append(os.path.relpath(os.path.join(root, f), self.path))
        return sorted(names, key=_natural_key)

    def read_bytes(self, name, limit=None):
        if self.zf is not None:
            with self.zf.open(name) as f:
                return f.read() if limit is None else f.read(limit)
        with open(os.path.join(self.path, name), "rb") as f:
            return f.read() if limit is None else f.read(limit)

    def read_array(self, info, use):
        """The columns `use` (numbers of header columns) of one line file, as a float64 array."""
        df = pd.read_csv(io.BytesIO(self.read_bytes(info.member)), skiprows=info.header_rows, header=0, usecols=use,
                         dtype=np.float64, encoding="utf-8-sig")
        return df.to_numpy()

    def close(self):
        if self.zf is not None:
            self.zf.close()


# --------------------------------------------------------------------------- raw Vitesse folders
# The files that come off the instrument (one folder per session, one sub-folder per image, one per run inside it) are read directly, so a
# .vit file made by NuQuant is not needed. What is reproduced, checked against a .vit made from the same files:
#   integ files   gzip, one block per 8 acquisitions: 16 byte header (version, 1, first acquisition number, number of regions) and 13 bytes per
#                 region (position in the trace, the summed peak area of the block, 5 bytes of zeros). Counts = area / AverageSingleIonArea.
#   pulse file    the acquisition number of every laser shot. A cycle is spot size / spacing shots (5), its first shot plus the transit time
#                 (TriggerCorrections.dat) is where it starts in the data, and it takes whole blocks: the first block that starts at or after
#                 the cycle start up to, not including, the first block at or after the next cycle start.
#   cps           counts in those blocks / (blocks x 8 acquisitions x acquisition period). The time written is the end of the cycle.
#   positions     x = start x + k x shots per cycle x spacing, y = start y, as in the .vit file.
# Not subtracted unless asked: the counts are those NuQuant writes without a gas blank. The option subtracts the mean of the blocks before the
# first laser shot of the run.
