# elements that do not occur in geologic samples at measurable levels (radioactive with no long-lived isotope, or gases)
ABSENT_EL = {"Tc", "Pm", "Po", "At", "Rn", "Fr", "Ra", "Ac", "Pa", "Np", "Pu", "Am", "Cm", "Xe", "Kr", "Ne", "He"}
HG204_OVER_202 = ISO_AB["Hg"][204] / ISO_AB["Hg"][202]
_MASS_RE = re.compile(r"^(\d+)")


def label_mass(label):
    m = _MASS_RE.match(str(label))
    return int(m.group(1)) if m else None


@dataclass
class InterfRule:
    id: str
    family: str                       # pedestal, isobar, oxide
    text: str
    kind: str = "edges"               # "edges" or "pedestal"
    edges: list = field(default_factory=list)       # [target mass, source (mass, "TIC" or "ONE"), coefficient]
    params: dict = field(default_factory=dict)
    enabled: bool = False
    basis: str = "measured"           # measured, physics, assumed
    evidence: str = ""
    effect: str = ""
    flags: list = field(default_factory=list)

    INFO = ("probes only cover", "large:", "interpolated across", "learned without")

    @property
    def warns(self):
        return [f for f in self.flags if not f.startswith(self.INFO)]

    @property
    def infos(self):
        return [f for f in self.flags if f.startswith(self.INFO)]

    def order(self):
        if self.kind == "pedestal":
            return (0, 0)
        if self.kind == "pedestal_line":
            return (0, 1)
        if self.kind == "gasblank":
            return (0, 2)
        if self.kind == "regfloor":
            return (3, 0)
        if self.kind == "linescale":
            return (9, 0)
        if self.family == "isobar":
            return (1, 0)
        src = [e[1] for e in self.edges if isinstance(e[1], (int, np.integer))]
        return (2, min(src) if src else 0)


def _line_sets(groups, n):
    """The row numbers of each line (each value of groups), found once by sorting instead of one comparison over all rows per line."""
    if groups is None:
        return [np.arange(n)]
    g = np.asarray(groups)
    order = np.argsort(g, kind="stable")
    _u, st = np.unique(g[order], return_index=True)
    return np.split(order, st[1:])


def _zone_signal_arr(M, q):
    """One value per cycle from the columns of M (cycles x empty masses): the mean, each mass held a few counts above the cycle's median."""
    if M.shape[1] < 3:
        return np.nanmedian(M, axis=1)
    med = np.nanmedian(M, axis=1)
    cap = med + 4 * np.maximum(q, np.sqrt(np.maximum(med, 0) * q))
    return np.nanmean(np.minimum(M, cap[:, None]), axis=1)


def line_levels(params, V, tic, rows, V0=None, Vraw=None):
    """The level of one line at the empty masses of each zone, as the difference from the fitted pedestal: [(centre, delta)], delta 0 when
    the line sits further off than the other lines did (it holds the element)."""
    out = []
    q = params.get("q", 100.0)
    for z in params.get("zones", []):
        ms = [m for m in z["masses"] if m in V]
        if len(ms) < 2:
            continue
        src = Vraw if Vraw is not None else V                      # the counts as they came, before any pedestal rule took its part off
        M = np.column_stack([src[m][rows] for m in ms])
        P = _zone_signal_arr(M, q)
        ref = z["a"] + z["b"] * tic[rows]
        if params.get("driver") and V0 is not None and params["driver"] in V0:
            ref = ref + z.get("a2", 0.0) + z.get("c", 0.0) * V0[params["driver"]][rows]
        d = float(np.nanmedian(P - ref))
        if abs(d) > z.get("cap", np.inf):
            d = 0.0
        out.append((z["centre"], d))
    return out


def _apply_line_level(params, V, tic, groups, V0=None, Vraw=None, sets=None):
    lo, hi = params.get("lo", 0), params.get("hi", 10 ** 6)
    n = len(tic)
    gl = sets if sets is not None else _line_sets(groups, n)
    for rows in gl:
        lv = line_levels(params, V, tic, rows, V0, Vraw)
        if not lv:
            continue
        cs = [c for c, _ in lv]
        ds = [d for _, d in lv]
        for m in V:
            if lo <= m <= hi and np.any(V[m][rows] != 0):
                V[m][rows] = V[m][rows] - float(np.interp(m, cs, ds))


def _step_value(nodes, m, col):
    """Value of the last node that starts at or below mass m, zero below the first node (a floor that starts at a mass and holds above it)."""
    v = 0.0
    for nd in nodes:
        if nd[0] <= m:
            v = nd[col]
    return v


def _ped_coefs(params, ms):
    """The constant and the ion-current (or driver) part of one pedestal rule at each of the masses ms."""
    ms = np.asarray(ms, float)
    nodes = params.get("nodes")
    if not nodes:
        return np.full(len(ms), params.get("a", 0.0)), np.full(len(ms), params.get("b", 0.0))
    nodes = sorted(nodes, key=lambda n: n[0])
    nm = np.array([n[0] for n in nodes], float)
    a, b = np.array([n[1] for n in nodes], float), np.array([n[2] for n in nodes], float)
    if params.get("step"):
        i = np.searchsorted(nm, ms, side="right") - 1
        return np.where(i >= 0, a[np.clip(i, 0, None)], 0.0), np.where(i >= 0, b[np.clip(i, 0, None)], 0.0)
    return np.interp(ms, nm, a), np.interp(ms, nm, b)


def _ped_at(params, m, tic, drv=None):
    """Pedestal of one rule at mass m, one value per cycle. A rule with a driver mass follows that mass instead of the ion current."""
    x = drv if (params.get("driver") and drv is not None) else tic
    nodes = params.get("nodes")
    if nodes and params.get("step"):
        return _step_value(nodes, m, 1) + _step_value(nodes, m, 2) * x
    if nodes:
        return _node_value(nodes, m, 1) + _node_value(nodes, m, 2) * x
    return params.get("a", 0.0) + params.get("b", 0.0) * x


GUARD_DEFAULT = 0.9
GUARD_KEEP = (202, 204, 206, 207, 208, 232, 235, 238)      # the U-Pb masses are judged by the reference material ages, not by this limit
GUARD_FROM = 180            # from this mass up, the empty masses the corrections are fitted on go to zero (the U-Pb region needs it)


def _guard_blank(V, M0, keys, rules, used, groups, g, sets=None):
    """A blank correction may not take more than the share g off the mean of a channel in one line. Where the learned blank is as large as the
    signal itself (low-count elements), the corrected mean would fall to zero or below, and nothing could be calibrated or drawn from that channel.
    Such a channel keeps (1 - g) of its mean. The empty masses from GUARD_FROM up (where the floor under Pb, Th and U is fitted) and the targets of isobar and oxide
    corrections are left alone: they are meant to go to zero."""
    edge_t = {t for r in rules if r.kind == "edges" for t, _s, _c in r.edges}
    ci = [i for i, m in enumerate(keys) if m not in edge_t and (m not in used or m < GUARD_FROM) and m not in GUARD_KEEP]
    if not ci:
        return
    cand = [keys[i] for i in ci]
    R = M0[:, ci]
    C = np.empty(R.shape, np.float64, order="F")                  # column by column: whole columns are contiguous, far faster than stacking
    for i, m in enumerate(cand):
        C[:, i] = V[m]
    S = R - C
    if sets is None:
        sets = [slice(None)] if groups is None else _line_sets(groups, len(R))
    changed = False
    with np.errstate(all="ignore"), warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for rows in sets:
            Rr, Sr = R[rows], S[rows]
            rm, sm = np.nanmean(Rr, axis=0), np.nanmean(Sr, axis=0)
            bad = (rm > 0) & (sm > g * rm)
            if bad.any():
                k = np.where(bad, g * rm / np.where(sm != 0, sm, 1.0), 1.0)
                C[rows] = Rr - Sr * k
                changed = True
    if changed:
        for i, m in enumerate(cand):
            V[m] = C[:, i]


class InterfModel:
    """The set of corrections of a session. Rules are switched on one by one. Nothing changes until the map is rebuilt."""

    def __init__(self):
        self.rules = []
        self.probes = []                  # empty masses chosen by hand, none means find them in the data
        self.used = []                    # the empty masses the last analysis used
        self.learn_glass = False          # learn the pedestal from glass lines too
        self.zero = []                    # masses the user says hold nothing in these samples
        self.driver = 0                   # a mass the floor at the empty masses follows besides the ion current, 0 means none unless the data show one
        self.lo = 0                       # the pedestal is taken off masses from here up, 0 means from the lowest empty mass
        self.skip_rms = []                # reference materials left out of the standards tests (their lines are read as samples)
        self.guard = GUARD_DEFAULT        # a blank correction may not take more than this share off the mean of a channel in one line (0 = no limit)
        self.only_target = True           # learn only from the lines that hold the minerals being quantified (all lines when there are none)
        self.blank = None                 # raw files: whether the gas blank was subtracted from the counts the corrections were learned on
        self.note = ""

    def active(self):
        return any(r.enabled for r in self.rules)

    def get(self, rid):
        return next((r for r in self.rules if r.id == rid), None)

    def set_rules(self, rules):
        old = {r.id: r.enabled for r in self.rules}
        for r in rules:
            if r.id in old:
                r.enabled = old[r.id]
        self.rules = list(rules)

    def apply(self, arr, mass_cols, groups=None):
        """Correct arr (rows x raw columns) in place. mass_cols: {mass: [column indices]}, the columns of one mass hold the same numbers.
        groups: the line each row belongs to, when arr holds several lines (the per-line level is taken line by line)."""
        rules = sorted([r for r in self.rules if r.enabled], key=InterfRule.order)
        if not rules:
            return
        keys = list(mass_cols)
        if keys:
            M0 = np.asfortranarray(arr[:, [mass_cols[m][0] for m in keys]], dtype=np.float64)       # one gather, then each mass is a contiguous column
        else:
            M0 = np.zeros((len(arr), 0))
        W = M0.copy(order="F")
        V = {m: W[:, i] for i, m in enumerate(keys)}                  # views of the working copy: no copy per mass
        g = float(getattr(self, "guard", 0.0) or 0.0)
        ls = next((r for r in rules if r.kind == "linescale"), None)
        tic = np.nansum(M0, axis=1)
        sets = _line_sets(groups, len(M0)) if groups is not None else None
        V0 = {r.params["driver"]: np.nan_to_num(V[r.params["driver"]]).copy() for r in rules
              if r.kind in ("pedestal", "pedestal_line") and r.params.get("driver") in V}                # the driver is read before any correction
        Vraw = {m: v.copy() for m, v in V.items()} if any(r.kind == "pedestal_line" for r in rules) else None
        for r in rules:
            if r.kind == "pedestal_line":
                _apply_line_level(r.params, V, tic, groups, V0, Vraw, sets)
                continue
            if r.kind == "regfloor":
                _apply_regfloor(r.params, V)
                continue
            if r.kind == "gasblank":
                _apply_gasblank(r.params, V, tic, groups, sets)
                continue
            if r.kind == "linescale":
                continue
            if r.kind == "pedestal":
                lo, hi = r.params.get("lo", 0), r.params.get("hi", 10 ** 6)
                drv = V0.get(r.params.get("driver"))
                if r.params.get("driver") and drv is None:
                    continue
                x = drv if drv is not None else tic
                ms = [m for m in V if lo <= m <= hi and np.any(V[m] != 0)]               # a column that is zero throughout was not measured
                A, B = _ped_coefs(r.params, ms)
                for m, a_, b_ in zip(ms, A, B):
                    V[m] -= a_ + b_ * x
                continue
            mrow = None
            if ls is not None and r.params.get("partners"):
                mrow = _line_mult(r, V, groups, ls.params.get("tau", 0.5), r.params.get("q") or ls.params.get("q", 1.0), sets)
            for t, s, c in r.edges:
                if t not in V:
                    continue
                if mrow is not None:
                    c = c * mrow
                if s == "TIC":
                    src = tic
                elif s == "ONE":
                    src = 1.0
                elif s in V:
                    src = V[s]
                else:
                    continue
                V[t] = V[t] - c * src
        if g > 0:
            _guard_blank(V, M0, keys, rules, set(self.used or []), groups, g, sets)
        for m, cs in mass_cols.items():
            for c in cs:
                arr[:, c] = V[m]

    def to_dict(self):
        return dict(rules=[asdict(r) for r in self.rules], probes=list(self.probes), used=list(self.used), zero=list(self.zero), learn_glass=bool(self.learn_glass), driver=int(self.driver), lo=int(self.lo), skip_rms=list(self.skip_rms), guard=float(self.guard), note=self.note, blank=self.blank)

    def load(self, d):
        self.rules, self.probes, self.used, self.zero, self.note, self.lo = [], [], [], [], "", 0
        self.learn_glass = False
        self.driver = 0
        self.skip_rms = []
        self.guard = GUARD_DEFAULT
        self.blank = None
        if not d:
            return
        for x in d.get("rules", []):
            x = dict(x)
            x["edges"] = [[int(t), (int(s) if not isinstance(s, str) else s), float(c)] for t, s, c in x.get("edges", [])]
            self.rules.append(InterfRule(**x))
        self.probes = [int(p) for p in d.get("probes", [])]
        self.used = [int(p) for p in d.get("used", [])]
        self.zero = [int(p) for p in d.get("zero", [])]
        self.learn_glass = bool(d.get("learn_glass", False))
        self.driver = int(d.get("driver", 0))
        self.lo = int(d.get("lo", 0))
        self.skip_rms = [str(x) for x in d.get("skip_rms", [])]
        self.guard = float(d.get("guard", GUARD_DEFAULT))
        self.blank = d.get("blank", None)
        self.note = d.get("note", "")


# ---- reading the raw mass columns of several lines
class RawLines:
    """Cycle-by-cycle counts of every mass in a set of lines. X is cycles x masses, one column per distinct mass."""

    def __init__(self, masses, X, line_of, std_of, rm_of=None):
        self.masses, self.X = list(masses), X
        self.line_of, self.std_of = line_of, std_of
        self.rm_of = rm_of if rm_of is not None else np.full(len(X), "", object)
        self.labels = {}                  # mass -> labels of the columns that share it, when known
        self.line_names = {}
        self.t_line = {}                  # line -> start time in seconds, when known
        self.idx = {m: i for i, m in enumerate(self.masses)}
        self.tic = np.nansum(X, axis=1)

    def col(self, m):
        return self.X[:, self.idx[m]] if m in self.idx else None

    def has(self, *ms):
        return all(m in self.idx for m in ms)


def read_raw_masses(source, info):
    """(masses, matrix) for one line: the first column of each mass."""
    ti, xi, yi, chan, labs = column_roles(info.columns)
    first, order = {}, []
    for j, lab in zip(chan, labs):
        m = label_mass(lab)
        if m is not None and m not in first:
            first[m] = j
            order.append(m)
    use = sorted({ti, xi, yi, *first.values()})
    arr = source.read_array(info, use)
    k = {c: i for i, c in enumerate(use)}
    good = np.isfinite(arr[:, k[xi]]) & np.isfinite(arr[:, k[yi]])
    arr = arr[good]
    return order, np.column_stack([arr[:, k[first[m]]] for m in order])


def read_raw_labels(source, info):
    """{mass: [labels]} of one line: every label whose column is a nominal-mass window."""
    ti, xi, yi, chan, labs = column_roles(info.columns)
    out = {}
    for lab in labs:
        m = label_mass(lab)
        if m is not None:
            out.setdefault(m, [])
            base = re.sub(r"#\d+$", "", str(lab))
            if base not in out[m]:
                out[m].append(base)
    return out


def _info_seconds(info):
    try:
        return datetime.fromisoformat(str(info.meta.get("Timestamp", ""))).timestamp()
    except ValueError:
        return float("nan")


AUTO_POOL = 160                                                           # most sample lines read (besides all standards) when the number of lines is left to the data


def target_lines(sess):
    """(members, minerals): the sample lines that hold pixels of the minerals being quantified (the U-Pb minerals and the trace element
    minerals that are switched on), so the corrections are learned from the lines they will be used on. (None, []) means use every line:
    no such minerals, no map, fewer than four such lines, or the switch is off (sess.interf.only_target). Whole lines are kept, not just
    the mineral pixels, because the pedestal needs the low-signal cycles between the grains."""
    if not getattr(sess.interf, "only_target", True) or sess.map is None or not sess.phases:
        return None, []
    names = set(sess.upb.minerals) | {n for n, mq in (sess.quant.minerals or {}).items() if mq.method != "off"}
    names = sorted(n for n in names if n in sess.phases)
    if not names:
        return None, []
    rows = np.zeros(sess.map.valid.shape[0], bool)
    for n in names:
        m = sess.phases[n].mask
        if m.shape[0] == rows.size:
            rows |= m.any(axis=1)
    infos = list(getattr(sess.map, "row_infos", []) or [])
    if len(infos) != rows.size:
        return None, []
    members = {i.member for i, r in zip(infos, rows) if r}
    smp = [i for i in sess.infos if i.use and i.role == "sample"]
    n_in = sum(1 for i in smp if i.member in members)
    if n_in < 4 or n_in >= len(smp):
        return (None, names) if n_in >= len(smp) else (None, [])
    return members, names


def pick_lines(sess, max_lines=40, only=None):
    """All standard lines plus an even spread (in time) of the sample lines, up to max_lines in total. max_lines 0 or less: every line.
    only: a set of line members, the sample lines are chosen among these."""
    stds = [i for i in sess.infos if i.use and i.role == "standard"]
    smp = [i for i in sess.infos if i.use and i.role == "sample" and (only is None or i.member in only)]
    t = np.array([_info_seconds(i) for i in smp])
    if len(smp) and np.isfinite(t).all():
        smp = [smp[k] for k in np.argsort(t, kind="stable")]               # spread over the session, so the drift is sampled
    if max_lines and max_lines > 0:
        room = max(max_lines - len(stds), 0)
        if room and len(smp) > room:
            smp = [smp[int(round(j))] for j in np.linspace(0, len(smp) - 1, room)]
        elif not room:
            smp = []
            stds = stds[:max_lines]
    return stds + smp


def load_raw_lines(sess, max_lines=40, progress=None, cache=None):
    """All standard lines plus an even spread of sample lines, up to max_lines in total. cache: {member: (masses, X)} to read each line once."""
    if sess.source is None:
        raise ValueError(NO_SOURCE)
    pick = pick_lines(sess, max_lines, target_lines(sess)[0])
    cache = {} if cache is None else cache
    parts, masses = [], None
    lid, sid, rid = [], [], []
    todo = [inf for inf in pick if inf.member not in cache]
    for inf, got in zip(todo, _pmap(lambda inf: read_raw_masses(sess.source, inf), todo)):
        cache[inf.member] = got
    for n, info in enumerate(pick):
        ms, X = cache[info.member]
        if masses is None:
            masses = ms
        else:
            pos = {m: i for i, m in enumerate(ms)}
            Y = np.full((len(X), len(masses)), np.nan)
            for j, m in enumerate(masses):
                if m in pos:
                    Y[:, j] = X[:, pos[m]]
            X = Y
        parts.append(X)
        lid += [n] * len(X)
        sid += [info.role == "standard"] * len(X)
        rid += [info.rm if info.role == "standard" else ""] * len(X)
        if progress:
            progress(n + 1, len(pick))
    if not parts:
        raise ValueError("No usable lines")
    rl = RawLines(masses, np.vstack(parts), np.array(lid), np.array(sid, bool), np.array(rid, object))
    try:
        rl.labels = read_raw_labels(sess.source, pick[0])
    except Exception:
        rl.labels = {}
    rl.line_names = {n: str(getattr(info, "name", n)) for n, info in enumerate(pick)}
    rl.t_line = {n: _info_seconds(info) for n, info in enumerate(pick)}
    skip = {str(x) for x in getattr(sess.interf, "skip_rms", [])}
    if skip:                                           # left out of the standards tests: the lines are then read as samples
        rl.std_of = rl.std_of & ~np.isin(np.array([str(x) for x in rl.rm_of]), list(skip))
    return rl


# ---- estimators
def _med(a):
    """np.median of a finite 1-D float array without numpy's wrapper overhead (same value)."""
    n = a.size
    h = n // 2
    if n % 2:
        return np.partition(a, h)[h]
    p = np.partition(a, [h - 1, h])
    return (p[h - 1] + p[h]) * 0.5


def _robust_line(x, y, floor=0.0):
    """Straight line y = a + b x that ignores outlying cycles (iterated, Huber-like). floor: the smallest scatter the
    weights may assume, so that counts in steps of one ion are not mistaken for outliers."""
    x, y = np.asarray(x, float), np.asarray(y, float)
    ok = np.isfinite(x) & np.isfinite(y)
    x, y = x[ok], y[ok]
    if len(x) < 10 or np.ptp(x) <= 0:
        return 0.0, 0.0, 0.0
    if len(x) > 20000:                                   # a line through this many cycles does not need them all
        step = int(np.ceil(len(x) / 20000))
        x, y = x[::step], y[::step]
    w = np.ones(len(x))
    for _ in range(8):
        sw = w.sum()
        mx, my = (w * x).sum() / sw, (w * y).sum() / sw
        sxx = (w * (x - mx) ** 2).sum()
        b_ = (w * (x - mx) * (y - my)).sum() / sxx if sxx > 0 else 0.0
        coef = (my - b_ * mx, b_)
        res = y - coef[0] - coef[1] * x
        mad = 1.4826 * _med(np.abs(res - _med(res)))
        s = max(mad, floor, 1e-9) if floor else (mad or 1.0)
        w = 1.0 / np.maximum(1.0, np.abs(res) / (1.5 * s))
    r = float(np.corrcoef(x, y)[0, 1]) if np.std(y) > 0 else 0.0
    return float(coef[0]), float(coef[1]), r


def scan_masses(raw):
    """Every mass against the total ion current of its cycle: constant part a, slope b (cps per million cps of ion current),
    median and mean level, and whether the mass looks like an oxide or hydride of a high-count signal 16 or 17 below it
    (the counts follow that signal, beyond what the ion current explains)."""
    tic = raw.tic
    q = raw_quantum(raw)

    def one(m):
        y = raw.col(m)
        ok = np.isfinite(y) & np.isfinite(tic)
        if ok.sum() < 20 or np.mean(y[ok] > 0) < 0.005:
            return None                                # a column that is zero throughout was not measured or was notched out
        a, b, r = _robust_line(tic[ok], y[ok], floor=0.5 * q)
        mean = float(np.nanmean(y))
        ox = ""
        for s_ in (m - 16, m - 17, m - 3, m - 2, m - 1, m + 1, m + 2, m + 3):      # oxide, hydroxide, tails and hydrides of a high-count neighbour
            if not raw.has(s_):
                continue
            ys = raw.col(s_)
            if not np.nanmean(ys) > 30 * max(mean, 1.0):
                continue
            ok2 = ok & np.isfinite(ys)
            A = np.column_stack([np.ones(ok2.sum()), tic[ok2], ys[ok2]])
            coef, res, rk, _ = np.linalg.lstsq(A, y[ok2], rcond=None)
            resid = y[ok2] - A @ coef
            sig2 = float(resid @ resid) / max(len(resid) - 3, 1)
            try:
                se = np.sqrt(np.diag(np.linalg.inv(A.T @ A)) * sig2)
            except np.linalg.LinAlgError:
                continue
            share = coef[2] * float(np.mean(ys[ok2])) / max(mean, 1e-9)
            if se[2] > 0 and coef[2] / se[2] > 5 and share > 0.3:
                ox = f"follows {s_}"
                break
        return dict(mass=m, a=a, b=b * 1e6, mean=mean, median=float(np.nanmedian(y)), oxide=ox)
    rows = [r_ for r_ in _pmap(one, raw.masses) if r_ is not None]
    return pd.DataFrame(rows)


def find_empty_masses(scan, lo=0, q=0.0, window=25, nlow=6, k=1.5, add=1.0):
    """Masses that hold only the pedestal: counts that rise with the ion current, with a median and a constant part of at most
    a few ions, and that follow the ion current no more than the quietest such masses nearby. Returns a list of masses."""
    if scan is None or scan.empty:
        return []
    cap = 3 * q if q > 0 else np.inf
    ok = (scan["oxide"] == "") & (scan["b"] >= 0.5) & (scan["median"] <= cap) & (scan["a"] <= cap) & (scan["mass"] >= lo)
    sc = scan[ok].sort_values("mass")
    m = sc["mass"].to_numpy()
    b = sc["b"].to_numpy()
    out = []
    for i in range(len(m)):
        near = np.abs(m - m[i]) <= window
        qq = np.median(np.sort(b[near])[:nlow])
        if b[i] <= k * qq + add:
            out.append(int(m[i]))
    return out


def _zones(masses, gap=6, span=15):
    zs, cur = [], []
    for m in sorted(masses):
        if cur and (m - cur[-1] > gap or m - cur[0] > span):
            zs.append(cur)
            cur = []
        cur.append(m)
    if cur:
        zs.append(cur)
    return zs


def _zone_signal(raw, ms):
    """One value per cycle from the empty masses of a zone: their mean, with each mass held to a few counts above the
    cycle's median so that one mass with a real signal does not matter."""
    return _zone_signal_arr(np.column_stack([raw.col(p) for p in ms]), raw_quantum(raw))


def _node_value(nodes, m, col):
    nodes = sorted(nodes, key=lambda n: n[0])
    nm = np.array([n[0] for n in nodes], float)
    return float(np.interp(m, nm, [n[col] for n in nodes]))


def _robust_multi(X, y, floor=0.0):
    """y = X b with outlying points down-weighted (iterated) and every coefficient held at zero or above: a floor, an ion-current part and
    a driver part can only add counts. X has a column of ones first."""
    from scipy.optimize import nnls
    ok = np.isfinite(y) & np.all(np.isfinite(X), axis=1)
    X, y = X[ok], y[ok]
    if len(y) < 12:
        return None
    w = np.ones(len(y))
    coef = None
    sc_x = np.maximum(np.abs(X).max(0), 1e-12)
    Xs = X / sc_x
    for _ in range(8):
        sw = np.sqrt(w)
        coef = nnls(Xs * sw[:, None], y * sw)[0] / sc_x
        res = y - X @ coef
        sc = max(1.4826 * _med(np.abs(res - _med(res))), floor, 1e-9)
        w = 1.0 / np.maximum(1.0, np.abs(res) / (1.5 * sc))
    return coef


def _zone_fit(P, TL, x, f, a_fixed=None):
    """[a, b, c] of P = a + b TL + c x (x may be None: c = 0), every part at zero or above. With a_fixed the floor is not fitted."""
    cols = [TL] + ([x] if x is not None else [])
    if a_fixed is None:
        co = _robust_multi(np.column_stack([np.ones(len(P))] + cols), P, f)
        if co is None:
            return None
        return np.array(list(co) + ([0.0] if x is None else []))
    co = _robust_multi(np.column_stack([np.ones(len(P))] + cols), P - a_fixed, f)         # the floor column is kept so the robust weights see a free offset
    if co is None:
        return None
    co = np.array(list(co) + ([0.0] if x is None else []))
    co[0] = a_fixed + co[0] * 0.0
    return co


def _fit_driver(raw, zinfo, q, tic, used_all, force=0):
    """A floor that follows one high-count mass besides the ion current. A zircon matrix puts a flat floor over the high masses in
    proportion to Zr.

    Counts of a single cycle are too noisy to show it, so the test is made on line means. The signal at the empty masses of each
    zone, line by line, is fitted as a + b TIC + c x for each high-count mass x, and compared with a + b TIC alone. The mass that
    lowers the line-to-line scatter most, on both halves of the lines, is kept.

    When the data hold cycles without ablation, they fix the floor a.

    Returns (driver mass, per-zone dicts a, b and c or None, evidence text) or None."""
    if not zinfo:
        return None
    lids = np.unique(raw.line_of)
    cands = [m for m in raw.masses if m not in used_all and raw.has(m) and np.nanmean(raw.col(m)) > 10 * q and np.any(raw.col(m) != 0)]
    if force:
        cands = [force] if (raw.has(force) and force not in used_all) else []
    if len(lids) < 15 or not cands:
        return None
    sel = []
    for l in lids:
        r_ = np.where(raw.line_of == l)[0]
        k = tic[r_] >= 0.3 * np.nanpercentile(tic[r_], 95)
        if k.sum() >= 5:
            sel.append(r_[k])
    if len(sel) < 15:
        return None
    lmean = lambda v: np.array([np.nanmean(v[a]) for a in sel])
    mad = lambda v: 1.4826 * np.nanmedian(np.abs(v - np.nanmedian(v))) or 1.0
    TL = lmean(tic)
    PL = [lmean(_zone_signal(raw, z["masses"])) for z in zinfo]
    XL = {m: lmean(np.nan_to_num(raw.col(m))) for m in cands}
    fl = [0.1 * mad(P) for P in PL]
    quiet = tic < 0.03 * np.nanpercentile(tic, 95)
    aq = None
    if quiet.sum() >= 150:                                                  # cycles without ablation measure the floor, so the fit cannot trade it against the driver
        aq = [float(np.nanmedian(_zone_signal(raw, z["masses"])[quiet])) for z in zinfo]
    afix = (lambda k: aq[k]) if aq is not None else (lambda k: None)
    resid = lambda P, TLx, x, co: P - (co[0] + co[1] * TLx + (co[2] * x if x is not None else 0.0))
    nl = len(TL)
    half = (np.arange(nl) % 2) == 0
    base, base_h = [], [[], []]
    for k, (P, f) in enumerate(zip(PL, fl)):
        co = _zone_fit(P, TL, None, f, afix(k))
        if co is None:
            return None
        base.append(mad(resid(P, TL, None, co)))
        for j, hm in enumerate((half, ~half)):
            c2 = _zone_fit(P[hm], TL[hm], None, f, afix(k))
            base_h[j].append(mad(resid(P[hm], TL[hm], None, c2)) if c2 is not None else np.nan)
    def try_mass(m):
        if np.std(XL[m]) <= 0:
            return None
        gains, fits, stab = [], [], []
        for k, (P, f) in enumerate(zip(PL, fl)):
            co = _zone_fit(P, TL, XL[m], f, afix(k))
            g_ = (1 - mad(resid(P, TL, XL[m], co)) / base[k]) if (co is not None and co[2] > 0) else 0.0
            gains.append(g_)
            fits.append(co if g_ > 0 else None)
            hs = []
            for j, hm in enumerate((half, ~half)):
                c2 = _zone_fit(P[hm], TL[hm], XL[m][hm], f, afix(k)) if co is not None else None
                hs.append((1 - mad(resid(P[hm], TL[hm], XL[m][hm], c2)) / base_h[j][k]) if (c2 is not None and np.isfinite(base_h[j][k])) else 0.0)
            stab.append(min(hs))
        score = float(sum(g_ for g_, st_ in zip(gains, stab) if g_ >= 0.15 and st_ >= 0.05))
        return (score, m, fits, gains)
    best = None
    for res in _pmap(try_mass, cands):                       # each candidate mass is tried on its own, the first of equal scores wins as before
        if res is not None and (best is None or res[0] > best[0]):
            best = res
    if best is None or best[0] <= 0:
        return None
    _, d, fits, gains = best
    rng = np.random.default_rng(1)
    out, tt, used_g = [], [], []
    for k, (P, f, co, g_) in enumerate(zip(PL, fl, fits, gains)):
        ok_ = co is not None and (force or g_ >= 0.15)
        t_ = 0.0
        if ok_:
            bs = []
            for _ in range(30):
                ii = rng.integers(0, len(P), len(P))
                c_ = _zone_fit(P[ii], TL[ii], XL[d][ii], f, afix(k))
                if c_ is not None:
                    bs.append(c_[2])
            t_ = co[2] / (float(np.std(bs)) or 1e-12)
            ok_ = t_ >= 4 or bool(force)
        if ok_:
            out.append(dict(a=float(co[0]), b=float(co[1]), c=float(co[2])))
            tt.append(t_)
            used_g.append(g_)
        else:
            out.append(None)
    if not tt:
        return None
    nz_ = [zi for zi, o in zip(zinfo, out) if o is not None]
    return d, out, (f"driver mass {d}: in the zones {', '.join(str(z['masses'][0]) + ' to ' + str(z['masses'][-1]) for z in nz_)} the line-to-line scatter at the empty masses "
                    f"falls by {100 * np.mean(used_g):.0f}% (mean) when the floor follows mass {d} as well as the ion current (slope/uncertainty {np.median(tt):.0f}, {len(sel)} lines"
                    f"{', floor fixed by cycles without ablation' if aq is not None else ''}). The other zones are left as they were")


BRIDGE_LO = 100          # the pedestal is bridged down to here: below it the floor is a small constant, from here up the ion-current part is there
ISO_FLOOR_SETS = {"Ba": [134, 135, 136, 137], "Nd": [143, 145, 146], "Dy": [161, 162, 163, 164], "Er": [166, 167, 168], "Yb": [171, 172, 173, 174]}


def _bridge_nodes(raw, sc, centres, lo=BRIDGE_LO, step=10, win=10, rank=0.15, cap=1.0):
    """The floor between and below the empty masses. Empty masses are few in the middle of the mass range (the rare earths sit there), so the
    pedestal is read from the lowest level among the masses round each node (masses that look like oxides or hydrides left out): a mass can only
    carry more than the floor, never less. Each node takes the ion-current and constant parts of that mass, and is held to cap times the highest level
    the empty masses themselves show, so a window full of real signal cannot raise it. Returns [(mass, constant, per cps of ion current)]."""
    if sc is None or len(sc) == 0 or not centres:
        return []
    tic = raw.tic
    tref = float(np.nanmedian(tic[tic > 0])) if np.any(tic > 0) else 0.0
    ms = sc["mass"].to_numpy(float)
    a_, b_ = sc["a"].to_numpy(float), sc["b"].to_numpy(float) * 1e-6               # the scan gives cps per million cps of ion current
    ok = (sc["oxide"].to_numpy() == "") & np.isfinite(a_) & np.isfinite(b_)
    lvl = a_ + b_ * tref
    zl = []
    for z in centres:
        near = ok & (np.abs(ms - z) <= 6)
        if near.any():
            zl.append(float(np.median(lvl[near])))
    top = max(zl) if zl else 0.0
    pts = list(np.arange(lo, min(centres) - step / 2, step))
    cs = sorted(centres)
    for x, y in zip(cs[:-1], cs[1:]):
        if y - x > 40:
            pts += list(np.arange(x + step, y - step / 2, step))
    out = []
    for c in pts:
        sel = np.flatnonzero(ok & (np.abs(ms - c) <= win))
        if len(sel) < 6:
            continue
        order = sel[np.argsort(lvl[sel])]
        i = order[int(rank * (len(order) - 1))]
        b = max(float(b_[i]), 0.0)
        a = max(float(lvl[i]) - b * tref, 0.0)
        L = a + b * tref
        if top > 0 and L > cap * top:
            a, b = a * cap * top / L, b * cap * top / L
        out.append((float(c), a, b))
    return out


def pedestal_iso_check(raw, rules, sets=None):
    """The floor under an element, read from its own isotopes: the counts of its clean isotopes against their natural abundances give a straight
    line whose intercept is what is there whatever the abundance. Returns [(element, floor before, floor after)] with the pedestal rules applied."""
    sets = sets or ISO_FLOOR_SETS
    from dataclasses import replace as _rep
    m = InterfModel()
    m.set_rules([_rep(r, enabled=(r.kind == "pedestal" and r.id != "ped_drv") or r.id == "ped_drv") for r in rules if r.kind in ("pedestal", "pedestal_line")])
    Xc = raw.X.copy()
    try:
        m.apply(Xc, {mm: [i] for i, mm in enumerate(raw.masses)}, raw.line_of)
    except Exception:
        return []
    out = []
    for el, ms in sets.items():
        if not all(x in raw.idx for x in ms) or el not in ISO_AB or not all(x in ISO_AB[el] for x in ms):
            continue
        ab = np.array([ISO_AB[el][x] for x in ms], float)
        A = np.column_stack([np.ones(len(ab)), ab / ab.max()])
        res = []
        for X in (raw.X, Xc):
            y = np.array([np.nanmean(X[:, raw.idx[x]]) for x in ms], float)
            res.append(float(np.linalg.lstsq(A, y, rcond=None)[0][0]))
        out.append((el, res[0], res[1]))
    return out


def est_pedestal(raw, probes=None, lo=0, hi=10 ** 6, scan=None, zero=None, learn_glass=False, driver=0, n_boot=30, bridge=True):
    """Counts that appear at masses where nothing should be, in proportion to the total ion current of the same cycle.
    The empty masses are taken from probes when given, otherwise found in the data over the whole mass range. They are
    grouped into zones and each zone gets its own fit, so the pedestal can change with mass.
    Returns (rules, detail dict). Two rules: the part that follows the ion current, and a constant offset."""
    full = raw
    gl = np.array([str(r).startswith("G_") for r in raw.rm_of])
    skipped_glass = 0
    if not learn_glass and gl.any() and (~gl).sum() >= 200:
        # glass lines hold every element, so no mass is empty in them: they would be read as pedestal
        keep_ = ~gl
        raw = RawLines(raw.masses, raw.X[keep_], raw.line_of[keep_], raw.std_of[keep_], raw.rm_of[keep_])
        raw.labels, raw.line_names = full.labels, full.line_names
        skipped_glass = int(len({int(l) for l in full.line_of[gl]}))
        scan = None
    tic = raw.tic
    sc = scan if scan is not None else scan_masses(raw)
    if probes:
        cand = [p for p in probes if p in raw.idx and p >= lo]
        mode = "chosen"
    else:
        cand = find_empty_masses(sc, lo, raw_quantum(raw))
        forced = [z for z in (zero or []) if z in raw.idx and z >= lo and sc["mass"].eq(z).any()]
        cand = sorted(set(cand) | set(forced))
        mode = "found" + (f" plus {len(forced)} you marked as zero" if forced else "")
        if len(cand) < 3:
            cand = sorted(set(p for p in PROBE_MASSES if p in raw.idx and p >= lo) | set(z for z in (zero or []) if z in raw.idx and z >= lo))
            mode = "default high masses"
        elif max(cand) < 150 and not zero:
            # only low masses came out empty (counts with a baseline taken off leave many of them at zero): the pedestal that matters sits on the
            # high masses, so the default probes join them
            hi_ = [p for p in PROBE_MASSES if p in raw.idx and p >= max(lo, 150)]
            if len(hi_) >= 3:
                cand = sorted(set(cand) | set(hi_))
                mode += " plus the default high masses"
    if len(cand) < 3:
        return [], dict(zones=pd.DataFrame(), scan=sc, used=[], mode=mode)
    q = raw_quantum(raw)
    zrows, nodes_b, nodes_a, used_all, dropped = [], [], [], [], []
    dropped_lines = {}
    tic_all = tic
    zinfo = []
    rng = np.random.default_rng(0)
    for zi, ms in enumerate(_zones(cand)):
        if len(ms) < (2 if mode == "chosen" else 3):
            dropped += ms
            continue
        bs = np.array([_robust_line(tic, raw.col(p), floor=0.5 * q)[1] * 1e6 for p in ms])
        med = float(np.median(bs))
        mad = max(1.4826 * float(np.median(np.abs(bs - med))), 0.25 * abs(med) + 1.0)
        keep = np.abs(bs - med) <= 3 * mad
        use = [p for p, k_ in zip(ms, keep) if k_] or ms
        dropped += [p for p in ms if p not in use]
        P = _zone_signal(raw, use)
        fl = 0.5 * q / max(np.sqrt(len(use)), 1.0)
        ok_rows = np.ones(len(P), bool)
        for _it in range(2):                                  # lines that sit far above the rest at these masses hold the element, not the pedestal
            a, b, r = _robust_line(tic[ok_rows], P[ok_rows], floor=fl)
            resid = P - (a + b * tic)
            lids = np.unique(raw.line_of)
            lm = np.array([np.nanmean(resid[(raw.line_of == l) & ok_rows]) if np.any((raw.line_of == l) & ok_rows) else np.nan for l in lids])
            sc_ = max(1.4826 * np.nanmedian(np.abs(lm - np.nanmedian(lm))), 0.5 * q / np.sqrt(len(use)))
            bad = lids[np.nan_to_num(lm) > np.nanmedian(lm) + 5 * sc_]
            if not len(bad) or len(bad) > 0.3 * len(lids):
                break
            ok_rows &= ~np.isin(raw.line_of, bad)
        n_bad = int(len(np.unique(raw.line_of)) - len(np.unique(raw.line_of[ok_rows])))
        if n_bad:
            dropped_lines[zi] = n_bad
        tic_z, P_z = tic[ok_rows], P[ok_rows]
        P, tic = P_z, tic_z
        a, b, r = _robust_line(tic, P, floor=fl)
        boots = []
        for _ in range(n_boot):                                # only the uncertainties come from these, never the fitted values
            ii = rng.integers(0, len(P), len(P))
            boots.append(_robust_line(tic[ii], P[ii], floor=fl)[:2])
        sa, sb = (float(np.std([x[0] for x in boots])), float(np.std([x[1] for x in boots]))) if boots else (float("nan"), float("nan"))
        tic = tic_all
        cen = float(np.median(use))
        zinfo.append(dict(masses=[int(x) for x in use], centre=cen, a=float(a), b=float(b)))
        nodes_b.append([cen, 0.0, float(b)])
        nodes_a.append([cen, float(a), 0.0])
        used_all += use
        zrows.append(dict(zone=f"{min(use)} to {max(use)}", masses=", ".join(map(str, use)), n=len(use), centre=cen, constant_cps=a, se_constant=sa,
                          per_million_tic=b * 1e6, se_per_million=sb * 1e6, r=r, lines_dropped=dropped_lines.get(zi, 0)))
    if not zrows:
        return [], dict(zones=pd.DataFrame(), scan=sc, used=[], mode=mode)
    zt = pd.DataFrame(zrows)
    lo_eff = int(lo) if lo else int(min(used_all))
    use_bridge = bool(bridge)
    bridge = []
    if use_bridge and not lo and mode != "chosen":
        bridge = _bridge_nodes(raw, sc, [float(x) for x in zt["centre"]])
        for c_, a_, b_ in bridge:
            nodes_b.append([c_, 0.0, b_])
            nodes_a.append([c_, a_, 0.0])
        if bridge:
            lo_eff = int(min(c_ for c_, _a, _b in bridge) - 5)
    top = tic >= np.quantile(tic, 0.9)
    flags_b, flags_a = [], []
    weak = zt[(zt["se_per_million"] > 0) & (zt["per_million_tic"].abs() / zt["se_per_million"].replace(0, np.nan) < 5)]
    if len(weak):
        flags_b.append("slope is under 5 times its uncertainty in zone " + ", ".join(weak["zone"]) + ": the link to the ion current is weak there")
    if skipped_glass:
        flags_b.append(f"learned without {skipped_glass} glass line(s): every element is present in glass, so no mass is empty there")
    if int(zt["lines_dropped"].sum()):
        flags_b.append(f"learned without lines that sit far above the rest at the empty masses ({int(zt['lines_dropped'].sum())} line-zone pairs): they hold the element")
    if dropped:
        flags_b.append(f"{len(dropped)} candidate mass(es) disagreed with their zone and were left out ({', '.join(map(str, sorted(dropped)))})")
    if len(zt) == 1 and min(used_all) > 150:
        flags_b.append(f"probes only cover masses {min(used_all)} to {max(used_all)}")
    cs = sorted(zt["centre"])
    gaps = [(x, y) for x, y in zip(cs[:-1], cs[1:]) if y - x > 40]
    if gaps:
        flags_b.append("interpolated across " + ", ".join(f"{int(x)} to {int(y)}" for x, y in gaps) + ": no empty mass there")
    if bridge:
        lv = ", ".join(f"{int(c_)}: {1e6 * b_:.0f}" for c_, a_, b_ in bridge[::max(len(bridge) // 6, 1)])
        flags_b.append(f"no empty masses at {int(min(c_ for c_, _a, _b in bridge))} to {int(max(c_ for c_, _a, _b in bridge))} between and below the empty masses: the pedestal there is the lowest level among the neighbouring masses "
                       f"(cps per million cps of ion current at masses {lv}). Check it against the isotope patterns and the standards")
    elif lo_eff < min(used_all) - 5:
        flags_b.append(f"large: pedestal applied down to mass {lo_eff}, below the lowest empty mass {min(used_all)}: held at its value there")
    flags_a.append("a constant offset can be a blank-subtraction artifact or real background: tick it only if the empty masses stay positive after the ion-current part")
    keyt = {m: raw.col(m) for m in (31, 45, 89, 204, 206, 207, 208, 232, 235, 238) if raw.has(m)}

    def eff(rule_nodes, which):
        out = []
        for m, v in keyt.items():
            if m not in (31, 45, 204, 207, 235):
                continue
            pm = _node_value(rule_nodes, m, which) * (tic[top] if which == 2 else 1.0)
            out.append(f"{m}: {100 * np.nanmean(pm) / max(np.nanmean(v[top]), 1e-9):.0f}%")
        return ", ".join(out)
    nz = f"{len(used_all)} empty masses in {len(zt)} zone(s) ({mode})"
    ev_zones = "; ".join(f"{r.zone}: {r.per_million_tic:.1f} +/- {r.se_per_million:.1f}" for r in zt.itertuples())
    bmin, bmax = zt["per_million_tic"].min(), zt["per_million_tic"].max()
    txt_b = (f"{bmax:.1f} cps per million cps of ion current, masses {lo_eff} and up" if len(zt) == 1 or abs(bmax - bmin) < 0.2 * abs(bmax)
             else f"{bmin:.1f} to {bmax:.1f} cps per million cps of ion current, by mass zone, masses {lo_eff} and up")
    rb = InterfRule("ped_tic", "pedestal", "Pedestal that follows the total ion current: " + txt_b, "pedestal",
                    params=dict(a=0.0, b=0.0, lo=lo_eff, lo_auto=int(min(used_all)), hi=int(hi), nodes=nodes_b), basis="measured",
                    evidence=f"{nz}. Per million, by zone: {ev_zones}. {len(tic):,} cycles", effect="in the strongest cycles: " + eff(nodes_b, 2), flags=flags_b)
    ra = InterfRule("ped_const", "pedestal", f"Constant offset by mass zone, masses {lo_eff} and up: " +
                    ", ".join(f"{r.constant_cps:.0f} cps at {r.zone}" for r in zt.itertuples()), "pedestal",
                    params=dict(a=0.0, b=0.0, lo=lo_eff, lo_auto=int(min(used_all)), hi=int(hi), nodes=nodes_a), basis="measured",
                    evidence=f"intercepts of the same fits: " + "; ".join(f"{r.zone}: {r.constant_cps:.0f} +/- {r.se_constant:.0f}" for r in zt.itertuples()) +
                    f" (one ion in a cycle is about {raw_quantum(raw):.0f} cps)",
                    effect="in the strongest cycles: " + eff(nodes_a, 1), flags=flags_a)
    rules = [rb, ra]
    dr = _fit_driver(raw, zinfo, q, tic, set(used_all), force=int(driver or 0))
    if dr is not None:
        dm, dz, dtxt = dr
        cmax = max(d_["c"] for d_ in dz if d_ is not None)
        sig = [d_ is not None and d_["c"] >= 0.25 * cmax for d_ in dz]                # the floor is applied from the first zone where it is clear, and holds above it
        for k, (zi_, d_, ok_) in enumerate(zip(zinfo, dz, sig)):
            if not ok_:
                zi_.update(c=0.0, a2=0.0)
                continue
            zi_.update(a=d_["a"], b=d_["b"], c=d_["c"], a2=0.0)                          # the ion-current and constant parts are refitted together with the driver
            nodes_b[k] = [zi_["centre"], 0.0, d_["b"]]
            nodes_a[k] = [zi_["centre"], d_["a"], 0.0]
            zt.loc[k, "per_million_tic"], zt.loc[k, "constant_cps"] = d_["b"] * 1e6, d_["a"]
        ev_zones = "; ".join(f"{r.zone}: {r.per_million_tic:.1f}" for r in zt.itertuples())
        rb.params["nodes"], ra.params["nodes"] = nodes_b, nodes_a
        rb.evidence = f"{nz}. Per million, by zone (refitted with mass {dm}): {ev_zones}. {len(tic):,} cycles"
        ra.evidence = "intercepts of the joint fit: " + "; ".join(f"{r.zone}: {r.constant_cps:.0f}" for r in zt.itertuples())
        nodes_d = [[min(zi_["masses"]) - 2, 0.0, d_["c"]] for zi_, d_, ok_ in zip(zinfo, dz, sig) if ok_]
        rd = InterfRule("ped_drv", "pedestal", f"Floor that follows mass {dm} instead of the ion current, masses {lo_eff} and up: " +
                        ", ".join(f"{d_['c']:.3f} x mass {dm} from {min(zi_['masses'])}" for zi_, d_, ok_ in zip(zinfo, dz, sig) if ok_),
                        "pedestal", params=dict(a=0.0, b=0.0, lo=lo_eff, lo_auto=int(min(used_all)), hi=int(hi), nodes=nodes_d, driver=int(dm), step=True), basis="measured",
                        evidence=dtxt + ". Fitted together with the ion-current rule, so tick it with ped_tic",
                        effect="", flags=["a driver mass can be a real element that happens to rise with the pedestal: judge it by the standards test"])
        rules.append(rd)
    rl = _line_level_rule(raw, zinfo, q, lo_eff, hi, int(min(used_all)), driver=(dr[0] if dr is not None else None))
    if rl is not None:
        rules.append(rl)
    iso = []
    try:
        iso = pedestal_iso_check(raw, rules)
    except Exception:
        iso = []
    if bridge and len(iso) >= 3 and sum(abs(x[2]) for x in iso) > 0.8 * sum(abs(x[1]) for x in iso):
        # the bridge does not take the floor off the isotope patterns (the empty masses may hold real signal, as in glass): leave it out
        r2, p2 = est_pedestal(raw, probes, lo, hi, scan, zero, learn_glass, driver, n_boot, bridge=False)
        if r2:
            r2[0].flags.append("the pedestal was not carried down to the masses between the empty masses: it made the floor read from the isotope patterns "
                               f"of {', '.join(x[0] for x in iso)} no smaller")
        return r2, p2
    if iso:
        rb.evidence += ". Floor read from the isotope patterns (cps, before to after the pedestal): " + ", ".join(f"{el} {b0:.0f} to {b1:.0f}" for el, b0, b1 in iso)
    return rules, dict(zones=zt, scan=sc, used=sorted(used_all), mode=mode, lo=lo_eff, bridge=bridge, iso_check=iso)


def _line_level_rule(raw, zinfo, q, lo_eff, hi, lo_auto, driver=None):
    """The level of each line at the empty masses, relative to the fitted pedestal. If lines differ by more than counting noise explains,
    the rule takes each line's own level off, so a line-to-line baseline does not pass as signal."""
    if not zinfo:
        return None
    lids = np.unique(raw.line_of)
    V = {m: raw.col(m) for m in raw.masses}
    tic = raw.tic
    params = dict(zones=[dict(z, cap=np.inf) for z in zinfo], q=float(q), lo=lo_eff, lo_auto=lo_auto, hi=int(hi))
    if driver:
        params["driver"] = int(driver)
    per = {i: [] for i in range(len(zinfo))}
    ncyc = []
    for l in lids:
        rows = raw.line_of == l
        ncyc.append(int(rows.sum()))
        for i, z in enumerate(zinfo):
            ms = [m for m in z["masses"] if m in V]
            if len(ms) < 2:
                per[i].append(np.nan)
                continue
            P = _zone_signal_arr(np.column_stack([V[m][rows] for m in ms]), q)
            ref = z["a"] + z["b"] * tic[rows]
            if driver:
                ref = ref + z.get("a2", 0.0) + z.get("c", 0.0) * np.nan_to_num(V[driver][rows])
            per[i].append(float(np.nanmedian(P - ref)))
    spread, noise, rows_ev, caps = [], [], [], []
    for i, z in enumerate(zinfo):
        d = np.array(per[i], float)
        d = d[np.isfinite(d)]
        if len(d) < 5:
            continue
        mad = 1.4826 * np.median(np.abs(d - np.median(d)))
        cap = float(max(3 * mad, 0.3 * q / np.sqrt(len(z["masses"]))))
        params["zones"][i]["cap"] = cap
        nz_ = float(q * 1.0 / np.sqrt(len(z["masses"]) * max(np.median(ncyc), 1)) * 1.5)         # counting noise of a median over a line, a generous guess
        spread.append(mad)
        noise.append(nz_)
        rows_ev.append(f"{z['masses'][0]} to {z['masses'][-1]}: +/-{mad:.0f} cps (noise {nz_:.0f})")
    if not spread:
        return None
    flags = []
    if np.median(spread) < 1.5 * np.median(noise):
        flags.append("line-to-line differences at the empty masses are no larger than counting noise: this correction is not needed")
    return InterfRule("ped_line", "pedestal", "Level of each line at the empty masses, relative to the fitted pedestal (adds to the pedestal rules)", "pedestal_line",
                      params=params, basis="measured",
                      evidence="line-to-line spread (robust) by zone: " + "; ".join(rows_ev) + f", {len(lids)} lines. A line far outside the others is left alone",
                      effect="", flags=flags)


def raw_quantum(raw):
    """Smallest step between nonzero counts, a hint of what one ion looks like in cps."""
    v = raw.X[:, :60].ravel()
    v = v[np.isfinite(v)]
    v = np.abs(v[v != 0])                      # counts with a baseline taken off can be negative: their size counts, not their sign
    return float(np.percentile(v, 1)) if v.size else float("nan")


def _ped_vec(raw, rules):
    """The pedestal of the rules as a function: mass -> one value per cycle (zero below the rule's lowest mass)."""
    rs = [r for r in rules if r.kind == "pedestal"]
    tic = raw.tic

    def f(m):
        out = np.zeros(len(tic))
        for r in rs:
            if r.params.get("lo", 0) <= m <= r.params.get("hi", 10 ** 6):
                d = r.params.get("driver")
                out = out + _ped_at(r.params, m, tic, np.nan_to_num(raw.col(d)) if d and raw.has(d) else None)
        return out
    return f


def _pm(ped, m, lo=0):
    """Pedestal at mass m from either a function (new) or a single vector (old, applied from mass lo)."""
    if ped is None:
        return 0.0
    if callable(ped):
        return ped(m)
    return ped if m >= lo else 0.0


def est_hg204(raw, ped=None):
    """204Hg sitting on 204Pb: 204Hg = 0.2301 x 202Hg from the natural abundances. Tested where the cycles carry Hg."""
    if not raw.has(202, 204):
        return []
    h = raw.col(202) - _pm(ped, 202)
    d = raw.col(204) - _pm(ped, 204)
    sig = 1.4826 * np.nanmedian(np.abs(h - np.nanmedian(h))) or 1.0
    rich = h > max(10 * sig, 5 * raw_quantum(raw))
    flags, ev = [], ""
    if rich.sum() >= 8:
        s = float(np.nansum(d[rich]) / np.nansum(h[rich]))
        ev = f"{int(rich.sum())} cycles with Hg: 204/202 = {s:.3f}, natural value {HG204_OVER_202:.3f}"
        if abs(s - HG204_OVER_202) > 0.5 * HG204_OVER_202:
            flags.append("measured 204/202 differs from the natural ratio: Pb on 204 or something else in the way")
        pat = {m: ISO_AB["Hg"][m] / ISO_AB["Hg"][202] for m in (199, 200, 201)}
        off = []
        for m, nat in pat.items():
            if raw.has(m):
                r_ = float(np.nansum((raw.col(m) - (p_ := _pm(ped, m)))[rich]) / np.nansum(h[rich]))
                if abs(r_ - nat) > 0.4 * nat:
                    off.append(f"{m}/202 = {r_:.2f} (Hg: {nat:.2f})")
        if off:
            flags.append("masses " + ", ".join(off) + ": 202 holds something besides Hg, so the Hg term would over-correct 204")
    else:
        ev = "no cycle here carries enough Hg to test the ratio, natural abundance used"
        flags.append("untested on this data")
    eff = ""
    if raw.has(204):
        top = h > 0
        eff = f"mean subtraction {HG204_OVER_202 * np.nanmean(h[top]):.0f} cps on 204" if top.any() else ""
    return [InterfRule("hg204", "isobar", f"204Hg on 204Pb: subtract {HG204_OVER_202:.4f} x the 202 signal", "edges",
                       edges=[[204, 202, HG204_OVER_202]], basis="physics", evidence=ev, effect=eff, flags=flags)]


def oxide_edges(el, rate, present):
    src = OX_SOURCE[el]
    ab = ISO_AB[el]
    out = []
    for m, a in ab.items():
        c = rate * a / ab[src]
        t = m + 16
        if a >= 0.01 and t in present and c > 0:
            out.append([t, src, float(c)])
    return out


def measure_oxide_rates(raw, ped=None, lo=195):
    """Oxide fraction MO/M from masses that hold the oxide alone: Hf (the isotopes at +16), Lu (175 to 191), Tm (169 to 185).
    The pedestal is taken off only at the masses the pedestal rule covers."""

    def c(m):
        return raw.col(m) - _pm(ped, m, lo)
    res = {}
    if not raw.has(178):
        return res
    hf = raw.col(178)
    g = hf > np.nanquantile(hf, 0.8)
    if g.sum() >= 5:
        S = np.nanmean([np.nanmean(c(m)[g]) / a for m, a in ISO_AB["Hf"].items() if m in (177, 178, 179)])
        per = {m + 16: np.nanmean(c(m + 16)[g]) / (a * S) for m, a in ISO_AB["Hf"].items()
               if m in (177, 178, 179, 180) and raw.has(m + 16)}
        if per:
            v = np.array(list(per.values()))
            res["Hf"] = dict(rate=float(np.median(v)), spread=float(np.std(v) / max(np.mean(v), 1e-12)), detail=per)
    for el, (s_, t_) in (("Lu", (175, 191)), ("Tm", (169, 185))):
        if raw.has(s_, t_):
            x = c(s_)
            top = x > np.nanquantile(x, 0.8)
            if top.sum() >= 5 and np.nanmean(x[top]) > 0:
                res[el] = dict(rate=float(np.nanmean(c(t_)[top]) / np.nanmean(x[top])), spread=float("nan"), detail={t_: None})
    return res


def est_oxides(raw, ped=None, lo=195, fit=True):
    meas = measure_oxide_rates(raw, ped, lo)
    rates = [v["rate"] for v in meas.values() if np.isfinite(v["rate"]) and v["rate"] > 0]
    if not rates:
        return [], meas
    r_hf = meas.get("Hf", {}).get("rate")
    scale = fit_oxide_scale(raw, r_hf) if (fit and r_hf and r_hf > 0) else None
    lam_ok = bool(scale and scale["gain"] > 0.05 and scale["lam"] > 0 and not (np.isfinite(scale["spread"]) and scale["spread"] > 0.6))
    lam = scale["lam"] if lam_ok else 1.0
    default = float(np.median(rates))
    present = set(raw.masses)
    rules = []
    for el in OX_SOURCE:
        prior = ox_prior(el, r_hf) * lam if r_hf else default
        flags = []
        if el in meas and meas[el]["rate"] > 0:
            r, basis = meas[el]["rate"], "measured"
            ev = f"{el}O/{el} = {100 * r:.2f}%"
            if el == "Hf":
                ev += f", the Hf isotopes agree within {100 * meas[el]['spread']:.0f}%"
                if meas[el]["spread"] > 0.2:
                    flags.append("isotopes disagree: something else sits on the oxide masses")
            elif prior > 0 and max(r / prior, prior / r) > 3:
                flags.append(f"measured rate is {max(r / prior, prior / r):.1f} times away from the bond-strength expectation: another species may sit on the oxide mass")
        elif lam_ok:
            r, basis = prior, "fitted"
            ev = (f"level fitted from the isotope patterns of {scale['n']} line(s): {lam:.2f} x the bond-strength expectation anchored on HfO "
                  f"({100 * ox_prior(el, r_hf):.2f}% x {lam:.2f}), mass bias {100 * scale['beta']:+.1f}% per amu. The relative rate between elements is the expectation, not measured")
            if np.isfinite(scale["spread"]) and scale["spread"] > 0.3:
                flags.append(f"the lines disagree on the oxide level (spread {100 * scale['spread']:.0f}%)")
        else:
            r, basis = prior, "assumed"
            why = ("the pattern fit found no oxide level beyond noise" if scale and scale["gain"] <= 0.05 else
                   "the pattern fit was not reliable" if scale else "no standard with enough rare earths to fit")
            ev = (f"{why}. Rate set from HfO ({100 * r_hf:.2f}%) and the bond strength of {el}O" if r_hf else
                  f"{why}. Median of the measured rates ({100 * default:.2f}%) is used")
            flags = ["assumed rate, check with a standard rich in this element"]
        ed = oxide_edges(el, r, present)
        if not ed:
            continue
        tg = ", ".join(str(e[0]) for e in ed)
        rules.append(InterfRule(f"ox_{el}", "oxide", f"{el}O on {tg}: {100 * r:.2f}% of {el}, in proportion to its isotopes", "edges",
                                edges=ed, basis=basis, evidence=ev, flags=flags))
    for rl in rules:                      # the largest effect on any mass, from the mean over all cycles
        best = ("", 0.0)
        for t, s_, c in rl.edges:
            tv, sv = raw.col(t), raw.col(s_)
            if tv is None or sv is None:
                continue
            f = np.nanmean(c * sv) / max(np.nanmean(tv), 1e-9)
            if f > best[1]:
                best = (f"{100 * f:.0f}% of mass {t} on average", f)
        rl.effect = best[0]
        if best[1] > 0.05:
            rl.flags.append("large: more than 5% of a mass")
    meas["_scale"] = scale
    return rules, meas


# ---- 235U: the Th tail
def est_u235(raw, ped=None, lo=195):
    """What 235 holds beyond U: 235 = kU x 238 + kTh x 232, fitted over the cycles. The Th part (a tail or hydride three masses up)
    is proposed for removal. The U part is the mass bias between 235 and 238 and is left to the calibration."""
    if not raw.has(232, 235, 238):
        return []
    y = raw.col(235) - _pm(ped, 235, lo)
    u = raw.col(238) - _pm(ped, 238, lo)
    th = raw.col(232) - _pm(ped, 232, lo)
    ok = np.isfinite(y) & np.isfinite(u) & np.isfinite(th) & ((u > 20 * raw_quantum(raw)) | (th > 20 * raw_quantum(raw)))
    if ok.sum() < 30:
        return []
    y, u, th = y[ok], u[ok], th[ok]
    q = raw_quantum(raw)
    B = np.column_stack([u, th])

    def fit(i):
        k_ = np.linalg.lstsq(B[i], y[i], rcond=None)[0]          # weights from the fitted level, not the noisy count, so low counts are not favoured
        for _ in range(3):
            mu = np.maximum(B[i] @ k_, 0.0)
            w_ = 1.0 / np.sqrt(mu * q + (0.02 * mu) ** 2 + q * q)
            k_ = np.linalg.lstsq(B[i] * w_[:, None], y[i] * w_, rcond=None)[0]
        return k_
    k = fit(slice(None))
    rng = np.random.default_rng(1)
    bs = np.array([fit(rng.integers(0, len(y), len(y))) for _ in range(60)])
    sd = bs.std(axis=0)
    r_uth = float(np.corrcoef(u, th)[0, 1])
    kU, kTh = float(k[0]), float(k[1])
    flags = []
    ev = (f"235 = {kU:.5f} x 238 + {kTh:.5f} x 232 over {int(ok.sum()):,} cycles (1/137.818 = {1 / 137.818:.5f}, so the U part implies "
          f"{100 * (kU * 137.818 - 1):+.1f}% between 235 and 238). Th coefficient uncertainty {sd[1]:.5f}. r(U, Th) = {r_uth:.2f}")
    if kTh <= 0 or sd[1] <= 0 or kTh / sd[1] < 3:
        flags.append("the Th term is not clearly above zero")
    if abs(r_uth) > 0.9:
        flags.append("Th and U move together in these cycles, so the split between them is uncertain: a Th-rich, U-poor line would settle it")
    if abs(kU * 137.818 - 1) > 0.1:
        flags.append("the U coefficient is more than 10% from natural 235/238: check the U isotope ratio of the standards")
    if kTh <= 0:
        return []
    top = th > np.quantile(th, 0.8)
    eff = f"{100 * kTh * np.mean(th[top]) / max(np.mean(y[top]), 1e-9):.1f}% of mass 235 in the Th-rich cycles"
    return [InterfRule("tail_235", "tail", f"Th tail on 235U: subtract {kTh:.5f} x the 232 signal", "edges", edges=[[235, 232, kTh]],
                       basis="measured", evidence=ev, effect=eff, flags=flags)]


# ---- peak tails: a high-count peak lifts the masses above it (Crawford et al. 2025, AutoSpect: about 1e-4 of the peak, tens of mass units wide)
def _fit_tail(y, x, q, nmax=20000):
    """y = a + k x over the cycles, weighted by the counting noise of the fitted level. Returns dict(a, k, se, n), None when it cannot be fitted."""
    ok = np.isfinite(y) & np.isfinite(x)
    y, x = y[ok], x[ok]
    if y.size < 40 or np.ptp(x) <= 0:
        return None
    if y.size > nmax:
        i = np.linspace(0, y.size - 1, nmax).astype(int)
        y, x = y[i], x[i]
    B = np.column_stack([np.ones(y.size), x])
    w = np.ones(y.size)
    k = np.zeros(2)
    for _ in range(4):
        sw = np.sqrt(w)
        k = np.linalg.lstsq(B * sw[:, None], y * sw, rcond=None)[0]
        mu = np.maximum(B @ k, 0.0)
        w = 1.0 / (mu * q + (0.02 * mu) ** 2 + q * q)
    sw = np.sqrt(w)
    Bw = B * sw[:, None]
    res = (y - B @ k) * sw
    dof = max(y.size - 2, 1)
    chi = max(float(res @ res) / dof, 1.0)
    try:
        cov = np.linalg.inv(Bw.T @ Bw) * chi
    except np.linalg.LinAlgError:
        return None
    return dict(a=float(k[0]), k=float(k[1]), se=float(np.sqrt(max(cov[1, 1], 0.0))), n=int(y.size))


def _absent_masses(raw):
    """Masses whose isotopes belong only to elements that do not occur in rock (Tc, Pm, Pu...): they hold no sample signal."""
    out = set()
    for m in raw.masses:
        els = {element_of(l) for l in raw.labels.get(m, [])}
        if els and els <= set(ABSENT_EL) and m not in (83, 129, 131):      # the noble gases are not rare in the gas stream
            out.add(int(m))
    return out


def tail_scan(raw, used=(), zero=(), n_src=8, up=25, down=2, min_src=300.0):
    """How much of each high-count peak shows up at the masses above it (and a little below). Counts of every mass within `down` below to `up`
    above the source are regressed on the source over the cycles, y = a + k x, after the pedestal has been taken off. Empty masses (the
    ones the pedestal is learned on, and masses marked as holding nothing) carry no sample signal of their own, so a clear k there is the
    tail and nothing else. Targets of other elements can follow a source for chemical reasons, so those rows are marked and only the
    empty ones fix a tail. Targets that are isotopes of the source's own element are left out. Columns: source, target, dm (target minus
    source), empty, k (fraction of the source), se, z, mean_target (cps) and share (the tail's part of the target)."""
    q = raw_quantum(raw)
    cols = ["source", "source_el", "target", "dm", "empty", "k", "se", "z", "mean_target", "share", "n"]
    if not np.isfinite(q) or q <= 0 or not len(raw.masses):
        return pd.DataFrame(columns=cols)
    emp = {int(m) for m in used} | {int(m) for m in zero} | _absent_masses(raw)
    sig = {}
    for m in raw.masses:
        c = raw.col(m)
        f = c[np.isfinite(c)]
        if f.size > 20:
            sig[m] = float(f.mean() - np.percentile(f, 5))
    # sources: the highest-count peaks that have an empty mass within reach above them (without one the tail cannot be read)
    cand = [m for m in sorted((m for m in sig if sig[m] > min_src * q), key=lambda m: -sig[m]) if any(1 <= e - m <= up for e in emp if e in sig)][:n_src]
    rows = []
    for s_ in cand:
        xs = raw.col(s_)
        el_s = _element_at(raw, s_) or ""
        for t in raw.masses:
            dm = int(t) - int(s_)
            if dm == 0 or dm < -down or dm > up:
                continue
            el_t = _element_at(raw, t) or ""
            if el_s and el_t == el_s:
                continue
            yt = raw.col(t)
            f = _fit_tail(yt, xs, q)
            if f is None:
                continue
            mt = float(np.nanmean(yt))
            ms = float(np.nanmean(xs[np.isfinite(xs)]))
            rows.append(dict(source=int(s_), source_el=el_s, target=int(t), dm=dm, empty=int(t) in emp, k=f["k"], se=f["se"],
                             z=f["k"] / f["se"] if f["se"] > 0 else np.nan, mean_target=mt, share=f["k"] * ms / max(abs(mt), 1e-9), n=f["n"]))
    return pd.DataFrame(rows, columns=cols)


TAIL_MAX_DM = 10            # the empty masses that fix a tail lie at most this far above the source (further out they are oxides, hydroxides and other peaks)
TAIL_MAX_K = 2e-3           # a tail above 0.2 % of the peak one mass up is not a tail: something else follows the source


def tail_profile(tab, z_min=5.0):
    """One row per source: the tail amplitude at one mass above (k1, fraction of the source) and the decay length (mass units) from the empty
    masses above it that show a tail (k above zero by z_min standard errors): ln k = ln k1 - (dm - 1) / L. Rows with fewer than two such
    masses have no decay length."""
    out = []
    if tab is None or not len(tab):
        return pd.DataFrame(columns=["source", "source_el", "n_empty", "n_clear", "k1", "decay_mass_units", "dm_min", "dm_max", "ok"])
    for s_, g in tab.groupby("source"):
        ge = g[(g.dm >= 1) & (g.dm <= TAIL_MAX_DM) & g["empty"]]
        cl = ge[(ge.k > 0) & (ge.z >= z_min)]
        k1 = L = np.nan
        ok = False
        if len(cl) >= 2 and cl.dm.nunique() >= 2:
            b, a = np.polyfit(cl.dm.to_numpy(float), np.log(cl.k.to_numpy(float)), 1)
            if b < 0 and 0.5 <= -1.0 / b <= 12.0 and float(np.exp(a + b)) <= TAIL_MAX_K:
                L, k1, ok = -1.0 / b, float(np.exp(a + b)), True
        out.append(dict(source=int(s_), source_el=g.source_el.iloc[0], n_empty=int(len(ge)), n_clear=int(len(cl)), k1=k1, decay_mass_units=L,
                        dm_min=int(cl.dm.min()) if len(cl) else 0, dm_max=int(cl.dm.max()) if len(cl) else 0, ok=ok))
    return pd.DataFrame(out)


def tail_check(sess, raw, n_src=10, up=25, down=2):
    """The tail scan on the analysed cycles with the pedestal and gas blank taken off (whether ticked or not, and no tail rule). Returns (scan, profile)."""
    from dataclasses import replace as _rep
    tmp = InterfModel()
    tmp.set_rules([_rep(r, enabled=True) for r in sess.interf.rules if r.kind in ("pedestal", "pedestal_line", "gasblank")])
    X = raw.X.copy()
    tmp.apply(X, {m: [i] for i, m in enumerate(raw.masses)}, raw.line_of)
    rp = RawLines(raw.masses, X, raw.line_of, raw.std_of, raw.rm_of)
    rp.labels, rp.line_names = raw.labels, raw.line_names
    tab = tail_scan(rp, sess.interf.used, sess.interf.zero, n_src=n_src, up=up, down=down)
    return tab, tail_profile(tab)


def est_tails(raw, used=(), zero=(), have=(), min_share=0.0005):
    """Tail rules, one per high-count peak that lifts the empty masses above it by a clear and decaying amount. The rule takes k(dm) x source off
    every mass above the source that is not an isotope of the source's element: k(dm) = k1 exp(-(dm - 1) / L), learned on the empty masses.
    Masses beyond the ones the tail was seen on are marked as extrapolated. `have`: (target, source) pairs that other rules already take
    off. Only targets where the tail is at least min_share of the signal are listed."""
    tab = tail_scan(raw, used, zero)
    prof = tail_profile(tab)
    q = raw_quantum(raw)
    out = []
    for r in prof[prof.ok].itertuples():
        xs = raw.col(r.source)
        ms = float(np.nanmean(xs[np.isfinite(xs)]))
        edges, beyond, ev = [], 0, []
        el_s = r.source_el
        for t in raw.masses:
            dm = int(t) - r.source
            if dm < 1 or dm > 3 * TAIL_MAX_DM or (int(t), r.source) in have:
                continue
            if el_s and _element_at(raw, t) == el_s:
                continue
            k = r.k1 * np.exp(-(dm - 1) / r.decay_mass_units)
            mt = float(np.nanmean(raw.col(t)))
            if k * ms < min_share * max(abs(mt), 1e-9) and k * ms < 3 * q:
                continue
            edges.append([int(t), int(r.source), float(k)])
            beyond += int(dm > r.dm_max + 1 or dm < r.dm_min - 1)
        if not edges:
            continue
        g = tab[(tab.source == r.source) & (tab.dm >= 1) & tab["empty"] & (tab.z >= 3)]
        ev = "; ".join(f"+{int(a.dm)}: {100 * a.k:.4f}% (z {a.z:.0f})" for a in g.sort_values("dm").itertuples())
        fm, ft, eff = _edge_effect(raw, edges)
        flags = []
        if beyond:
            flags.append(f"{beyond} target mass(es) lie beyond the empty masses the tail was seen on: the decay is extended, not measured")
        if not _worth(fm, ft):
            continue
        el = f"{r.source}{el_s}" if el_s else str(r.source)
        out.append(InterfRule(f"tailpk_{r.source}", "tail", f"Tail of {el}: {100 * r.k1:.4f}% one mass up, falling by 1/e per {r.decay_mass_units:.1f} masses, "
                              f"taken off {len(edges)} masses above it", "edges", edges=edges, params=dict(source=r.source, k1=float(r.k1), L=float(r.decay_mass_units)),
                              basis="measured" if not beyond else "assumed", evidence=f"empty masses above {r.source}: {ev}", effect=eff, flags=flags))
    return out


