def _ab(el, m):
    return ABUND.get(el, {}).get(m, 0.0)


# target <- interferer / reference mass of the interferer. The ratio is fixed by the natural abundances (like 204Hg on 204Pb).
ISOBARS = [
    "176Hf<-176Lu/175", "176Hf<-176Yb/173", "176Lu<-176Yb/173", "174Hf<-174Yb/173", "174Yb<-174Hf/177", "180Hf<-180W/182", "180W<-180Hf/177",
    "144Nd<-144Sm/147", "148Nd<-148Sm/147", "150Nd<-150Sm/147", "142Nd<-142Ce/140", "142Ce<-142Nd/146", "144Sm<-144Nd/146", "148Sm<-148Nd/146",
    "150Sm<-150Nd/146", "152Sm<-152Gd/157", "154Sm<-154Gd/157", "152Gd<-152Sm/147", "154Gd<-154Sm/147", "156Gd<-156Dy/161", "158Gd<-158Dy/161",
    "156Dy<-156Gd/157", "158Dy<-158Gd/157", "160Dy<-160Gd/157", "160Gd<-160Dy/161", "162Dy<-162Er/167", "164Dy<-164Er/167", "162Er<-162Dy/161",
    "164Er<-164Dy/161", "168Er<-168Yb/173", "170Er<-170Yb/173", "168Yb<-168Er/167", "170Yb<-170Er/167",
    "138La<-138Ba/137", "138La<-138Ce/140", "138Ce<-138Ba/137", "138Ce<-138La/139", "136Ce<-136Ba/137",
    "87Rb<-87Sr/88", "87Sr<-87Rb/85", "48Ti<-48Ca/44", "46Ti<-46Ca/44", "50Ti<-50V/51", "50Ti<-50Cr/52", "50V<-50Ti/49", "50V<-50Cr/52",
    "50Cr<-50Ti/49", "50Cr<-50V/51", "54Cr<-54Fe/56", "54Fe<-54Cr/52", "58Fe<-58Ni/60", "58Ni<-58Fe/56", "64Zn<-64Ni/62", "64Ni<-64Zn/66",
    "92Zr<-92Mo/95", "94Zr<-94Mo/95", "96Zr<-96Mo/95", "96Zr<-96Ru/101", "92Mo<-92Zr/90", "94Mo<-94Zr/90", "96Mo<-96Zr/90", "96Ru<-96Zr/90",
    "112Cd<-112Sn/118", "114Cd<-114Sn/118", "116Cd<-116Sn/118", "115In<-115Sn/118", "187Os<-187Re/185", "187Re<-187Os/189",
    "184W<-184Os/189", "192Pt<-192Os/189", "190Pt<-190Os/189", "198Pt<-198Hg/202", "198Hg<-198Pt/195", "196Hg<-196Pt/195",
]
_ISO_RE = re.compile(r"^(\d+)([A-Z][a-z]?)<-(\d+)([A-Z][a-z]?)/(\d+)$")
IE2 = {"Ba": 10.00, "Ce": 10.85, "La": 11.06, "Nd": 10.73, "Sm": 11.07, "Gd": 12.09, "Dy": 11.67, "Er": 11.93, "Yb": 12.18, "Hf": 14.9,
       "Zr": 13.13, "Th": 11.9, "U": 11.6, "Pb": 15.03, "W": 16.1, "Sr": 11.03}
DC_KT = 0.8                 # eV, the plasma excitation energy scale used when only one element's doubly charged fraction could be measured
H_PRIOR = 2e-5              # MH+/M+ where it cannot be learned: only a starting value, the standards then choose the strength
# source element, mass of the source ion, mass the hydride lands on (a different element than the source)
HYDRIDES = [("Si", 30, 31), ("Ca", 44, 45), ("V", 51, 52), ("Fe", 54, 55), ("Ni", 62, 63), ("Ni", 64, 65), ("Zn", 64, 65), ("Zn", 68, 69),
            ("Cu", 63, 64), ("Cu", 65, 66), ("Sr", 88, 89), ("Ba", 138, 139), ("Ce", 140, 141), ("Gd", 158, 159), ("Dy", 164, 165), ("Yb", 174, 175)]
GAS_MASSES = [40, 41, 44, 51, 52, 53, 54, 55, 56, 57, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78, 79, 80, 81, 82, 83, 84]


def _edge_effect(raw, edges, mult=1.0):
    """(largest mean share of a target taken off, largest share in the cycles richest in the source, text) for edges [[target, source, c]]."""
    fm, ft, txt = 0.0, 0.0, ""
    for t, s_, c in edges:
        tv, sv = raw.col(t), raw.col(s_)
        if tv is None or sv is None:
            continue
        ok = np.isfinite(tv) & np.isfinite(sv)
        if ok.sum() < 5:
            continue
        tv, sv = tv[ok], sv[ok]
        a = float(np.mean(c * mult * sv) / max(float(np.mean(tv)), 1e-9))
        top = sv > np.quantile(sv, 0.95)
        b = float(np.mean(c * mult * sv[top]) / max(float(np.mean(tv[top])), 1e-9)) if top.any() else 0.0
        if a > fm:
            fm, txt = a, f"{100 * a:.1f}% of mass {t} on average"
        ft = max(ft, b)
    if txt:
        txt += f", up to {100 * ft:.0f}% in the cycles richest in the source"
    return fm, ft, txt


def _worth(fm, ft):
    return fm >= 0.0005 or ft >= 0.01


def est_isobars(raw):
    """Isobars other than 204Hg: the interferer's isotope on the target mass is its clean reference isotope times the natural abundance ratio."""
    out = []
    for spec in ISOBARS:
        m = _ISO_RE.match(spec)
        tm, tel, im, iel, ref = int(m.group(1)), m.group(2), int(m.group(3)), m.group(4), int(m.group(5))
        if not raw.has(tm, ref):
            continue
        a_i, a_r = _ab(iel, im), _ab(iel, ref)
        if a_i <= 0 or a_r <= 0:
            continue
        c = a_i / a_r
        ed = [[tm, ref, float(c)]]
        fm, ft, eff = _edge_effect(raw, ed)
        if not _worth(fm, ft):
            continue
        flags = []
        if fm > 0.05:
            flags.append("large: more than 5% of a mass")
        if ft > 0.5:
            flags.append(f"{iel} is more than half of mass {tm} in its richest cycles: {tel} cannot be read there")
        out.append(InterfRule(f"iso_{im}{iel}_{tm}{tel}", "isobar", f"{im}{iel} on {tm}{tel}: subtract {c:.5f} x the {ref} signal", "edges", edges=ed,
                              params=dict(el=tel), basis="physics",
                              evidence=f"natural abundance ratio {im}{iel}/{ref}{iel} = {a_i:.5f}/{a_r:.5f}", effect=eff, flags=flags))
    return out


def _fit_pair(y, p, s, q, nb=40, seed=1):
    """y = a p + k s over the cycles, weighted by the counting noise of the fitted level, with a bootstrap for the uncertainty of k."""
    ok = np.isfinite(y) & np.isfinite(p) & np.isfinite(s) & (s > 20 * q)
    y, p, s = y[ok], p[ok], s[ok]
    if y.size < 40 or np.ptp(s) <= 0:
        return None
    rng = np.random.default_rng(seed)
    if y.size > 15000:
        i = rng.choice(y.size, 15000, replace=False)
        y, p, s = y[i], p[i], s[i]
    B = np.column_stack([p, s])

    def fit(i):
        k_ = np.linalg.lstsq(B[i], y[i], rcond=None)[0]
        for _ in range(3):
            mu = np.maximum(B[i] @ k_, 0.0)
            w_ = 1.0 / np.sqrt(mu * q + (0.02 * mu) ** 2 + q * q)
            k_ = np.linalg.lstsq(B[i] * w_[:, None], y[i] * w_, rcond=None)[0]
        return k_
    k = fit(slice(None))
    bs = np.array([fit(rng.integers(0, y.size, y.size)) for _ in range(nb)])
    r = float(np.corrcoef(p, s)[0, 1]) if np.ptp(p) > 0 else 1.0
    return dict(a=float(k[0]), k=float(k[1]), sd=float(bs[:, 1].std()), n=int(y.size), r=r)


def _element_at(raw, m):
    for lab in raw.labels.get(m, []):
        el = element_of(lab)
        if el:
            return el
    return None


def _partner(raw, el, t, exclude):
    c = [(ab, mm) for mm, ab in ABUND.get(el, {}).items() if mm != t and mm not in exclude and ab >= 0.02 and raw.has(mm)]
    return max(c)[1] if c else None


def _learn_edge(raw, t, s_, q, exclude):
    """Rate k of 'source s_ adds k x s_ to target t', learned against a clean isotope of the target's own element. None when there is none or
    the fit is not clear: k above zero by three standard deviations, the own-element ratio within the mass bias range, the two not moving together."""
    el = _element_at(raw, t)
    if not el:
        return None
    p = _partner(raw, el, t, exclude)
    if p is None:
        return None
    f = _fit_pair(raw.col(t), raw.col(p), raw.col(s_), q)
    if f is None:
        return None
    rho = _ab(el, t) / _ab(el, p)
    ok = f["k"] > 0 and f["sd"] > 0 and f["k"] / f["sd"] >= 3 and 0.5 * rho <= f["a"] <= 1.6 * rho and abs(f["r"]) < 0.97
    f.update(partner=p, rho=rho, ok=bool(ok), el=el)
    return f


def est_dcharge(raw):
    """Doubly charged ions: M++ lands on M/2. The fraction q(E) = E++/E+ is learned for each element from targets that have a clean isotope of
    their own element (47Ti against 49Ti and 90Zr, say), pooled over the targets. Elements that cannot be measured follow the trend of ln q
    against the second ionisation energy of the elements that could, and are marked assumed."""
    q = raw_quantum(raw)
    if not np.isfinite(q) or q <= 0:
        return []
    cand = {}
    for el in IE2:
        edges = [(i // 2, i) for i, a in ABUND.get(el, {}).items() if i % 2 == 0 and a >= 0.03 and raw.has(i, i // 2)]
        if edges:
            cand[el] = edges
    learned = {}
    for el, edges in cand.items():
        targets = {t for t, _ in edges}
        ks, sds, parts = [], [], []
        for t, i in edges:
            f = _learn_edge(raw, t, i, q, targets)
            if f and f["ok"]:
                ks.append(f["k"])
                sds.append(f["sd"])
                parts.append(f"{t} against {f['partner']}")
        if ks:
            w = 1.0 / np.square(sds)
            qe, se = float(np.sum(w * ks) / np.sum(w)), float(1.0 / np.sqrt(np.sum(w)))
            chi = float(np.sum(w * (np.array(ks) - qe) ** 2) / max(len(ks) - 1, 1)) if len(ks) > 1 else 0.0
            if qe > 0 and qe / se >= 3:
                learned[el] = dict(q=qe, sd=se, parts=parts, chi=chi)
    slope = None
    if len(learned) >= 2:
        xs = np.array([IE2[e] for e in learned])
        ys = np.log([learned[e]["q"] for e in learned])
        if np.ptp(xs) > 0.3:
            b, a0 = np.polyfit(xs, ys, 1)
            if b < 0:
                slope = (float(a0), float(b), "fitted on " + ", ".join(learned))
    elif len(learned) == 1:
        e = next(iter(learned))
        slope = (float(np.log(learned[e]["q"]) + IE2[e] / DC_KT), -1.0 / DC_KT, f"anchored on {e} with kT = {DC_KT} eV")
    out = []
    for el, edges in cand.items():
        flags = []
        if el in learned:
            L = learned[el]
            qe, basis = L["q"], "measured"
            ev = f"{el}++/{el}+ = {100 * qe:.3f}% (+/- {100 * L['sd']:.3f}%), learned from " + "; ".join(L["parts"])
            if L["chi"] > 3:
                flags.append("the targets disagree on the rate: something else sits on one of them")
        elif slope is not None:
            qe, basis = float(np.exp(slope[0] + slope[1] * IE2[el])), "assumed"
            ev = (f"no clean isotope to learn it on: {100 * qe:.3f}% from the trend of ln(M++/M+) with the second ionisation energy ({IE2[el]} eV), "
                  f"{slope[2]}")
            flags.append("assumed rate: the standards decide whether it helps, and the tuning sets its strength")
        else:
            continue
        ed = [[t, i, float(qe)] for t, i in edges]
        fm, ft, eff = _edge_effect(raw, ed, 10.0 if basis == "assumed" else 1.0)
        if not _worth(fm, ft):
            continue
        fm1, ft1, eff1 = _edge_effect(raw, ed)
        if fm1 > 0.05:
            flags.append("large: more than 5% of a mass")
        tg = ", ".join(f"{i}++ on {t}" for t, i in edges)
        out.append(InterfRule(f"dc_{el}", "doubly charged", f"{el} doubly charged ions ({tg}): {100 * qe:.3f}% of each isotope", "edges", edges=ed,
                              params=dict(el=el, q=qe), basis=basis, evidence=ev, effect=eff1 or eff, flags=flags))
    return out


def est_hydrides(raw):
    """Hydrides on a different element (30SiH on 31P, 44CaH on 45Sc, 158GdH on 159Tb, 174YbH on 175Lu and so on). Where the target has a clean isotope
    of its own element the rate is learned. Where it has none (the targets here are mostly mono-isotopic) a starting rate is used and
    marked assumed: the standards decide whether it is ticked and the tuning sets its strength over a wide range."""
    q = raw_quantum(raw)
    if not np.isfinite(q) or q <= 0:
        return []
    by_el = {}
    for el, s_, t in HYDRIDES:
        if raw.has(s_, t):
            by_el.setdefault(el, []).append((t, s_))
    out = []
    for el, edges in by_el.items():
        ed, notes, measured = [], [], 0
        for t, s_ in edges:
            f = _learn_edge(raw, t, s_, q, {s_})
            if f and f["ok"]:
                ed.append([t, s_, float(f["k"])])
                measured += 1
                notes.append(f"{s_}H on {t}: {100 * f['k']:.4f}% (against {f['partner']})")
            else:
                ed.append([t, s_, H_PRIOR])
        fm, ft, eff = _edge_effect(raw, ed, 10.0 if measured < len(ed) else 1.0)
        if not _worth(fm, ft):
            continue
        basis = "measured" if measured == len(ed) else "assumed"
        flags = [] if basis == "measured" else [f"assumed rate ({H_PRIOR:.0e}) on {len(ed) - measured} target(s) with no clean isotope to learn it on: the standards decide, the tuning sets the strength"]
        tg = ", ".join(f"{s_}{el}H on {t}" for t, s_ in edges)
        fm1, ft1, eff1 = _edge_effect(raw, ed)
        out.append(InterfRule(f"hy_{el}", "hydride", f"{el} hydrides ({tg})", "edges", edges=ed, params=dict(el=el), basis=basis,
                              evidence="; ".join(notes) if notes else "starting rate, not measured", effect=eff1 or eff, flags=flags))
    return out


def _gas_levels(raw, masses, frac=0.05, nmin=10):
    """Per line, the level of each mass in the cycles with almost no ablation (total counts under `frac` of the line's 95th percentile)."""
    out = []
    for lid in np.unique(raw.line_of):
        rows = np.flatnonzero(raw.line_of == lid)
        t = raw.tic[rows]
        hi = np.nanpercentile(t, 95) if t.size else 0.0
        low = rows[t < frac * hi] if hi > 0 else rows[:0]
        if low.size >= nmin:
            out.append({m: float(np.nanmedian(raw.col(m)[low])) for m in masses})
    return out


def est_gasblank(raw, frac=0.05, nmin=10):
    """Argides, argon-based and other gas polyatomics (ArO on 56Fe, ArC on 52Cr, ArCl on 75As, Ar2 on 80Se...): they come from the gas, not the
    sample, so they are present in the cycles between ablation. The level of each such mass in a line's own laser-off cycles is taken off that line."""
    masses = [m for m in GAS_MASSES if raw.has(m)]
    q = raw_quantum(raw)
    if not masses or not np.isfinite(q):
        return []
    lv = _gas_levels(raw, masses, frac, nmin)
    if not lv:
        return []
    mean = {m: float(np.mean([d[m] for d in lv])) for m in masses}
    use = [m for m in masses if mean[m] > 2 * q]
    if not use:
        return []
    top = max(use, key=lambda m: mean[m])
    ev = f"{len(lv)} line(s) have at least {nmin} laser-off cycles. Mean level: " + ", ".join(f"{m}: {mean[m]:,.0f} cps" for m in sorted(use, key=lambda m: -mean[m])[:6])
    return [InterfRule("gasblank", "gas blank", f"Gas blank at {len(use)} masses (argides and other gas polyatomics): each line's own level between ablation, taken off",
                       "gasblank", params=dict(masses=use, frac=frac, min=nmin), basis="measured", evidence=ev, effect=f"largest at mass {top}: {mean[top]:,.0f} cps")]


def est_extra(raw):
    """All the corrections beyond the pedestal, 204Hg, oxides and the Th tail. A family that fails is left out, never the whole analysis."""
    out = []
    for f in (est_isobars, est_dcharge, est_hydrides, est_gasblank):
        try:
            out += f(raw)
        except Exception:
            pass
    return out


def _pair_wls(y, p, s, q):
    """y = a p + k s over the cycles of one line, weighted by the counting noise of the fitted level. (k, sd of k) or None when the line cannot say:
    too few cycles with the source present, or the partner and the source move together."""
    ok = np.isfinite(y) & np.isfinite(p) & np.isfinite(s) & (s > 20 * q)
    if ok.sum() < 40:
        return None
    y, p, s = y[ok], p[ok], s[ok]
    if np.ptp(s) <= 0 or np.ptp(p) <= 0:
        return None
    if abs(float(np.corrcoef(p, s)[0, 1])) > 0.97:
        return None
    B = np.column_stack([p, s])
    k_ = np.linalg.lstsq(B, y, rcond=None)[0]
    for _ in range(2):
        mu = np.maximum(B @ k_, 0.0)
        w_ = 1.0 / np.sqrt(mu * q + (0.02 * mu) ** 2 + q * q)
        k_ = np.linalg.lstsq(B * w_[:, None], y * w_, rcond=None)[0]
    r = (y - B @ k_) * w_
    chi = max(float(np.sum(r * r)) / max(len(y) - 2, 1), 1.0)
    try:
        cov = np.linalg.inv((B * w_[:, None]).T @ (B * w_[:, None])) * chi
    except np.linalg.LinAlgError:
        return None
    sd = float(np.sqrt(max(cov[1, 1], 0.0)))
    return float(k_[1]), sd


def _rule_line_est(r, V, rows, q):
    """For one line, the rate of each edge of a rule against its partner isotope, as a multiple of the rule's own rate: [(ratio, sd)]."""
    parts = r.params.get("partners") or {}
    out = []
    for t, s_, c in r.edges:
        p = parts.get(str(t))
        if p is None or c <= 0 or t not in V or p not in V or s_ not in V:
            continue
        f = _pair_wls(V[t][rows], V[p][rows], V[s_][rows], q)
        if f is not None and f[1] > 0:
            out.append((f[0] / c, f[1] / c))
    return out


def _combine_est(ests, tau):
    """One multiplier for a rule on one line from its edges (inverse variance), pulled towards 1 by a prior of sd tau: a line that says little
    keeps the session rate. Returns (multiplier, sd of the estimate before the pull)."""
    if not ests:
        return 1.0, float("inf")
    w = np.array([1.0 / e[1] ** 2 for e in ests])
    m = float(np.sum(w * np.array([e[0] for e in ests])) / np.sum(w))
    sd = float(1.0 / np.sqrt(np.sum(w)))
    pw = 1.0 / tau ** 2
    return float(np.clip((pw * 1.0 + m * (1.0 / sd ** 2)) / (pw + 1.0 / sd ** 2), 0.2, 5.0)), sd


def _line_mult(r, V, groups, tau, q, sets=None):
    """Multiplier of the rate of a rule, one per row, from each line's own cycles (a line is a value of groups, or all rows when it is None)."""
    n = len(next(iter(V.values())))
    out = np.ones(n)
    if sets is None:
        sets = _line_sets(groups, n)
    for rows in sets:
        m, _sd = _combine_est(_rule_line_est(r, V, rows, q), tau)
        out[rows] = m
    return out


LS_FAMILIES = ("ox_", "dc_", "hy_")


def est_linescale(raw, rules, tau=0.5):
    """Let the rate of each oxide, doubly charged and hydride correction follow the line.

    Rates move with ablation conditions and matrix, so a rate learned over the session is too high on some lines and too low on
    others. On each line the rate is read again from that line's own cycles (the target against a clean isotope of its own
    element, as when the rate was learned) and pulled towards the session rate in proportion to how little the line can say. It
    works for the unknowns as well as the standards, because it needs no accepted values.

    Adds the partner isotopes to the rules and returns one rule that switches the behaviour on, or [] when no line-to-line change
    shows."""
    q = raw_quantum(raw)
    if not np.isfinite(q) or q <= 0:
        return []
    cand = [r for r in rules if r.kind == "edges" and r.id.startswith(LS_FAMILIES) and r.edges]
    if not cand:
        return []
    lids = np.unique(raw.line_of)
    V = {m: raw.X[:, i] for i, m in enumerate(raw.masses)}
    used, rows_ev, ratios, sds = [], [], [], []
    for r in cand:
        targets = {int(t) for t, _s, _c in r.edges}
        srcs = {int(s_) for _t, s_, _c in r.edges if isinstance(s_, (int, np.integer))}
        parts = {}
        for t, s_, c in r.edges:
            el = _element_at(raw, t)
            pm = _partner(raw, el, t, targets | srcs) if el else None
            if pm is not None:
                parts[str(int(t))] = int(pm)
        if not parts:
            continue
        r.params = dict(r.params or {}, partners=parts, q=float(q))
        per = []
        for lid in lids:
            rows = np.flatnonzero(raw.line_of == lid)
            m, sd = _combine_est(_rule_line_est(r, V, rows, q), 1e6)
            if np.isfinite(sd):
                per.append((m, sd))
        if len(per) >= 6:
            used.append(r.id)
            ratios += [a for a, _ in per]
            sds += [b for _, b in per]
            rows_ev.append(f"{r.id}: {len(per)} lines")
    if not used:
        return []
    ratios, sds = np.array(ratios), np.array(sds)
    spread = float(1.4826 * np.median(np.abs(ratios - np.median(ratios))))
    noise = float(np.median(sds))
    flags = []
    if spread < 1.2 * noise:
        flags.append("the rates differ from line to line by no more than the counting noise of a line: this is not needed")
    return [InterfRule("linescale", "line rates", "Rate of the oxide, doubly charged and hydride corrections read again on each line (pulled towards the session rate)",
                       "linescale", params=dict(tau=float(tau), q=float(q)), basis="measured",
                       evidence=f"{', '.join(rows_ev[:6])}{'...' if len(rows_ev) > 6 else ''}. Spread of the line rates (robust) {spread:.2f} of the session rate, counting noise of one line {noise:.2f}",
                       effect="", flags=flags)]


def _apply_gasblank(params, V, tic, groups, sets=None):
    fr, nmin = params.get("frac", 0.05), params.get("min", 10)
    n = len(tic)
    gl = sets if sets is not None else _line_sets(groups, n)
    for rows in gl:
        t = tic[rows]
        hi = np.nanpercentile(t, 95) if t.size else 0.0
        if not hi > 0:
            continue
        low = t < fr * hi
        if low.sum() < nmin:
            continue
        for m in params.get("masses", []):
            if m in V:
                lv = np.nanmedian(V[m][rows][low])
                if np.isfinite(lv):
                    V[m][rows] = V[m][rows] - lv


# ---- oxide level from the isotope patterns
# approximate M-O bond energies (eV). Oxide ions form more readily where the bond is strong, roughly exp(0.75 x bond energy)
OX_BDE = {"La": 8.23, "Ce": 8.21, "Pr": 7.55, "Nd": 7.35, "Sm": 5.80, "Eu": 4.80, "Gd": 7.35, "Tb": 7.30, "Dy": 6.35, "Ho": 6.30,
          "Er": 6.28, "Tm": 5.40, "Yb": 4.20, "Lu": 6.88, "Hf": 8.30, "Ta": 8.24, "Ba": 5.67, "W": 7.0}
OX_K = 0.75
PAT_EL = ["La", "Ce", "Pr", "Nd", "Sm", "Eu", "Gd", "Tb", "Dy", "Ho", "Er", "Tm", "Yb", "Lu", "Hf", "Ta", "Ba", "W"]


def ox_prior(el, r_hf):
    return r_hf * float(np.exp(OX_K * (OX_BDE[el] - OX_BDE["Hf"])))


def _pat_design(masses, lam, r_hf, beta):
    A = np.zeros((len(masses), len(PAT_EL)))
    f = np.exp(beta * (np.asarray(masses, float) - 150.0))
    for j, el in enumerate(PAT_EL):
        ab = ISO_AB[el]
        r = r_hf if el == "Hf" else lam * ox_prior(el, r_hf)         # Hf is the anchor and is not scaled
        A[:, j] = [(ab.get(m, 0.0) + r * ab.get(m - 16, 0.0)) for m in masses]
    return A * f[:, None]


def fit_oxide_scale(raw, r_hf, max_lines=12):
    """One number: how large the rare-earth, Ta, Ba and W oxides are compared with the bond-strength prior anchored on Hf
    (1 = the prior). Fitted line by line on the summed counts of the ablation cycles with a free mass bias and non-negative amounts
    of each element. Returns dict(lam, spread, n, gain) or None."""
    from scipy.optimize import nnls
    masses = [m for m in raw.masses if 134 <= m <= 197]
    if len(masses) < 30 or not (r_hf and r_hf > 0):
        return None
    idx = [raw.idx[m] for m in masses]
    lids = np.unique(raw.line_of[raw.std_of]) if raw.std_of.any() else np.unique(raw.line_of)
    q = raw_quantum(raw)
    betas = np.arange(-0.03, 0.0801, 0.005)
    lams = [0.0, 0.1, 0.2, 0.35, 0.5, 0.7, 1.0, 1.4, 2.0, 2.8, 4.0, 5.6, 8.0]
    out = []
    for lid in lids:
        rows = raw.line_of == lid
        tic = raw.tic[rows]
        win = tic >= 0.3 * np.nanpercentile(tic, 95)
        if win.sum() < 5:
            continue
        y = np.nansum(raw.X[rows][win][:, idx], axis=0)
        ree = sum(y[masses.index(m)] for m in (139, 140, 141, 159, 165, 169, 175) if m in masses)
        if ree < 2000 * q * win.sum() / 50:
            continue
        w = 1.0 / np.sqrt(np.maximum(y, 0) * q * win.sum() ** 0 + (0.02 * y) ** 2 + q * q)
        best = (np.inf, 0.0, 0.0)
        chi0 = np.inf
        bx = None
        for b in betas:
            for lm in lams:
                A = _pat_design(masses, lm, r_hf, b)
                x, _ = nnls(A * w[:, None], y * w)
                c = float(np.sum(((y - A @ x) * w) ** 2))
                if lm == 0 and c < chi0:
                    chi0 = c
                if c < best[0]:
                    best, bx = (c, lm, b), x
        ree = np.array([bx[PAT_EL.index(e)] for e in PAT_EL if e not in ("Hf", "Ta", "Ba", "W")])
        if (ree >= 0.05 * ree.max()).sum() < 10 or best[1] >= lams[-1]:
            continue                      # a line poor in the light rare earths (zircon) says nothing about their oxides. The edge of the grid is no answer
        out.append(dict(lam=best[1], beta=best[2], chi=best[0], chi0=chi0, gain=1 - best[0] / max(chi0, 1e-12)))
        if len(out) >= max_lines:
            break
    if not out:
        return None
    lam = np.array([o["lam"] for o in out])
    med = float(np.median(lam))
    spread = float(1.4826 * np.median(np.abs(lam - med)) / max(med, 1e-9)) if len(lam) > 2 else float("nan")
    return dict(lam=med, spread=spread, n=len(out), gain=float(np.median([o["gain"] for o in out])),
                beta=float(np.median([o["beta"] for o in out])), lines=out)


# ---- does a correction help? test on the standards
VAL_MASS = {"Ti": 49, "Y": 89, "Nb": 93, "La": 139, "Ce": 140, "Pr": 141, "Nd": 146, "Sm": 147, "Eu": 153, "Gd": 157, "Tb": 159, "Dy": 163,
            "Ho": 165, "Er": 167, "Tm": 169, "Yb": 172, "Lu": 175, "Hf": 178, "Ta": 181, "Th": 232, "U": 238}


def _std_subset(raw):
    s = raw.std_of & (raw.rm_of != "")
    r = RawLines(raw.masses, raw.X[s], raw.line_of[s], raw.std_of[s], raw.rm_of[s])
    r.labels, r.line_names = raw.labels, raw.line_names
    return r


def _el_of(lab):
    return re.sub(r"[^A-Za-z].*$", "", re.sub(r"^\d+", "", str(lab)))


def _val_items(rs):
    """{mass: element} of the masses the standards test looks at: the named ones, plus every mass that carries one element only."""
    items = {m: el for el, m in VAL_MASS.items() if m in rs.idx}
    for m, labs in rs.labels.items():
        els = {_el_of(l) for l in labs}
        if len(els) == 1 and m in rs.idx and m not in items:
            items[m] = next(iter(els))
    return items


def _rm_kind(rm):
    return rm.split("_")[0] if "_" in rm else rm


def _line_stats(rs):
    """{line: (reference material, mean of every column over the ablation cycles, sum of every column over them)}: the cycles with the ion
    current at 30% or more of the line's 95th percentile. Lines with fewer than 5 such cycles are left out. Found once per set of standards,
    since every test below reads the same numbers."""
    lid = rs.line_of
    order = np.argsort(lid, kind="stable")
    ul, st = np.unique(lid[order], return_index=True)
    en = np.append(st[1:], len(order))
    out = {}
    with np.errstate(all="ignore"), warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for u, a, b in zip(ul, st, en):
            idx = order[a:b]
            tic = rs.tic[idx]
            w = tic >= 0.3 * np.nanpercentile(tic, 95)
            if w.sum() < 5:
                continue
            Xw = rs.X[idx][w]
            out[u] = (str(rs.rm_of[idx[0]]), np.nanmean(Xw, axis=0), np.nansum(Xw, axis=0))
    return out


def rm_intercepts(sess, rs, items=None, min_rm=4, min_span=6.0, stats=None):
    """cps = S x ppm + I across the reference materials of one kind, one mass at a time. For a clean mass I is zero. A pedestal, a blank
    or an interference shows as I. Needs four or more reference materials whose concentrations differ by a factor of six or more."""
    items = items or _val_items(rs)
    win = stats if stats is not None else _line_stats(rs)
    out = []
    for m, el in items.items():
        pts = {}
        for lid, (rm, mean_, _sum) in win.items():
            ppm = sess.rm_table.get(rm, {}).get(el)
            if ppm and ppm > 0:
                pts.setdefault(rm, []).append((ppm, float(mean_[rs.idx[m]])))
        by_kind = {}
        for rm, v in pts.items():
            by_kind.setdefault(_rm_kind(rm), []).append((rm, v[0][0], float(np.median([c for _, c in v]))))
        for kind, L in by_kind.items():
            if len(L) < min_rm:
                continue
            ppm = np.array([x[1] for x in L])
            c = np.array([x[2] for x in L])
            if ppm.max() / ppm.min() < min_span or np.any(c <= 0):
                continue
            w_ = 1.0 / (0.05 * c + 50.0) ** 2

            def fit(idx):
                A = np.column_stack([ppm[idx], np.ones(len(idx))]) * np.sqrt(w_[idx])[:, None]
                return np.linalg.lstsq(A, c[idx] * np.sqrt(w_[idx]), rcond=None)[0]
            S, I = fit(np.arange(len(L)))
            jk = [fit(np.delete(np.arange(len(L)), k))[1] for k in range(len(L))]
            se = float(np.sqrt((len(L) - 1) / len(L) * np.sum((np.array(jk) - np.mean(jk)) ** 2)))
            out.append(dict(mass=m, element=el, kind=kind, n_rm=len(L), S=float(S), intercept=float(I), se=se, cps_min=float(c.min()),
                            rel=float(I / c.min())))
    return pd.DataFrame(out)


def _val_pairs(sess, rs, items, min_cps=300.0, stats=None):
    """{(mass, rm): (log bias against the other reference materials of the same kind, mean cps)} for the standards rs."""
    sens, cps = {}, {}
    for lid, (rm, mean_, _sum) in (stats if stats is not None else _line_stats(rs)).items():
        tab = sess.rm_table.get(rm, {})
        for m, el in items.items():
            ppm = tab.get(el)
            if ppm and ppm > 0:
                c = float(mean_[rs.idx[m]])
                if c > 0:
                    sens.setdefault((m, rm), []).append(c / ppm)
                    cps.setdefault((m, rm), []).append(c)
    out = {}
    for m in {k[0] for k in sens}:
        rms = [rm for (mm, rm) in sens if mm == m and np.mean(cps[(mm, rm)]) >= min_cps]
        for rm in rms:
            peers = [r for r in rms if r != rm and _rm_kind(r) == _rm_kind(rm)]
            if peers:
                out[(m, rm)] = (float(np.log(np.median(sens[(m, rm)]) / np.median([np.median(sens[(m, r)]) for r in peers]))), float(np.mean(cps[(m, rm)])))
    return out


def _cpb_rows(sess, c4):
    """Per reference material, with the sums [204, 206, 207, 238] over its lines: errors of 206/238 and 207/206 after the 204 correction
    (common Pb of the Stacey-Kramers composition at the accepted age) and before it."""
    out = []
    for rm, (s4, s6, s7, s8) in c4.items():
        a68, a76 = accepted_upb(sess, rm, "206Pb/238U"), accepted_upb(sess, rm, "207Pb/206Pb")
        if not a68 or s8 <= 0 or s6 <= 0:
            continue
        t = float(age_ma(a68, "238"))
        r64, r74 = sk_common_64_74(min(max(t, 0.0), 3600.0))
        s6c, s7c = s6 - r64 * s4, s7 - r74 * s4
        row = dict(rm=rm, s4=s4, s6=s6, f206=100 * r64 * s4 / s6, e68=s6 / s8 / a68 - 1, e76=(s7 / s6 / a76 - 1) if a76 else np.nan,
                   e68c=s6c / s8 / a68 - 1 if s6c > 0 else np.nan, e76c=(s7c / s6c / a76 - 1) if a76 and s6c > 0 and s7c > 0 else np.nan)
        out.append(row)
    return out


def _cpb_error(sess, c4):
    """Mean size of the 206/238 and 207/206 errors after the 204 correction, each centred on the median over reference materials (percent)."""
    rows = _cpb_rows(sess, c4)
    v = []
    for k in ("e68c", "e76c"):
        e = np.array([r[k] for r in rows if np.isfinite(r[k])])
        if len(e) >= 3:
            v += list(np.abs(np.log1p(e) - np.median(np.log1p(e))))
    return float(100 * np.mean(v)) if v else float("nan")


def norm_test(sess, raw, model=None, min_ppm=100.0, max_candidates=60):
    """Does dividing by something of known concentration help? Each reference material's cps per ppm is compared with the other reference
    materials of its kind (the same measure as the standards test), with no normalisation, with the sum of all ions, and with each internal
    standard candidate: every mass whose element has 100 ppm or more in most reference materials, and the summed isotopes of elements with
    known abundances. Pairs are the same for all candidates. Returns a table sorted by mean size of the bias."""
    model = model or sess.interf
    rs = _std_subset(raw)
    X = rs.X.copy()
    model.apply(X, {m: [i] for i, m in enumerate(rs.masses)}, rs.line_of)
    r2 = RawLines(rs.masses, X, rs.line_of, rs.std_of, rs.rm_of)
    r2.labels = rs.labels
    items = _val_items(r2)
    lines = []
    for lid in np.unique(r2.line_of):
        rows = r2.line_of == lid
        tic = r2.tic[rows]
        w = tic >= 0.3 * np.nanpercentile(tic, 95)
        if w.sum() >= 5:
            lines.append((str(r2.rm_of[rows][0]), np.nanmean(r2.X[rows][w], axis=0), float(np.nanmean(tic[w]))))
    if len(lines) < 4:
        raise ValueError("The test needs standard lines of at least two reference materials")
    rms = {rm for rm, _, _ in lines}

    def biases(norm_cols=None, el=None, use_tic=False):
        sens = {}
        for rm, v, t in lines:
            tab = sess.rm_table.get(rm, {})
            if use_tic:
                d, pis = t, 1.0
            elif norm_cols is not None:
                d = float(np.nansum([v[r2.idx[m]] for m in norm_cols]))
                pis = tab.get(el)
                if not pis or pis < min_ppm or d <= 0:
                    continue
            else:
                d, pis = 1.0, 1.0
            for m, e in items.items():
                if norm_cols is not None and m in norm_cols:
                    continue
                ppm = tab.get(e)
                c = v[r2.idx[m]]
                if ppm and ppm > 0 and c > 0:
                    sens.setdefault((m, rm), []).append((c / d) / (ppm / pis))
        out = {}
        for m in {k[0] for k in sens}:
            have = [rm for (mm, rm) in sens if mm == m]
            for rm in have:
                peers = [r for r in have if r != rm and _rm_kind(r) == _rm_kind(rm)]
                if peers:
                    out[(m, rm)] = float(np.log(np.median(sens[(m, rm)]) / np.median([np.median(sens[(m, r)]) for r in peers])))
        return out
    base = biases()
    cands = [("sum of all ions", None, None, True)]
    for el, ab in ISO_AB.items():
        ms = [m for m in ab if m in r2.idx]
        have = [rm for rm in rms if sess.rm_table.get(rm, {}).get(el, 0) >= min_ppm]
        if len(ms) >= 2 and len(have) >= max(3, 0.4 * len(rms)):
            cands.append((f"{el} isotopes {ms[0]} to {ms[-1]}", ms, el, False))
    singles = []
    for m, el in items.items():
        have = [rm for rm in rms if sess.rm_table.get(rm, {}).get(el, 0) >= min_ppm]
        if len(have) >= max(3, 0.4 * len(rms)):
            v = np.nanmean([ln[1][r2.idx[m]] for ln in lines])
            singles.append((v, m, el))
    for v, m, el in sorted(singles, reverse=True)[:max_candidates]:
        cands.append((f"{el} {m}", [m], el, False))
    rows = []
    for name, cols, el, use_tic in cands:
        b = biases(cols, el, use_tic)
        com = [k for k in b if k in base]
        if len(com) < 20:
            continue
        a = np.array([abs(b[k]) for k in com]) * 100
        a0 = np.array([abs(base[k]) for k in com]) * 100
        rows.append(dict(normalise_to=name, pairs=len(com), mean_bias=float(a.mean()), mean_bias_without=float(a0.mean()), median_bias=float(np.median(a)),
                         median_bias_without=float(np.median(a0)), better_share=float(np.mean(a < a0)), change_mean=float(a.mean() - a0.mean())))
    df = pd.DataFrame(rows)
    return df.sort_values("change_mean").reset_index(drop=True) if len(df) else df


# ---- which normaliser is steadiest, and is Zr usable as a stoichiometric anchor
ZR_AB = {90: .5145, 91: .1122, 92: .1715, 94: .1738, 96: .0280}
HF_AB = {176: .0526, 177: .1860, 178: .2728, 179: .1362, 180: .3508}
NORM_SETS = [("Hf 177+178+179", {177: 1, 178: 1, 179: 1}), ("Hf 178", {178: 1}), ("U 238", {238: 1}), ("Th 232", {232: 1}),
             ("Zr 90", {90: 1}), ("Zr 91", {91: 1}), ("Zr 92", {92: 1}), ("Zr 94", {94: 1}), ("Zr 96", {96: 1}), ("Zr 92+94+96", {92: 1, 94: 1, 96: 1}),
             ("Si 28", {28: 1}), ("Si 29+30", {29: 1, 30: 1}), ("Al 27", {27: 1}), ("Ca 43", {43: 1}), ("Y 89", {89: 1}), ("P 31", {31: 1}),
             ("Ti 49", {49: 1}), ("Ce 140", {140: 1})]


def _std_line_means(raw, model):
    """Windowed mean cps of every mass for every standard line, with the ticked corrections applied: {rm: array(lines x masses)}."""
    rs = _std_subset(raw)
    X = rs.X.copy()
    model.apply(X, {m: [i] for i, m in enumerate(rs.masses)}, rs.line_of)
    out = {}
    for lid in np.unique(rs.line_of):
        rows = rs.line_of == lid
        tic = np.nansum(X[rows], axis=1)
        w = tic >= 0.3 * np.nanpercentile(tic, 95)
        if w.sum() >= 5:
            out.setdefault(str(rs.rm_of[rows][0]), []).append(np.nanmean(X[rows][w], axis=0))
    return {k: np.array(v) for k, v in out.items()}, rs


def zr_check(sess, raw, model=None, max_cv=8.0, min_lines=5):
    """Is each Zr isotope usable as the stoichiometric anchor? Hf and U follow each other to a few percent from line to line, so the ratio of a
    Zr isotope to Hf should be as steady in a zircon standard. Shown per isotope: its mean signal, the line-to-line spread of its ratio to Hf
    (median over the standards with enough lines), and the attenuation, the Zr/Hf signal ratio divided by the Zr/Hf ratio in the reference
    material (1 when Zr is seen as strongly as Hf, small when the instrument holds Zr back)."""
    model = model or sess.interf
    L, rs = _std_line_means(raw, model)
    idx = rs.idx
    hf = [m for m in (177, 178, 179) if m in idx]
    if not hf:
        return pd.DataFrame(columns=["mass", "mean_cps", "cv_ratio_to_hf_pct", "attenuation", "usable"])
    rows = []
    for m in ZR_AB:
        if m not in idx:
            continue
        cvs, att, cps = [], [], []
        for rm, V in L.items():
            d = np.nansum(V[:, [idx[x] for x in hf]], axis=1)
            c = V[:, idx[m]]
            cps.append(float(np.nanmean(c)))
            tab = sess.rm_table.get(rm, {})
            if len(V) >= min_lines and (d > 0).all() and (c > 0).all():
                y = c / d
                cvs.append(100 * np.std(y, ddof=1) / np.mean(y))
            if tab.get("Zr") and tab.get("Hf") and np.nanmean(d) > 0:
                zr_el = np.nanmean(c) / ZR_AB[m]
                hf_el = np.nanmean(d) / sum(HF_AB[x] for x in hf)
                att.append((zr_el / hf_el) / (tab["Zr"] / tab["Hf"]))
        if not cps:
            continue
        cv = float(np.median(cvs)) if cvs else float("nan")
        rows.append(dict(mass=m, mean_cps=float(np.mean(cps)), cv_ratio_to_hf_pct=cv, attenuation=float(np.median(att)) if att else float("nan"),
                         usable=bool(np.isfinite(cv) and cv <= max_cv)))
    return pd.DataFrame(rows, columns=["mass", "mean_cps", "cv_ratio_to_hf_pct", "attenuation", "usable"])


def norm_precision(sess, raw, model=None, min_cps=3000.0, min_lines=5):
    """Which normaliser makes the lines of one reference material agree best with each other? For every standard with five or more lines
    and every single-element mass above min_cps, the spread of the line values (percent) with and without dividing by the candidate.
    Needs no concentrations, so the reference values do not limit it. The stoichiometric candidate is the Zr plus Hf total from the
    steadiest Zr isotope (when none is steady it is shown anyway). Returns a table sorted by the change in spread."""
    model = model or sess.interf
    L, rs = _std_line_means(raw, model)
    L = {k: v for k, v in L.items() if len(v) >= min_lines}
    if not L:
        raise ValueError(f"Needs {min_lines} or more lines of at least one reference material")
    idx = rs.idx
    items = _val_items(rs)
    cands = [("sum of all ions", None)]
    for name, w in NORM_SETS:
        if all(m in idx for m in w):
            cands.append((name, w))
    zc = zr_check(sess, raw, model)
    if len(zc) and zc["cv_ratio_to_hf_pct"].notna().any():
        zbest = int(zc.sort_values("cv_ratio_to_hf_pct").iloc[0]["mass"])
        hf = [m for m in (177, 178, 179) if m in idx]
        if hf:
            cands.append((f"Zr + Hf total (Zr {zbest}, stoichiometric)", {zbest: 1.0 / ZR_AB[zbest], **{m: 1.0 / sum(HF_AB[x] for x in hf) for m in hf}}))

    def spread(w):
        out = {}
        for rm, V in L.items():
            if w is None:
                d = np.nansum(V, axis=1)
            else:
                d = np.nansum([V[:, idx[m]] * k for m, k in w.items()], axis=0)
            if not (d > 0).all():
                continue
            for m in items:
                if w is not None and m in w:
                    continue
                c = V[:, idx[m]]
                if np.nanmean(c) < min_cps or not (c > 0).all():
                    continue
                out[(rm, m)] = (100 * np.std(c / d, ddof=1) / np.mean(c / d), 100 * np.std(c, ddof=1) / np.mean(c))
        return out
    rows = []
    for name, w in cands:
        sp = spread(w)
        if len(sp) < 8:
            continue
        a = np.array([v[0] for v in sp.values()])
        a0 = np.array([v[1] for v in sp.values()])
        rows.append(dict(normalise_to=name, combos=len(sp), spread=float(np.median(a)), spread_without=float(np.median(a0)),
                         change=float(np.median(a) - np.median(a0)), better_share=float(np.mean(a < a0))))
    df = pd.DataFrame(rows, columns=["normalise_to", "combos", "spread", "spread_without", "change", "better_share"])
    return df.sort_values("change").reset_index(drop=True) if len(df) else df


def pb204_report(sess, raw, model=None):
    """What 204 holds after the ticked corrections, and what correcting for common Pb with it does to each reference material:
    the 204 signal, the common Pb it implies (percent of 206Pb), and the errors of 206Pb/238U and 207Pb/206Pb before and after."""
    model = model or sess.interf
    rs = _std_subset(raw)
    if not rs.has(204, 206, 207, 238):
        return pd.DataFrame()
    X = rs.X.copy()
    model.apply(X, {m: [i] for i, m in enumerate(rs.masses)}, rs.line_of)
    r2 = RawLines(rs.masses, X, rs.line_of, rs.std_of, rs.rm_of)
    c4, nl, cyc = {}, {}, {}
    for lid in np.unique(r2.line_of):
        rows = r2.line_of == lid
        rm = str(r2.rm_of[rows][0])
        tic = r2.tic[rows]
        win = tic >= 0.3 * np.nanpercentile(tic, 95)
        if win.sum() < 5:
            continue
        c4.setdefault(rm, np.zeros(4))
        c4[rm] += [float(np.nansum(r2.col(m)[rows][win])) for m in (204, 206, 207, 238)]
        nl[rm] = nl.get(rm, 0) + 1
        cyc[rm] = cyc.get(rm, 0) + int(win.sum())
    rows = _cpb_rows(sess, c4)
    return pd.DataFrame([dict(rm=r["rm"], lines=nl.get(r["rm"], 0), cps204=r["s4"] / max(cyc.get(r["rm"], 1), 1), common_pb_pct_of_206=r["f206"],
                              err_206_238=100 * r["e68"], err_206_238_after=100 * r["e68c"], err_207_206=100 * r["e76"], err_207_206_after=100 * r["e76c"])
                         for r in rows])


def _val_scores(sess, rs, min_cps=1500.0):
    """(element bias %, number of element-RM pairs, U-Pb bias %, number of RMs, pairs, offset score) for the standards in rs, which holds the model's
    corrections already applied. Element bias: each RM's cps per ppm against the other RMs of the same kind (G_, Z_...), leave one out.
    U-Pb bias: 206/238 and 207/206 against the accepted ratio, scatter between RMs. pairs: the per-mass, per-RM biases (for a paired comparison).
    Offset score: median size of the calibration-line intercept relative to the lowest-count RM's signal, in percent."""
    tick()
    items = _val_items(rs)
    stats = _line_stats(rs)
    pairs = _val_pairs(sess, rs, items, stats=stats)
    big = [abs(b) for (b, c) in pairs.values() if c >= min_cps]
    ratios, c4 = {}, {}
    for lid, (rm, _mean, sm) in stats.items():
        if rs.has(206, 238):
            s6, s8 = float(sm[rs.idx[206]]), float(sm[rs.idx[238]])
            if s8 > 0:
                ratios.setdefault((rm, "206Pb/238U"), []).append((s6, s8))
        if rs.has(206, 207):
            s7, s6 = float(sm[rs.idx[207]]), float(sm[rs.idx[206]])
            if s6 > 0:
                ratios.setdefault((rm, "207Pb/206Pb"), []).append((s7, s6))
        if rs.has(204, 206, 207, 238):
            sums = [float(sm[rs.idx[m]]) for m in (204, 206, 207, 238)]
            c4.setdefault(rm, np.zeros(4))
            c4[rm] += sums
    mub_c = _cpb_error(sess, c4)
    ub = []
    for key in ("206Pb/238U", "207Pb/206Pb"):
        f = []
        for (rm, k), v in ratios.items():
            acc = accepted_upb(sess, rm, key) if k == key else None
            if acc and k == key:
                a = sum(x[0] for x in v)
                b = sum(x[1] for x in v)
                if a > 0 and b > 0:
                    f.append(np.log(a / b / acc))
        if len(f) >= 3:
            ub += list(np.array(f) - np.median(f))
    rms_ = lambda v: float(100 * np.sqrt(np.mean(np.square(v)))) if len(v) else float("nan")
    ic = rm_intercepts(sess, rs, items, stats=stats)
    off = float(100 * np.median(np.abs(ic["rel"]))) if len(ic) >= 5 else float("nan")
    weak = [abs(b) for (b, c) in pairs.values() if c < 10000.0]
    m1 = float(100 * np.mean(weak)) if len(weak) >= 8 else float("nan")
    mub = float(100 * np.mean(np.abs(ub))) if len(ub) else float("nan")
    return rms_(big), len(big), rms_(ub), len(ub), pairs, off, m1, mub, mub_c


def _pair_change(p_with, p_without, max_cps=10000.0):
    """Paired change in |bias| (percentage points) over the pairs a pedestal can matter for (low-count signals), and how many got better or worse."""
    d = [100 * (abs(p_with[k][0]) - abs(p_without[k][0])) for k in p_with if k in p_without and p_with[k][1] < max_cps
         and abs(p_with[k][0] - p_without[k][0]) * 100 >= 0.2]                    # only the pairs the correction actually moved
    if len(d) < 8:
        return float("nan"), 0, 0, len(d)
    d = np.array(d)
    return float(np.median(d)), int(np.sum(d < 0)), int(np.sum(d > 0)), len(d)


def validate_rules(sess, raw, model=None, tol=0.15):
    """For every proposed correction, how the agreement among the standards changes when it is added to, or taken out of,
    the ticked set. Three measures: the same mass in one reference material against the others of its kind (paired, low-count signals),
    206Pb/238U and 207Pb/206Pb against the accepted ratios, and the intercept of cps against ppm across reference materials (zero when clean).
    Returns (table, summary dict). The standards must have reference material names with accepted values."""
    model = model or sess.interf
    rs = _std_subset(raw)
    if len(rs.X) < 20 or len({str(r) for r in rs.rm_of}) < 2:
        raise ValueError("The test needs at least two standard lines with different reference materials (Import tab: role Standard, RM name)")
    on0 = {r.id for r in model.rules if r.enabled}
    saved = {r.id: r.enabled for r in model.rules}

    def score(ids):
        for r in model.rules:
            r.enabled = r.id in ids
        X = rs.X.copy()
        model.apply(X, {m: [i] for i, m in enumerate(rs.masses)}, rs.line_of)
        r2 = RawLines(rs.masses, X, rs.line_of, rs.std_of, rs.rm_of)
        r2.labels = rs.labels
        return _val_scores(sess, r2)
    try:
        none = score(set())
        cur = score(on0)
        rows = []
        for r in model.rules:
            if r.kind == "regfloor":
                continue
            w = score(on0 | {r.id})
            wo = score(on0 - {r.id})
            d_el = w[0] - wo[0] if np.isfinite(w[0]) and np.isfinite(wo[0]) else float("nan")
            d_l1 = w[7] - wo[7] if np.isfinite(w[7]) and np.isfinite(wo[7]) else float("nan")
            d_l2 = w[2] - wo[2] if np.isfinite(w[2]) and np.isfinite(wo[2]) else float("nan")
            d_ub = max(d_l1, d_l2) if np.isfinite(d_l1) and np.isfinite(d_l2) else (d_l1 if np.isfinite(d_l1) else d_l2)   # both the mean and the root mean square must agree to count as better
            d_pr, n_b, n_w, n_p = _pair_change(w[4], wo[4])
            d_cp = w[8] - wo[8] if np.isfinite(w[8]) and np.isfinite(wo[8]) else float("nan")
            d_off = w[5] - wo[5] if np.isfinite(w[5]) and np.isfinite(wo[5]) else float("nan")
            ds = [d for d in (d_pr, d_ub, d_cp) if np.isfinite(d)]
            if np.isfinite(d_pr) and n_p >= 8 and max(n_b, n_w) < 0.65 * n_p:
                ds = [d for d in ds if d is not d_pr] + ([0.0] if np.isfinite(d_pr) else [])          # a split vote among the moved pairs counts for nothing
            if not ds:
                ds = [d_el] if np.isfinite(d_el) else []
            t = max(tol, 0.2)
            if not ds:
                v = "cannot be tested here"
            elif min(ds) < -t and max(ds) < t:
                v = "helps"
            elif max(ds) > t and min(ds) > -t:
                v = "hurts"
            elif min(ds) < -t and max(ds) > t:
                v = "mixed"
            else:
                v = "no clear effect"
            rows.append(dict(id=r.id, correction=r.text, element_bias_without=wo[0], element_bias_with=w[0],
                             upb_bias_without=wo[2], upb_bias_with=w[2], upb_abs_without=wo[7], upb_abs_with=w[7], weak_without=wo[6], weak_with=w[6], cpb_without=wo[8], cpb_with=w[8], pairs_change=d_pr, pairs_better=n_b, pairs_worse=n_w, pairs_n=n_p,
                             offset_without=wo[5], offset_with=w[5], verdict=v))
    finally:
        for r in model.rules:
            r.enabled = saved[r.id]
    summ = dict(none=none[:4] + (none[5], none[6], none[7], none[8]), ticked=cur[:4] + (cur[5], cur[6], cur[7], cur[8]), n_rm=len({str(r) for r in rs.rm_of}), n_lines=len(np.unique(rs.line_of)))
    return pd.DataFrame(rows), summ


# ---- a floor learned from the other masses (the residual after the other corrections)
def _rf_clusters(used, gap=4):
    used = sorted(set(used))
    if not used:
        return []
    out = [[used[0]]]
    for m in used[1:]:
        (out[-1].append(m) if m - out[-1][-1] <= gap else out.append([m]))
    return [c for c in out if len(c) >= 2]


def _rf_design(get, an, tic):
    cols = [np.sqrt(np.clip(np.nan_to_num(get(m)), 0, None)) for m in an]
    cols.append(np.sqrt(np.clip(np.nan_to_num(tic), 0, None)))
    return np.column_stack(cols)


def _apply_regfloor(p, V):
    """Take off each cluster's learned floor: a ridge prediction from the square roots of the counts at the masses away from the cluster."""
    keys = list(V)
    M = np.nan_to_num(np.column_stack([V[m] for m in keys]))
    col = {m: i for i, m in enumerate(keys)}
    tic = M.sum(1)
    S = np.sqrt(np.clip(M, 0, None))
    stic = np.sqrt(np.clip(tic, 0, None))
    preds = []
    for c in p.get("clusters", []):
        mu, sd, w = np.asarray(c["mu"], float), np.asarray(c["sd"], float), np.asarray(c["w"], float)
        cols = [S[:, col[m]] if m in col else np.full(len(tic), mu[k]) for k, m in enumerate(c["an"])]
        cols.append(stic)
        A = np.column_stack(cols)
        preds.append(np.clip(c["b"] + ((A - mu) / sd) @ w, 0, None))
    for c, pred in zip(p.get("clusters", []), preds):
        for m in V:
            if c["lo"] - c["pad"] <= m <= c["hi"] + c["pad"] and np.any(V[m] != 0):
                V[m] -= pred


def _ridge(A, y, alpha):
    mu, sd = A.mean(0), A.std(0) + 1e-9
    Z = (A - mu) / sd
    b = float(y.mean())
    w = np.linalg.solve(Z.T @ Z + alpha * np.eye(Z.shape[1]), Z.T @ (y - b))
    return mu, sd, w, b


def est_regfloor(raw, Xc, used, alpha=3000.0, nfold=5, sub=4, excl=3, pad=2, min_m=14, seed=0):
    """Learn the floor left at the empty masses after the other corrections (Xc: the cycles with them applied) from the masses away from it.
    Each group of empty masses gets a ridge model of its median count on the square roots of all other masses and of the ion current.
    The masses within excl of the group and all empty masses are left out of the predictors, so no mass predicts itself.
    Returns (rule, Xoof, info). Xoof is Xc with the floor taken off by predictions made without the line (lines are cut into nfold groups),
    which is what the correction would do to a line it was not fitted on."""
    idx = {m: i for i, m in enumerate(raw.masses)}
    used = [m for m in used if m in idx]
    cl = _rf_clusters(used)
    if not cl:
        return None, Xc.copy(), {}
    ids = np.unique(raw.line_of)
    rng = np.random.default_rng(seed)
    fold = dict(zip(ids.tolist(), rng.integers(0, nfold, len(ids))))
    fo = np.array([fold[int(l)] for l in raw.line_of])
    tic = np.nansum(Xc, axis=1)
    out, clusters, rows = Xc.copy(), [], []
    for c in cl:
        lo, hi = min(c), max(c)
        F = np.nanmedian(Xc[:, [idx[m] for m in c]], axis=1)
        an = [m for m in raw.masses if m >= min_m and not (lo - excl <= m <= hi + excl) and m not in used]
        if len(an) < 5:
            continue
        A = _rf_design(lambda m: Xc[:, idx[m]], an, tic)
        pred = np.zeros(len(F))
        for k in range(nfold):
            tr, te = fo != k, fo == k
            if tr.sum() < 50 or not te.any():
                continue
            mu, sd, w, b = _ridge(A[tr][::sub], F[tr][::sub], alpha)
            pred[te] = b + ((A[te] - mu) / sd) @ w
        pred = np.clip(pred, 0, None)
        cols = [idx[m] for m in raw.masses if lo - pad <= m <= hi + pad]
        out[:, cols] -= pred[:, None]
        mu, sd, w, b = _ridge(A[::sub], F[::sub], alpha)
        clusters.append(dict(lo=int(lo), hi=int(hi), pad=int(pad), an=[int(m) for m in an], mu=[float(x) for x in mu], sd=[float(x) for x in sd],
                             w=[float(x) for x in w], b=float(b)))
        rows.append((lo, hi, len(c), float(np.median(np.abs(pred - F)))))
    if not clusters:
        return None, Xc.copy(), {}
    rule = InterfRule("reg_floor", "pedestal", "", kind="regfloor", params=dict(clusters=clusters), enabled=False, basis="measured")
    return rule, out, dict(clusters=rows)


def regfloor_signature(model):
    """What the learned floor depends on: the other ticked corrections and their numbers."""
    keep = [(r.id, r.params, r.edges) for r in sorted(model.rules, key=lambda r: r.id) if r.enabled and r.kind != "regfloor"]
    import hashlib
    return hashlib.md5(json.dumps(keep, sort_keys=True, default=str).encode()).hexdigest()[:12]


def model_signature(model):
    """What a corrected copy of the data depends on: every ticked correction with its numbers, and the limit."""
    keep = [(r.id, r.params, r.edges) for r in sorted(model.rules, key=lambda r: r.id) if r.enabled]
    import hashlib
    return hashlib.md5(json.dumps([keep, float(getattr(model, "guard", 0.0)), sorted(model.used or [])], sort_keys=True, default=str).encode()).hexdigest()[:12]


def refresh_regfloor_flag(model):
    r = model.get("reg_floor")
    if r is None:
        return
    stale = r.params.get("sig") != regfloor_signature(model)
    msg = "learned with a different set of corrections ticked: learn it again"
    r.flags = [f for f in r.flags if f != msg]
    if stale and r.enabled:
        r.flags.append(msg)


def add_regfloor(sess, raw, model=None, force=False):
    """Learn the floor left after the ticked corrections and add it as the correction 'reg_floor'. It is ticked only if the reference materials,
    corrected with predictions made without their own lines, agree better (U-Pb falls by 2 percent or more, nothing else rises by more than 5 percent,
    the low-count signal bias rises by less than 1.5 points) or if force is true. Returns a dict describing what happened."""
    model = model or sess.interf
    used = list(model.used or [])
    if len(used) < 6:
        raise ValueError("Analyze the lines first")
    old = model.get("reg_floor")
    saved = {r.id: r.enabled for r in model.rules}
    if old is not None:
        old.enabled = False
    try:
        Xc = raw.X.copy()
        model.apply(Xc, {m: [i] for i, m in enumerate(raw.masses)}, raw.line_of)
        sig = regfloor_signature(model)
    finally:
        for r in model.rules:
            r.enabled = saved[r.id]
    rule, Xoof, info = est_regfloor(raw, Xc, used)
    if rule is None:
        return dict(added=False, reason="not enough empty masses to learn a floor from")
    rule.params["sig"] = sig
    rule.params["n_lines"] = int(len(np.unique(raw.line_of)))
    s = raw.std_of & (raw.rm_of != "")
    scored = s.sum() >= 20 and len({str(x) for x in raw.rm_of[s]}) >= 2

    def sc(X):
        r = RawLines(raw.masses, X[s], raw.line_of[s], raw.std_of[s], raw.rm_of[s])
        r.labels = raw.labels
        v = _val_scores(sess, r)
        return v[6], v[7], v[8]
    res = dict(added=True, scored=scored, clusters=info.get("clusters", []))
    ok = force
    if scored:
        a, b = sc(Xc), sc(Xoof)
        res.update(before=a, after=b)
        fin = lambda x, y: np.isfinite(x) and np.isfinite(y)
        better = any(fin(x, y) and y <= 0.98 * x for x, y in zip(a[1:], b[1:]))
        worse = any(fin(x, y) and y > 1.05 * x for x, y in zip(a[1:], b[1:])) or (fin(a[0], b[0]) and b[0] > a[0] + 1.5)
        ok = ok or (better and not worse)
        f = lambda v: "-" if not np.isfinite(v) else f"{v:.0f}%"
        rule.evidence = (f"Reference materials corrected without their own lines: weak-signal bias {f(a[0])} to {f(b[0])}, U-Pb {f(a[1])} to {f(b[1])}, "
                         f"with the 204 correction {f(a[2])} to {f(b[2])}.")
    else:
        rule.evidence = "No standards of two reference materials to judge it on."
    n_cl = len(rule.params["clusters"])
    rule.text = (f"Learned floor: the counts left at {n_cl} groups of empty masses are predicted from the other masses and taken off the masses "
                 f"around each group. Fitted on {rule.params['n_lines']} lines.")
    rule.effect = "typical size of the floor removed: " + ", ".join(f"{lo}-{hi}: {e:.0f} cps" for lo, hi, _n, e in info["clusters"][:6])
    rule.enabled = bool(ok)
    res["enabled"] = bool(ok)
    rules = [r for r in model.rules if r.id != "reg_floor"] + [rule]
    model.set_rules(rules)
    model.get("reg_floor").enabled = bool(ok)
    return res


_ISO_REE = {"La", "Ce", "Pr", "Nd", "Sm", "Eu", "Gd", "Tb", "Dy", "Ho", "Er", "Tm", "Yb", "Lu", "Hf", "Ta", "W"}
_ISO_MID = {"Ca", "Sc", "Ti", "V", "Cr", "Mn", "Fe", "Co", "Ni", "Cu", "Zn", "K", "Ar"}


def group_of(r):
    """The name of the group a rule is tried and tuned with. Oxides, doubly charged ions and hydrides each go as one family. Isobars go in three
    groups by the element they land on. The Hg isobar, the Th tail and the pedestal parts stand alone."""
    if r.id.startswith("ox_"):
        return "oxides (all)"
    if r.id.startswith("dc_"):
        return "doubly charged (all)"
    if r.id.startswith("hy_"):
        return "hydrides (all)"
    if r.id.startswith("iso_"):
        el = (r.params or {}).get("el", "")
        return "isobars: REE, Hf, W" if el in _ISO_REE else ("isobars: K to Zn" if el in _ISO_MID else "isobars: Rb to Os")
    return r.id


def rule_groups(model):
    """Corrections that are tried together: each pedestal rule, the Hg isobar, the Th tail, and the families (oxides, isobars, doubly charged, hydrides)."""
    g = {}
    for r in model.rules:
        if r.kind == "regfloor":
            continue                       # fitted on all the lines last, judged on lines held out: not part of the greedy search
        g.setdefault(group_of(r), []).append(r.id)
    return g


def _rs_without(rs, rm):
    """The standards rs with one reference material taken out."""
    keep = np.array([str(r) != rm for r in rs.rm_of])
    r = RawLines(rs.masses, rs.X[keep], rs.line_of[keep], rs.std_of[keep], rs.rm_of[keep])
    r.labels, r.line_names = rs.labels, getattr(rs, "line_names", {})
    return r


def select_rules(sess, raw, model=None, min_gain=0.02, max_worse=0.03, cv=True, min_stable=0.6):
    """Forward selection from the standards: start with nothing, add the group of corrections that lowers the disagreement most, repeat.
    Two measures, each relative to doing nothing: the mean size of the per-mass bias of low-count signals (one reference material against the others
    of its kind) and the mean size of the U-Pb ratio errors. A group is added only if the sum falls by min_gain and neither measure rises by
    more than max_worse (the element bias at all masses guards as well).
    With three or more reference materials the selection is also repeated with each one left out, and a group is kept only if it was chosen
    in at least min_stable of those repeats, so a group that one reference material alone asked for is dropped. The low-count signal bias of the
    reference material that was left out, with and without the groups chosen without it, is the held-out result (path.attrs["cv"]).
    Returns (path table, chosen rule ids). Leaves the ticks as they were."""
    model = model or sess.interf
    rs = _std_subset(raw)
    all_rms = sorted({str(r) for r in rs.rm_of})
    if len(rs.X) < 20 or len(all_rms) < 2:
        raise ValueError("The test needs at least two standard lines with different reference materials (Import tab: role Standard, RM name)")
    groups = rule_groups(model)
    by_id = {r.id: r for r in model.rules}
    cache = {}

    def score(ids, rsub, tag):
        key = (tag, frozenset(ids))
        if key in cache:
            return cache[key]
        m = InterfModel()
        m.guard = model.guard
        m.set_rules([_rep_enabled(by_id[i]) for i in sorted(ids) if i in by_id])
        X = rsub.X.copy()
        m.apply(X, {mm: [i] for i, mm in enumerate(rsub.masses)}, rsub.line_of)
        r2 = RawLines(rsub.masses, X, rsub.line_of, rsub.std_of, rsub.rm_of)
        r2.labels = rsub.labels
        sc = _val_scores(sess, r2)
        cache[key] = ((sc[6], sc[7], sc[8], sc[0]), sc[4])
        return cache[key]

    def greedy(rsub, tag, pool=None, par=False):
        pool = groups if pool is None else pool
        base_, _ = score(set(), rsub, tag)
        path = [dict(step=0, added="nothing", weak_bias=base_[0], upb_error=base_[1], upb_error_204=base_[2], elem_bias=base_[3],
                     J=float(sum(np.isfinite(base_[:3]))))]
        chosen, left, cur = set(), dict(pool), base_

        def J(v):
            parts = [x / x0 for x, x0 in zip(v[:3], base_[:3]) if np.isfinite(x) and np.isfinite(x0) and x0 > 0]       # the element bias (4th) only guards
            return float(np.sum(parts)) if parts else float("nan")
        Jc = J(cur)
        names = []
        for step in range(1, len(pool) + 1):
            best = None
            items_ = list(left.items())
            res_ = _pmap(lambda it: score(chosen | set(it[1]), rsub, tag)[0], items_) if par else (score(chosen | set(it[1]), rsub, tag)[0] for it in items_)
            for (name, ids), v in zip(items_, res_):
                if any(np.isfinite(x) and np.isfinite(c) and x > c * (1 + max_worse) for x, c in zip(v, cur)):
                    continue
                j = J(v)
                if np.isfinite(j) and (best is None or j < best[0]):
                    best = (j, name, ids, v)
            if best is None or not np.isfinite(Jc) or best[0] > Jc - min_gain:
                break
            Jc, name, ids, v = best
            chosen |= set(ids)
            cur = v
            left.pop(name)
            names.append(name)
            path.append(dict(step=step, added=name, weak_bias=v[0], upb_error=v[1], upb_error_204=v[2], elem_bias=v[3], J=Jc))
        return path, chosen, names

    path, chosen, names = greedy(rs, "all", par=True)
    info = None
    if cv and len(all_rms) >= 3:
        votes = {n: 0 for n in groups}
        before, after, nfold = [], [], 0
        _, p_none = score(set(), rs, "all")
        pool = {n: groups[n] for n in names}                   # the repeats choose among the groups the full run chose: only those can be dropped

        def fold(rm):
            tr = _rs_without(rs, rm)
            if len({str(r) for r in tr.rm_of}) < 2:
                return None
            try:
                _, ch_k, nm_k = greedy(tr, "no_" + rm, pool)
                _, p_k = score(ch_k, rs, "all")
            except Exception:
                return None
            return rm, nm_k, p_k
        for res in _pmap(fold, all_rms):                       # the repeats are independent of each other and run side by side
            if res is None:
                continue
            rm, nm_k, p_k = res
            nfold += 1
            for n in nm_k:
                votes[n] += 1
            for key, (b0, c0) in p_none.items():
                if key[1] == rm and c0 < 10000.0 and key in p_k:
                    before.append(abs(b0))
                    after.append(abs(p_k[key][0]))
        if nfold >= 2:
            stab = {n: votes[n] / nfold for n in groups}
            drop = [n for n in names if stab[n] < min_stable]
            for n in drop:
                chosen -= set(groups[n])
            for row in path:
                row["stable"] = stab.get(row["added"], np.nan)
            info = dict(folds=nfold, stability=stab, dropped=drop,
                        held_out_before=float(100 * np.mean(before)) if before else float("nan"),
                        held_out_after=float(100 * np.mean(after)) if after else float("nan"), pairs=len(before))
    df = pd.DataFrame(path)
    df.attrs["cv"] = info
    return df, sorted(chosen)


def subset_lines(raw, ids):
    """The cycles of some lines of a RawLines, as a RawLines of their own."""
    k = np.isin(raw.line_of, list(ids))
    r = RawLines(raw.masses, raw.X[k], raw.line_of[k], raw.std_of[k], raw.rm_of[k])
    r.labels = getattr(raw, "labels", {})
    r.line_names = getattr(raw, "line_names", {})
    r.t_line = getattr(raw, "t_line", {})
    return r


def subset_n_lines(pool, n):
    """The standards plus n minus their number of sample lines spread over the pool, with the line numbers counted again from 0."""
    lids = list(np.unique(pool.line_of))
    std_ids = [l for l in lids if pool.std_of[pool.line_of == l][0]]
    smp_ids = [l for l in lids if l not in set(std_ids)]
    keep = std_ids + _spread_ids(smp_ids, n - len(std_ids))
    r = subset_lines(pool, keep)
    remap = {old: new for new, old in enumerate(sorted(set(keep)))}
    r.line_of = np.array([remap[x] for x in r.line_of])
    r.t_line = {remap[o]: pool.t_line.get(o, float("nan")) for o in remap}
    r.line_names = {remap[o]: pool.line_names.get(o, str(o)) for o in remap}
    return r


def _spread_ids(ids, n):
    ids = list(ids)
    if n >= len(ids):
        return ids
    return [ids[int(round(j))] for j in np.linspace(0, len(ids) - 1, max(n, 0))] if n > 0 else []


def learning_curve(raw, ladder=(8, 16, 32, 64, 128, 256), tol=0.05, probes=None, lo=0, zero=None, learn_glass=False, driver=0, progress=None):
    """How many lines the pedestal needs. The pedestal is learned from the standards plus n sample lines spread over the session, for growing n,
    (ladder: the numbers of sample lines tried) and each fit is judged on the sample lines it did not see: the robust scatter of the empty masses after the pedestal is taken off, and the
    shift of their median. The smallest n whose score is within tol of the best is chosen. Returns (n chosen, table)."""
    lids = list(np.unique(raw.line_of))
    std_ids = [l for l in lids if raw.std_of[raw.line_of == l][0]]
    smp_ids = [l for l in lids if l not in set(std_ids)]
    n_all = len(lids)
    lad = sorted({int(k) for k in ladder if 4 <= k < len(smp_ids)})
    if len(smp_ids) < 12 or not lad:
        return n_all, pd.DataFrame([dict(lines=n_all, held_out=0, scatter=np.nan, shift=np.nan, score=np.nan, chosen=True)])
    rows = []
    q = raw_quantum(raw)
    test = _spread_ids(smp_ids, max(len(smp_ids) // 4, 5))                         # one set of sample lines held out for every n, so the scores compare
    pool = [l for l in smp_ids if l not in set(test)]
    lad = [k for k in lad if k < len(pool)] + ([len(pool)] if len(pool) >= 4 else [])
    ns = sorted(set(lad))
    # the fits are independent of each other, so they run side by side: the fit on all lines (it names the masses every fit is judged on)
    # and one fit for each number of sample lines
    jobs = [None] + ns

    def fit(n):
        sub = raw if n is None else subset_lines(raw, set(std_ids) | set(_spread_ids(pool, n)))
        return est_pedestal(sub, probes, lo, zero=zero, learn_glass=learn_glass, driver=driver, n_boot=0)
    fits = {}
    for k, (n, res) in enumerate(zip(jobs, _pmap(fit, jobs))):
        fits[n] = res
        if progress:
            progress(k + 1, len(jobs))
    judge = [m for m in fits[None][1].get("used", []) if raw.has(m)]
    if len(judge) < 3:
        return n_all, pd.DataFrame([dict(lines=n_all, held_out=0, scatter=np.nan, shift=np.nan, score=np.nan, chosen=True)])
    for n in ns:
        rules, det = fits.pop(n)
        use_ = [r for r in rules if r.id in ("ped_tic", "ped_const", "ped_drv")]
        if not use_:
            continue
        m = InterfModel()
        m.set_rules([_rep_enabled(r) for r in use_])
        te = subset_lines(raw, test)
        X = te.X.copy()
        m.apply(X, {mm: [i] for i, mm in enumerate(te.masses)}, te.line_of)
        cols = [te.idx[mm] for mm in judge]
        P = _zone_signal_arr(X[:, cols], q)
        lm = np.array([np.nanmedian(P[te.line_of == l]) for l in test])
        sc = float(1.4826 * np.nanmedian(np.abs(P - np.nanmedian(P))))
        shift = float(np.nanmedian(np.abs(lm)))
        rows.append(dict(lines=n + len(std_ids), sample_lines=n, held_out=len(test), scatter=sc, shift=shift, score=float(np.hypot(sc, shift))))
    if not rows:
        return n_all, pd.DataFrame([dict(lines=n_all, held_out=0, scatter=np.nan, shift=np.nan, score=np.nan, chosen=True)])
    df = pd.DataFrame(rows)
    best = df["score"].min()
    pick = df[df["score"] <= best * (1 + tol)]["lines"].min()
    df["chosen"] = df["lines"] == pick
    return int(pick), df


def _rep_enabled(r):
    from dataclasses import replace as _rep
    return _rep(r, enabled=True)



def tw_rm_errors(sess, raw, X):
    """Tera-Wasserburg check of the zircon reference materials in the cycles X (no 204 used).

    Each reference material's lines give one point (238/206, 207/206). The line through them, anchored at the common Pb
    composition, meets the concordia at an age. Two calibration factors (U/Pb and the 207/206 mass bias) are set so the ages of
    all the materials agree best with the accepted ones, like the median centring of the other measures.

    Returns (mean size of the 206/238 error in percent, {rm: error in percent})."""
    from scipy.optimize import minimize
    idx = {m: i for i, m in enumerate(raw.masses)}
    if not all(m in idx for m in (206, 207, 238)):
        return float("nan"), {}
    pts = {}
    for lid in np.unique(raw.line_of):
        rows = (raw.line_of == lid) & raw.std_of
        if not rows.any():
            continue
        rm = str(raw.rm_of[rows][0])
        if not rm.startswith("Z_"):
            continue
        tic = np.nansum(X[rows], axis=1)
        win = tic >= 0.3 * np.nanpercentile(tic, 95)
        if win.sum() < 5:
            continue
        s6, s7, s8 = (float(np.nansum(X[rows][win][:, idx[m]])) for m in (206, 207, 238))
        if s6 > 0 and s7 > 0 and s8 > 0:
            pts.setdefault(rm, []).append((s8 / s6, s7 / s6, s6))
    info = {}
    for rm, P in pts.items():
        a68, a76 = accepted_upb(sess, rm, "206Pb/238U"), accepted_upb(sess, rm, "207Pb/206Pb")
        if a68 and a76 and len(P) >= 2:
            t = float(age_ma(a68, "238"))
            r64, r74 = sk_common_64_74(min(max(t, 0.0), 3600.0))
            info[rm] = (np.array(P), a68, a76, float(r74 / r64))
    if len(info) < 3:
        return float("nan"), {}

    def run(k):
        k8, k7 = np.exp(k)
        out = {}
        for rm, (P, a68, a76, yc) in info.items():
            x, y, w = P[:, 0] * k8, P[:, 1] * k7, P[:, 2]
            sl = float(np.sum(w * x * (y - yc)) / np.sum(w * x * x))
            t = _tw_intersect(yc, sl)
            if not np.isfinite(t):
                out[rm] = (np.nan, np.nan)
                continue
            xc, y_ = _tw_conc(t)
            out[rm] = (float(np.log((1 / xc) / a68)), float(np.log(y_ / a76)))
        return out

    def obj(k):
        o = run(k)
        v = [a for a, b in o.values() if np.isfinite(a)] + [b for a, b in o.values() if np.isfinite(b)]
        return float(np.sqrt(np.mean(np.square(v)))) if len(v) >= 4 else 9.0
    best = None
    for k0 in ([0, 0], [0.3, 0], [-0.3, 0], [0, 0.1]):
        r = minimize(obj, k0, method="Nelder-Mead", options=dict(xatol=1e-3, fatol=1e-5, maxiter=200))
        if best is None or r.fun < best.fun:
            best = r
    o = run(best.x)
    per = {rm: 100 * a for rm, (a, b) in o.items() if np.isfinite(a)}
    return (float(np.mean(np.abs(list(per.values())))) if per else float("nan")), per


def rm_panel(sess, raw, model=None):
    """The reference materials with the ticked corrections and with none, side by side: per material the bias of its low-count signals against the
    other materials of its kind (percent), the errors of 206Pb/238U and 207Pb/206Pb (percent) and the 204 signal (cps).
    Returns (table, summary) where summary holds the three overall measures {weak, upb, upb204} for 'now' and 'none'."""
    model = model or sess.interf
    rs = _std_subset(raw)
    if len(rs.X) < 20 or len({str(r) for r in rs.rm_of}) < 2:
        raise ValueError("Needs standard lines of at least two reference materials (Import tab: role Standard, RM name)")
    saved = {r.id: r.enabled for r in model.rules}
    out, summ = {}, {}
    try:
        for tag in ("now", "none"):
            for r in model.rules:
                r.enabled = saved[r.id] if tag == "now" else False
            X = rs.X.copy()
            model.apply(X, {m: [i] for i, m in enumerate(rs.masses)}, rs.line_of)
            r2 = RawLines(rs.masses, X, rs.line_of, rs.std_of, rs.rm_of)
            r2.labels = rs.labels
            twm, twper = tw_rm_errors(sess, rs, X)
            by = {}
            for (m, rm), (b, c) in _val_pairs(sess, r2, _val_items(r2)).items():
                by.setdefault(rm, []).append(abs(b) * 100)
            sc = _val_scores(sess, r2)
            summ[tag] = dict(weak=sc[6], upb=sc[7], upb204=sc[8], tw=twm)
            rep = pb204_report(sess, raw, model)
            rows = {}
            for rm in sorted({str(x) for x in rs.rm_of}):
                row = dict(rm=rm, lines=int(len({int(l) for l in rs.line_of[np.array([str(x) == rm for x in rs.rm_of])]})), weak=float(np.mean(by[rm])) if rm in by else np.nan,
                           e68=np.nan, e76=np.nan, c204=np.nan, tw=twper.get(rm, np.nan))
                if len(rep):
                    q = rep[rep["rm"] == rm]
                    if len(q):
                        row.update(e68=float(q.iloc[0]["err_206_238"]), e76=float(q.iloc[0]["err_207_206"]), c204=float(q.iloc[0]["cps204"]))
                rows[rm] = row
            out[tag] = rows
    finally:
        for r in model.rules:
            r.enabled = saved[r.id]
    recs = []
    for rm, a in out["now"].items():
        b = out["none"][rm]
        recs.append(dict(rm=rm, lines=a["lines"], weak=a["weak"], weak_none=b["weak"], e68=a["e68"], e68_none=b["e68"], e76=a["e76"], e76_none=b["e76"],
                         c204=a["c204"], c204_none=b["c204"], tw=a["tw"], tw_none=b["tw"]))
    return pd.DataFrame(recs), summ



