def isotope_audit(raw, model=None, flag=0.25, min_cps=150.0):
    """Isotope-pattern check of every element that has several isotopes among the masses.

    The signal of each isotope divided by its natural abundance should be the same for all isotopes of the element. The consensus
    is the median across the isotopes. An isotope far above it carries something else (an interference), and one far below it is
    notched, saturated or suppressed.

    Unknowns and standards are shown apart. Returns a DataFrame. 'use' is False when either group deviates."""
    X = raw.X.copy()
    if model is not None:
        model.apply(X, {m: [i] for i, m in enumerate(raw.masses)}, raw.line_of)
    lines = sorted({int(l) for l in raw.line_of})
    S = np.array([np.nanmean(X[raw.line_of == i], axis=0) - np.nanpercentile(X[raw.line_of == i], 10, axis=0) for i in lines])
    isstd = np.array([bool(raw.std_of[raw.line_of == i][0]) for i in lines])
    idx = {m: j for j, m in enumerate(raw.masses)}
    rows = []
    for el, d in ISO_ABUNDANCE.items():
        ms = [m for m in d if m in idx and any(re.match(r"\d+(.*)", l) and re.match(r"\d+(.*)", l).group(1) == el
                                                for l in (raw.labels.get(m) or [f"{m}{el}"]))]
        if len(ms) < 2:
            continue
        res = {}
        for tag, sel in (("unknown", ~isstd), ("standard", isstd)):
            if not sel.any():
                continue
            s = S[sel].mean(axis=0)
            r = {m: s[idx[m]] / d[m] for m in ms if s[idx[m]] >= min_cps}
            if len(r) < 2:
                continue
            # the core is the largest group of isotopes that agree with each other
            best = []
            for a in r.values():
                grp = [m for m, v in r.items() if a > 0 and 1 / (1 + flag) <= v / a <= 1 + flag]
                if len(grp) > len(best) or (len(grp) == len(best) and sum(r[m] for m in grp) > sum(r[m] for m in best)):
                    best = grp
            if len(best) < 2 or len(best) < 0.4 * len(r):
                continue
            ref = float(np.median([r[m] for m in best]))
            res[tag] = {m: v / ref for m, v in r.items()}
        for m in ms:
            ru, rs_ = res.get("unknown", {}).get(m, np.nan), res.get("standard", {}).get(m, np.nan)
            vals = [v for v in (ru, rs_) if np.isfinite(v)]
            if not vals:
                continue
            bad = [v for v in vals if v > 1 + flag or v < 1 / (1 + flag)]
            hi = any(v > 1 + flag for v in vals)
            others = [l for l in (raw.labels.get(m) or []) if not l.endswith(el)]
            rows.append(dict(element=el, mass=m, shared_with=", ".join(others), unknown=ru, standard=rs_,
                             use=not bad, note=("excess: something else adds to this mass" if hi else "low: notched, saturated or suppressed") if bad else ""))
    return pd.DataFrame(rows, columns=["element", "mass", "shared_with", "unknown", "standard", "use", "note"])


def _scaled_rule(r, k):
    """A copy of a rule with its strength multiplied by k."""
    from dataclasses import replace as _rep
    import copy
    n = _rep(r, params=copy.deepcopy(r.params), edges=[list(e) for e in r.edges], enabled=True)
    if n.kind == "pedestal":
        if n.params.get("nodes"):
            n.params["nodes"] = [[c, a * k, b * k] for c, a, b in n.params["nodes"]]
        else:
            n.params["a"], n.params["b"] = n.params.get("a", 0.0) * k, n.params.get("b", 0.0) * k
    elif n.kind == "edges":
        n.edges = [[t, src, c * k] for t, src, c in n.edges]
    return n


_WIDE_GRID = (0.0, 0.25, 0.5, 1.0, 2.0, 4.0, 8.0)


def tune_groups(model, ids):
    """The corrections whose strength is tuned, each as one number: every ticked pedestal part, the Hg term, the Th tail, all oxides together."""
    g = {}
    for r in model.rules:
        if r.id not in ids or r.kind in ("pedestal_line", "gasblank", "linescale"):
            continue
        g.setdefault(group_of(r), []).append(r.id)
    return g


def tune_scales(sess, raw, model=None, ids=None, grid=(0.5, 0.65, 0.8, 0.9, 1.0, 1.1, 1.25, 1.5, 1.8), sweeps=2, loo=True):
    """Fine-tune how strong each ticked correction is, against the reference materials: one multiplier per correction, searched one at a time
    (twice over) to lower the same disagreement measures the selection uses. To see whether the multipliers are real, the search is repeated with
    each reference material left out in turn. Returns (table, {group: multiplier}, summary dict). Leaves the model alone."""
    model = model or sess.interf
    ids = set(ids if ids is not None else [r.id for r in model.rules if r.enabled])
    ids -= {r.id for r in model.rules if r.kind == "regfloor"}
    groups = tune_groups(model, ids)
    rs = _std_subset(raw)
    if not groups or len(rs.X) < 20 or len({str(r) for r in rs.rm_of}) < 2:
        raise ValueError("Tick the corrections to tune, and have standards of at least two reference materials")
    by_id = {r.id: r for r in model.rules}
    fixed = [by_id[i] for i in ids if i in by_id and by_id[i].kind in ("pedestal_line", "gasblank", "linescale")]

    def measures(rsub, scales):
        m = InterfModel()
        rules = list(fixed)
        for name, gids in groups.items():
            rules += [_scaled_rule(by_id[i], scales.get(name, 1.0)) for i in gids]
        m.set_rules([_rep_enabled(r) for r in rules])
        X = rsub.X.copy()
        m.apply(X, {mm: [i] for i, mm in enumerate(rsub.masses)}, rsub.line_of)
        r2 = RawLines(rsub.masses, X, rsub.line_of, rsub.std_of, rsub.rm_of)
        r2.labels = rsub.labels
        sc = _val_scores(sess, r2)
        return (sc[6], sc[7], sc[8])

    def search(rsub, grid=grid, sweeps=sweeps):
        base = measures(rsub, {n: 0.0 for n in groups})                    # nothing ticked: the yardstick
        def J(v):
            parts = [x / x0 for x, x0 in zip(v, base) if np.isfinite(x) and np.isfinite(x0) and x0 > 0]
            return float(np.sum(parts)) if parts else float("nan")
        cur = {n: 1.0 for n in groups}
        best = J(measures(rsub, cur))
        j0 = best
        for _ in range(sweeps):
            for n in groups:
                gr = _WIDE_GRID if (grid is not None and len(grid) >= 7 and n.startswith(("hydrides", "doubly"))) else grid
                for k in gr:
                    if k == cur[n]:
                        continue
                    trial = dict(cur, **{n: k})
                    j = J(measures(rsub, trial))
                    if np.isfinite(j) and (not np.isfinite(best) or j < best - 1e-9):
                        best, cur = j, trial
        return cur, j0, best, base
    scales, j_before, j_after, base = search(rs)
    rows = []
    loo_scales = {n: [] for n in groups}
    if loo:
        for rm in sorted({str(r) for r in rs.rm_of}):
            keep = np.array([str(r) != rm for r in rs.rm_of])
            if len({str(r) for r in rs.rm_of[keep]}) < 2:
                continue
            sub = RawLines(rs.masses, rs.X[keep], rs.line_of[keep], rs.std_of[keep], rs.rm_of[keep])
            sub.labels = rs.labels
            try:
                sc_, _, _, _ = search(sub, (0.6, 0.8, 1.0, 1.25, 1.6), 1)
            except Exception:
                continue
            for n in groups:
                loo_scales[n].append(sc_[n])
    for n in groups:
        v = loo_scales[n]
        rows.append(dict(correction=n, multiplier=scales[n], lowest_when_one_RM_left_out=min(v) if v else np.nan,
                         highest_when_one_RM_left_out=max(v) if v else np.nan))
    stable = all((not loo_scales[n]) or (max(loo_scales[n]) / max(min(loo_scales[n]), 1e-9) <= 2.2) for n in groups)
    gain = (j_before - j_after) / j_before if np.isfinite(j_before) and j_before > 0 else 0.0
    return pd.DataFrame(rows), scales, dict(J_before=j_before, J_after=j_after, gain=gain, stable=stable, groups=groups)


def apply_scales(model, scales, groups):
    """Multiply the strengths of the named corrections in the model, in place."""
    for name, ids in groups.items():
        k = scales.get(name, 1.0)
        if abs(k - 1.0) < 1e-9:
            continue
        for r in model.rules:
            if r.id in ids:
                n = _scaled_rule(r, k)
                r.params, r.edges = n.params, n.edges
                r.evidence += f" Strength multiplied by {k:.2f} to agree with the standards."




def analyze_interferences(sess, max_lines=40, probes=None, progress=None, status=None):
    """Learn the corrections from the lines of the open .vit file. Returns (rules, detail dict). Does not change the session."""
    curve = None
    st = status or (lambda f, t="": None)
    if not max_lines or max_lines <= 0:                                    # let the data decide how many lines to learn from
        cache = {}
        n_std = sum(1 for i in sess.infos if i.use and i.role == "standard")
        pool = load_raw_lines(sess, n_std + AUTO_POOL, progress, cache)
        st(0.20, "Finding how many lines to learn from...")
        n, curve = learning_curve(pool, probes=probes or sess.interf.probes, lo=sess.interf.lo, zero=sess.interf.zero,
                                  learn_glass=sess.interf.learn_glass, driver=sess.interf.driver,
                                  progress=lambda k, m: st(0.20 + 0.55 * k / max(m, 1), f"Fitting the pedestal on {k} of {m} line sets..."))
        raw = subset_n_lines(pool, n)
    else:
        raw = load_raw_lines(sess, max_lines, progress)
    st(0.78, "Fitting the final pedestal...")
    rules, ptab = est_pedestal(raw, probes or sess.interf.probes, sess.interf.lo, zero=sess.interf.zero, learn_glass=sess.interf.learn_glass, driver=sess.interf.driver)
    st(0.90, "Learning mercury, oxide and thorium corrections...")
    sess.interf.used = list(ptab.get("used", []))
    # the corrections after the pedestal are learned from the counts with the pedestal (global and line by line) already taken off
    from dataclasses import replace as _rep
    tmp = InterfModel()
    tmp.set_rules([_rep(r, enabled=True) for r in rules])
    Xp = raw.X.copy()
    tmp.apply(Xp, {m: [i] for i, m in enumerate(raw.masses)}, raw.line_of)
    rawp = RawLines(raw.masses, Xp, raw.line_of, raw.std_of, raw.rm_of)
    rawp.labels, rawp.line_names = raw.labels, raw.line_names
    rules += est_hg204(rawp, None)
    ox, meas = est_oxides(rawp, None, 0)
    rules += ox
    rules += est_u235(rawp, None, 0)
    rules += est_extra(rawp)
    try:
        have = {(int(t), int(s_)) for r in rules if r.kind == "edges" for t, s_, _c in r.edges if isinstance(s_, (int, np.integer))}
        rules += est_tails(rawp, sess.interf.used, sess.interf.zero, have)
    except Exception:
        pass
    try:
        rules += est_linescale(rawp, rules)
    except Exception:
        pass
    sess.interf.set_rules(rules)
    sess.interf.blank = bool(getattr(sess.source, "subtract_blank", False)) if getattr(sess.source, "raw", False) else None
    sess.interf.probes = list(probes or [])
    st(1.0, "Done")
    ptab["found"] = ptab.get("used", [])
    tl = target_lines(sess)
    return rules, dict(target=dict(names=tl[1], restricted=tl[0] is not None), raw=raw, pedestal=ptab.get("zones"), scan=ptab.get("scan"), used=ptab.get("used", []), mode=ptab.get("mode", ""), oxide=meas, curve=curve)


def suggest_zero(raw, scan=None, found=None):
    """Masses that probably hold nothing in geologic samples. Column 'why': the element is not found in nature, or the counts
    are the pedestal only (found in the data). The user decides which to keep."""
    sc = scan if scan is not None else scan_masses(raw)
    meas = set(sc["mass"]) if len(sc) else set()
    rows = []
    for m in raw.masses:
        labs = raw.labels.get(m, [])
        els = {re.sub(r"^\d+", "", l) for l in labs}
        els = {re.sub(r"[^A-Za-z].*$", "", e) for e in els}
        absent = bool(els) and els <= ABSENT_EL
        dead = m not in meas
        why = "element not found in nature" if absent else ("column is zero throughout: not measured" if dead and els else "")
        if not why and found and m in found:
            why = "counts are the pedestal only"
        if why:
            rows.append(dict(mass=m, labels=", ".join(labs), why=why, dead=dead))
    return pd.DataFrame(rows)


def zero_report(raw, model, zero=None):
    """For every mass the user calls zero: what is left after the ticked corrections, whether any cycle carries a real signal
    (the sample may hold the element), and whether the counts follow a high-count neighbour (hydride or tail)."""
    zero = [z for z in (zero if zero is not None else model.zero) if raw.has(z)]
    if not zero:
        return pd.DataFrame()
    X = raw.X.copy()
    model.apply(X, {m: [i] for i, m in enumerate(raw.masses)}, raw.line_of)
    top = raw.tic >= np.quantile(raw.tic, 0.9)
    q = raw_quantum(raw)
    rows = []
    for m in zero:
        i = raw.idx[m]
        y0, y1 = raw.X[:, i], X[:, i]
        measured = bool(np.any(y0 != 0))
        low = np.sort(y1[np.isfinite(y1)])[: max(len(y1) // 2, 1)]          # background scale from the quiet half, a present element does not inflate it
        sd = 1.4826 * np.median(np.abs(low - np.median(low))) if measured and len(low) else 0.0
        thr = max(5 * sd, 8 * q) if measured else np.inf
        hot = np.nan_to_num(y1) > thr
        lines_hot = int(len({int(l) for l in raw.line_of[hot]})) if hot.any() else 0
        follows = ""
        for s_ in (m - 1, m - 2, m - 3, m + 1, m + 2, m + 3, m - 16, m - 17):
            if measured and raw.has(s_) and np.nanmean(raw.col(s_)) > 30 * max(abs(np.nanmean(y1)), q):
                ys = raw.col(s_)
                ok = np.isfinite(y1) & np.isfinite(ys)
                if ok.sum() > 30 and np.std(ys[ok]) > 0 and np.std(y1[ok]) > 0:
                    r = float(np.corrcoef(y1[ok], ys[ok])[0, 1])
                    if r > 0.5:
                        c = float(np.sum((y1[ok] - y1[ok].mean()) * (ys[ok] - ys[ok].mean())) / np.sum((ys[ok] - ys[ok].mean()) ** 2))
                        follows = f"follows {s_} (r {r:.2f}, {100 * c:.3f}% of it)"
                        break
        flag = ""
        if not measured:
            flag = "not measured (column is zero)"
        elif hot.mean() > 0.01:
            flag = f"signal above background in {100 * hot.mean():.1f}% of cycles, {lines_hot} line(s): the sample may hold this element"
        rows.append(dict(mass=m, labels=", ".join(raw.labels.get(m, [])), raw_cps=float(np.nanmean(y0[top])), corrected_cps=float(np.nanmean(y1[top])),
                         scatter_cps=float(sd), hot_cycles=float(hot.mean()), follows=follows, note=flag))
    return pd.DataFrame(rows)


def export_interf(path, sess, detail):
    """Everything the tab learned from, in one zip: the cycles of the analysed lines (npz), the per-mass scan, the pedestal zones, the proposals,
    the zero-mass report and the model, so the analysis can be reproduced or examined elsewhere."""
    import zipfile
    raw = detail["raw"]
    buf = io.BytesIO()
    np.savez_compressed(buf, masses=np.array(raw.masses), X=raw.X.astype(np.float32), line_of=raw.line_of, std_of=raw.std_of,
                        rm_of=np.array([str(x) for x in raw.rm_of]), tic=raw.tic.astype(np.float64))
    rules = pd.DataFrame([dict(id=r.id, enabled=r.enabled, family=r.family, text=r.text, basis=r.basis, effect=r.effect, evidence=r.evidence,
                               flags="; ".join(r.flags)) for r in sess.interf.rules])
    meta = dict(labels={str(k): v for k, v in raw.labels.items()}, line_names={str(k): v for k, v in raw.line_names.items()},
                model=sess.interf.to_dict(), n_cycles=int(len(raw.X)), n_masses=len(raw.masses))
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("cycles.npz", buf.getvalue())
        z.writestr("meta.json", json.dumps(meta, indent=1))
        z.writestr("rules.csv", rules.to_csv(index=False))
        if detail.get("scan") is not None:
            z.writestr("mass_scan.csv", detail["scan"].to_csv(index=False))
        if detail.get("pedestal") is not None:
            z.writestr("pedestal_zones.csv", detail["pedestal"].to_csv(index=False))
        if detail.get("curve") is not None and len(detail["curve"]):
            z.writestr("lines_to_learn_from.csv", detail["curve"].to_csv(index=False))
        zr = zero_report(raw, sess.interf)
        if len(zr):
            z.writestr("zero_masses.csv", zr.to_csv(index=False))
        z.writestr("check.csv", interf_check(raw, sess.interf).to_csv(index=False))
        try:
            rs_ = _std_subset(raw)
            ic = rm_intercepts(sess, rs_)
            if len(ic):
                z.writestr("rm_intercepts.csv", ic.to_csv(index=False))
        except Exception:
            pass
        z.writestr("README.txt", "cycles.npz: X (cycles x masses, float32 cps, raw), masses, line_of, std_of, rm_of, tic.\n"
                   "mass_scan.csv: each mass against the total ion current (a = constant cps, b = cps per million cps of ion current).\n"
                   "pedestal_zones.csv: the fit by zone of empty masses. lines_to_learn_from.csv: how the pedestal's error on unseen lines changes with the number of lines learned from. rules.csv: the proposals. meta.json: labels per mass and the model.\n")
    return path


def interf_check(raw, model):
    """Before and after on the analysed cycles: empty masses, the U isotopes, and the oxide masses."""
    X = raw.X.copy()
    cols = {m: [i] for i, m in enumerate(raw.masses)}
    model.apply(X, cols, raw.line_of)
    after = RawLines(raw.masses, X, raw.line_of, raw.std_of, raw.rm_of)
    top = raw.tic >= np.quantile(raw.tic, 0.9)
    rows = []

    def add(name, m, note=""):
        if not raw.has(m):
            return
        rows.append(dict(item=name, mass=m, raw_cps=float(np.nanmean(raw.col(m)[top])), corrected_cps=float(np.nanmean(after.col(m)[top])), note=note))
    for m in (model.used or model.probes)[:60:max(1, len(model.used or model.probes) // 12)]:
        add(f"empty mass {m}", m, "should be about 0")
    for m in model.zero:
        add(f"zero mass {m}", m, "marked as zero")
    for m, nm in ((99, "Tc"), (233, "233U"), (236, "236U"), (237, "237Np"), (239, "239Pu")):
        add(f"{nm}", m, "should be about 0")
    for m in (204, 206, 207, 208, 232, 235, 238):
        add(f"signal {m}", m)
    if raw.has(235, 238):
        u8 = np.nanmean(raw.col(238)[top])
        rows.append(dict(item="235U / (238U / 137.818)", mass=235, raw_cps=float(np.nanmean(raw.col(235)[top]) / (u8 / 137.818)),
                         corrected_cps=float(np.nanmean(after.col(235)[top]) / (np.nanmean(after.col(238)[top]) / 137.818)), note="ratio, 1 for natural U"))
    for m in (194, 195, 196):
        add(f"HfO mass {m}", m, "oxide of Hf, should fall")
    return pd.DataFrame(rows)


# ======================================================================================================================
# Detrital zircon (and other mineral) mapping: grains, domains, virtual spots, sampling
# Every question is asked of a set of pixels. A grain, a core, a rim, a virtual spot and a whole sample are all pixel sets,
# and a date from a pixel set always comes from pooled counts (ratio of sums), never from averaging per-pixel ratios.
# ======================================================================================================================
ZR_DATES = ("age206/238", "age207/235", "age207/206", "age207c")
ZR_DATES_ALL = ZR_DATES + ("age_conc", "agetw")


class ZCtx:
    """Everything the pixel-set functions need, built once per session state: calibrated signals, row normalisation factors, grain labels."""


def zr_context(sess, minerals=None):
    cfg = sess.upb
    mins = [n for n in (minerals or cfg.minerals) if n in sess.phases]
    if not mins:
        raise CalibError("Choose the minerals for U-Pb in the Quantify tab first")
    if not cfg.primary:
        raise CalibError("Choose a primary reference material for U-Pb in the Quantify tab first")
    ny, nx = sess.map.cube.shape[:2]
    lab = np.zeros((ny, nx), np.int32)
    gmin, off = {}, 0
    for n in mins:
        l = np.asarray(sess.grain_labels(n), np.int32)
        take = (l > 0) & (lab == 0)
        lab[take] = l[take] + off
        for g in np.unique(l[take]):
            gmin[int(g) + off] = n
        off += int(l.max())
    c = ZCtx()
    c.sess, c.ny, c.nx, c.lab, c.grain_mineral, c.minerals = sess, ny, nx, lab, gmin, mins
    c.region = (lab > 0) & sess.map.valid & ~corr_mask(sess, [l for l in CORR_UPB if l in sess._chan])
    c.dx, c.dy = pixel_pitch(sess)
    c.q = _count_quantum(sess.map)
    sig = upb_signals(_upb_get_map(sess), cfg, hg_ratio=0.0 if hg_already_stripped(sess) else None)
    c.sig = sig
    c.rat = _ratio_arrays(sig)
    rt = sess.map.row_time
    c.fac = {}
    for key in c.rat:
        _rows, _notes, f = upb_factor_series(sess, key)
        if f is None:
            continue
        c.fac[key] = np.asarray(f(rt), float) if np.isfinite(rt).all() else np.full(ny, float(f(0.0)))
    if "206Pb/238U" not in c.fac:
        raise CalibError("No usable primary-standard lines for 206Pb/238U")
    c.dom = np.zeros((ny, nx), np.int32)
    c.dom_info = pd.DataFrame(columns=["dom", "grain", "mineral", "kind", "n_pix", "area_um2"])
    c.region0 = c.region.copy()
    c.excl = np.zeros_like(c.region)
    c.pixok = c.region.copy()
    c.filter_pooled = False
    c.filter = {}
    return c


def _zr_idx(ctx, sel, pixel=False):
    """Flat, row-major pixel indices of a selection (bool mask or index list) inside the usable region. The pixel filter (zr_filter) applies to
    pixel-level statistics (pixel=True) and, when ctx.filter_pooled is set, to the pooled counts too."""
    base = ctx.region & ctx.pixok if (pixel or ctx.filter_pooled) else ctx.region
    sel = np.asarray(sel)
    if sel.dtype == bool:
        return np.flatnonzero(sel & base)
    idx = np.sort(sel.astype(np.int64).ravel())
    return idx[base.ravel()[idx]]


def _zr_dates(r):
    """Dates (Ma) from a dict of pooled ratios."""
    out = {}
    with np.errstate(all="ignore"):
        if "206Pb/238U" in r:
            out["age206/238"] = float(age_ma(r["206Pb/238U"], "238"))
        if "207Pb/235U" in r:
            out["age207/235"] = float(age_ma(r["207Pb/235U"], "235"))
        if "207Pb/206Pb" in r:
            out["age207/206"] = float(age_207_206(r["207Pb/206Pb"]))
        if "206Pb/238U" in r and "207Pb/206Pb" in r:
            d, p = common_pb_207(r["206Pb/238U"], r["207Pb/206Pb"])
            out["age207c"], out["common206pct"] = float(d), float(p)
    return out


def pixset_estimate(ctx, sel, g=10, tw=False, layers=(), pix=True):
    """Pooled estimate for a set of pixels: summed counts, ratios, dates, delete-a-block jackknife standard errors (blocks are
    consecutive pixels in row order, so they are spatial strips), the dispersion of the block ratios against what Poisson counting predicts
    (mswd_blocks, near 1 for a homogeneous set), and the mean of any layers (trace elements) over the pixels."""
    idx = _zr_idx(ctx, sel)
    n = len(idx)
    out = dict(n_pix=int(n), area_um2=float(n * ctx.dx * ctx.dy))
    if n == 0:
        return out
    iy = idx // ctx.nx
    keys = [k for k in ("206Pb/238U", "207Pb/235U", "207Pb/206Pb") if k in ctx.fac]
    num, den = {}, {}
    for k in keys:
        a, b = ctx.rat[k]
        na, nb = a.ravel()[idx], b.ravel()[idx]
        ok = np.isfinite(na) & np.isfinite(nb) & (nb > 0)
        num[k] = np.where(ok, na * ctx.fac[k][iy], 0.0)
        den[k] = np.where(ok, nb, 0.0)
    r = {k: (num[k].sum() / den[k].sum() if den[k].sum() > 0 else np.nan) for k in keys}
    out.update({"r" + k.replace("Pb/", "/"): float(v) for k, v in r.items()})
    d0 = _zr_dates(r)
    out.update(d0)
    ge = int(min(g, n // 2)) if n >= 4 else 0
    q = ctx.q
    if ge >= 3:
        blocks = np.array_split(np.arange(n), ge)
        sums = {k: (num[k].sum(), den[k].sum()) for k in keys}
        leave = {key: [] for key in d0}
        l68, l76 = [], []
        for b in blocks:
            rr = {}
            for k in keys:
                dn, dd = sums[k][1] - den[k][b].sum(), sums[k][0] - num[k][b].sum()
                rr[k] = dd / dn if dn > 0 else np.nan
            for key, v in _zr_dates(rr).items():
                leave[key].append(v)
            l68.append(rr.get("206Pb/238U", np.nan))
            l76.append(rr.get("207Pb/206Pb", np.nan))
        for key in ZR_DATES + ("common206pct",):
            if key in leave:
                a = np.array(leave[key])
                out[key + "_se"] = float(np.sqrt((ge - 1) / ge * np.sum((a - a.mean()) ** 2))) if np.isfinite(a).all() else np.nan
        if "206Pb/238U" in r and "207Pb/206Pb" in r and np.isfinite([r["206Pb/238U"], r["207Pb/206Pb"]]).all():
            out.update(_zr_concordia(r["206Pb/238U"], r["207Pb/206Pb"], np.array(l68), np.array(l76), ge))
        if q and "206Pb/238U" in keys:                 # Poisson expectation for the block ratios
            a, b = ctx.rat["206Pb/238U"]
            s6 = np.array([np.nansum(a.ravel()[idx[bb]]) for bb in blocks]) / q
            s8 = np.array([np.nansum(b.ravel()[idx[bb]]) for bb in blocks]) / q
            rb = np.array([num["206Pb/238U"][bb].sum() / den["206Pb/238U"][bb].sum() if den["206Pb/238U"][bb].sum() > 0 else np.nan for bb in blocks])
            with np.errstate(all="ignore"):
                var = r["206Pb/238U"] ** 2 * (1 / np.maximum(s6, 1e-9) + 1 / np.maximum(s8, 1e-9))
                ok = np.isfinite(rb) & (s6 > 0) & (s8 > 0)
                out["mswd_blocks"] = float(np.sum((rb[ok] - r["206Pb/238U"]) ** 2 / var[ok]) / (ok.sum() - 1)) if ok.sum() > 2 else np.nan
            out.update(_zr_overdispersion(rb, s6, s8))
    if q:
        a = ctx.sig.get("206Pb")
        if a is not None:
            out["ions206"] = float(np.nansum(a.ravel()[idx]) / q)
        b = ctx.sig.get("238U")
        if b is not None:
            out["ions238"] = float(np.nansum(b.ravel()[idx]) / q)
    if "age206/238" in d0 and "age207/206" in d0 and d0["age206/238"] > 0 and np.isfinite(d0["age207/206"]):
        out["disc_pct"] = float(100 * (1 - d0["age206/238"] / d0["age207/206"]))
    if tw and n >= 20 and "207Pb/206Pb" in keys:
        a68 = np.where(den["206Pb/238U"] > 0, num["206Pb/238U"] / np.where(den["206Pb/238U"] > 0, den["206Pb/238U"], 1), np.nan)
        a76 = np.where(den["207Pb/206Pb"] > 0, num["207Pb/206Pb"] / np.where(den["207Pb/206Pb"] > 0, den["207Pb/206Pb"], 1), np.nan)
        w = ctx.sig["206Pb"].ravel()[idx]
        t, se, pct = tw_age(a68, a76, w)
        out.update(agetw=t, agetw_se=se, tw_common206pct=pct)
    if pix and "206Pb/238U" in keys:
        out.update(_zr_pixel_stats(ctx, sel, g))
    idr = _zr_idx(ctx, sel)
    for spec in layers:
        arr = ctx.sess.get_layer(spec).ravel()[idr].astype(float)
        arr = arr[np.isfinite(arr)]
        out[spec] = float(arr.mean()) if arr.size else np.nan
    return out


# ---- domains
def _grain_boxes(lab):
    for gid, sl in enumerate(ndi.find_objects(lab), start=1):
        if sl is not None:
            yield gid, sl


def _depth_in_grain(ctx, m):
    """Distance (um) from the grain edge for a cropped grain mask, with the map edge counted as grain edge only where the grain really ends."""
    half = 0.25 * (ctx.dx + ctx.dy)
    mp = np.pad(m, 2, mode="constant")
    d = ndi.distance_transform_edt(mp, sampling=(ctx.dy, ctx.dx))[2:-2, 2:-2]
    return d - half


def _finish_domains(ctx, dom, rows):
    ctx.dom = dom
    t = pd.DataFrame(rows, columns=["dom", "grain", "mineral", "kind", "n_pix", "area_um2"]) if rows else pd.DataFrame(columns=["dom", "grain", "mineral", "kind", "n_pix", "area_um2"])
    ctx.dom_info = t
    return t


def domain_radial(ctx, rim_um, min_core_px=10, ids=None, gap_um=0.0):
    """Two domains per grain by depth from the grain edge: rim (within rim_um) and core. A grain whose core would be smaller than
    min_core_px stays one domain, 'whole'."""
    dom = np.zeros((ctx.ny, ctx.nx), np.int32)
    rows, nid = [], 1
    for gid, sl in _grain_boxes(ctx.lab):
        if ids is not None and gid not in ids:
            continue
        m = (ctx.lab[sl] == gid) & ctx.region[sl]
        if not m.any():
            continue
        depth = _depth_in_grain(ctx, ctx.lab[sl] == gid)
        core = m & (depth > rim_um + gap_um)
        rimm = m & (depth <= rim_um - gap_um) if gap_um else m & ~core
        parts = [("core", core), ("rim", rimm)] if core.sum() >= min_core_px and rimm.sum() > 0 else [("whole", m)]
        for kind, pm in parts:
            view = dom[sl]
            view[pm] = nid
            rows.append((nid, gid, ctx.grain_mineral.get(gid, ""), kind, int(pm.sum()), float(pm.sum() * ctx.dx * ctx.dy)))
            nid += 1
    return _finish_domains(ctx, dom, rows)


def _smooth_in(mask, val, sigma):
    """Gaussian smoothing that only uses pixels inside the mask (normalised convolution)."""
    w = ndi.gaussian_filter(mask.astype(float), sigma)
    v = ndi.gaussian_filter(np.where(mask, val, 0.0), sigma)
    with np.errstate(all="ignore"):
        return np.where(mask & (w > 1e-6), v / w, np.nan)


def zr_feature(ctx, name, sl, mask, sigma):
    """A smoothed feature image inside one grain. 'pbu' and 'pbpb' smooth the counts of numerator and denominator separately and then
    take the ratio (log10), so noise does not turn into bias. Any other name is a layer, smoothed and log10 transformed when positive."""
    if name in ("pbu", "pbpb"):
        key = "206Pb/238U" if name == "pbu" else "207Pb/206Pb"
        a, b = ctx.rat[key]
        iy = np.arange(ctx.ny)[sl[0]][:, None]
        na = np.nan_to_num(a[sl]) * ctx.fac[key][iy]
        nb = np.nan_to_num(b[sl])
        good = mask & np.isfinite(a[sl]) & np.isfinite(b[sl])
        num, den = _smooth_in(good, np.where(good, na, 0), sigma), _smooth_in(good, np.where(good, nb, 0), sigma)
        with np.errstate(all="ignore"):
            r = num / den
            return np.log10(np.where(r > 0, r, np.nan))
    arr = ctx.sess.get_layer(name)[sl].astype(float)
    good = mask & np.isfinite(arr)
    v = _smooth_in(good, np.where(good, arr, 0), sigma)
    with np.errstate(all="ignore"):
        return np.log10(np.where(v > 0, v, np.nan)) if np.nanmin(np.where(good, arr, np.nan)) > 0 else v


def domain_cluster(ctx, features, kmax=4, sigma=1.0, min_px=15, ids=None, min_grain_px=40, trim_px=0):
    """Domains by clustering smoothed features inside each grain. The number of domains per grain (1 to kmax) comes from a Gaussian
    mixture BIC in which the log-likelihood and the sample size are divided by the number of pixels one smoothing kernel covers
    (4 pi sigma^2), because smoothed neighbouring pixels are not independent and an uncorrected BIC splits noise. The labels are then
    cleaned with a majority filter and domains smaller than min_px are merged into their neighbours. trim_px leaves out the pixels within
    that many pixels of another domain (the blended zone). Domains are numbered by the first feature, lowest first."""
    from sklearn.mixture import GaussianMixture
    dom = np.zeros((ctx.ny, ctx.nx), np.int32)
    rows, nid = [], 1
    ncorr = max(1.0, 4 * np.pi * sigma ** 2)
    for gid, sl in _grain_boxes(ctx.lab):
        if ids is not None and gid not in ids:
            continue
        gm = (ctx.lab[sl] == gid)
        m = gm & ctx.region[sl]
        if not m.any():
            continue
        F = [zr_feature(ctx, f, sl, m, sigma) for f in features]
        ok = m & np.all([np.isfinite(f) for f in F], axis=0)
        labs = np.zeros(m.shape, np.int32)
        if ok.sum() >= min_grain_px:
            X = np.stack([f[ok] for f in F], axis=1)
            sd = X.std(0)
            keep = sd > 1e-9
            if keep.any():
                Z = (X[:, keep] - X[:, keep].mean(0)) / sd[keep]
                best, bk = None, 1
                fits = {}
                for k in range(1, kmax + 1):
                    if len(Z) < 10 * k:
                        break
                    gmm = GaussianMixture(k, covariance_type="full" if Z.shape[1] > 1 else "full", random_state=0, n_init=2, reg_covar=1e-4).fit(Z)
                    ll = gmm.score(Z) * len(Z) / ncorr
                    npar = k * (Z.shape[1] + Z.shape[1] * (Z.shape[1] + 1) / 2) + k - 1
                    bic = -2 * ll + npar * np.log(max(len(Z) / ncorr, 2.0))
                    fits[k] = (bic, gmm)
                if fits:
                    bk = min(fits, key=lambda k: fits[k][0])
                    gmm = fits[bk][1]
                    pr = gmm.predict(Z)
                    order = np.argsort([gmm.means_[j, 0] for j in range(bk)])
                    remap = np.empty(bk, int)
                    remap[order] = np.arange(bk)
                    labs[ok] = remap[pr] + 1
                    if bk > 1:
                        labs = _majority(labs, m, bk, sigma=max(sigma, 1.0))
                        labs = _merge_small(labs, m, min_px)
        if not labs.any():
            labs[m] = 1
        # unassigned usable pixels (feature NaN) join the nearest domain
        miss = m & (labs == 0)
        if miss.any() and (labs > 0).any():
            ind = ndi.distance_transform_edt(labs == 0, return_indices=True)[1]
            labs[miss] = labs[tuple(ind[:, miss])]
        if trim_px and len(np.unique(labs[labs > 0])) > 1:       # leave out the pixels next to another domain, where the two are blended
            kept = np.zeros_like(labs)
            for k in np.unique(labs[labs > 0]):
                inner = ndi.binary_erosion((labs == k) | ~gm, iterations=int(trim_px), border_value=1) & (labs == k)
                kept[inner] = k
            for k in np.unique(kept[kept > 0]):
                if (kept == k).sum() < 5:
                    kept[kept == k] = 0
            labs = kept
        ks = [k for k in np.unique(labs[labs > 0])]
        for j, k in enumerate(ks):
            pm = labs == k
            dom[sl][pm] = nid
            rows.append((nid, gid, ctx.grain_mineral.get(gid, ""), f"D{j + 1}" if len(ks) > 1 else "whole", int(pm.sum()), float(pm.sum() * ctx.dx * ctx.dy)))
            nid += 1
    return _finish_domains(ctx, dom, rows)


def _majority(labs, m, k, sigma=1.0):
    best, arg = None, None
    stack = []
    for j in range(1, k + 1):
        stack.append(_smooth_in(m, (labs == j).astype(float), sigma))
    st = np.nan_to_num(np.stack(stack), nan=-1)
    out = np.where(m, st.argmax(0) + 1, 0)
    return out.astype(np.int32)


def _merge_small(labs, m, min_px):
    """Domains (connected parts of one label) smaller than min_px take the label of the nearest bigger part."""
    out = labs.copy()
    for _ in range(3):
        small = np.zeros(m.shape, bool)
        for j in np.unique(out[out > 0]):
            cc, n = ndi.label(out == j, structure=np.ones((3, 3)))
            sizes = np.bincount(cc.ravel())
            for c in range(1, n + 1):
                if sizes[c] < min_px:
                    small |= cc == c
        if not small.any() or not (m & ~small).any():
            break
        ind = ndi.distance_transform_edt(small | ~m, return_indices=True)[1]
        out[small] = out[tuple(ind[:, small])]
    # a label may be present in several separate parts: keep them as one domain (spatial coherence is the user's call)
    return out


def domain_table(ctx, g=10, tw=False, layers=()):
    """One row per domain and one per grain (kind 'grain'): pooled counts, dates, uncertainties, mixing diagnostics, trace elements."""
    rows = []
    t = ctx.dom_info
    depth = zr_depth(ctx)
    for r in t.itertuples():
        e = pixset_estimate(ctx, ctx.dom == r.dom, g=g, tw=tw, layers=layers)
        dm = ctx.dom == r.dom
        gm = ctx.lab == r.grain
        mx = float(depth[gm].max()) if gm.any() else np.nan
        rows.append(dict(dom=r.dom, grain=r.grain, mineral=r.mineral, kind=r.kind, depth_rel=(float(depth[dm].mean()) / mx if mx > 0 and dm.any() else np.nan), **e))
    for gid in np.unique(ctx.lab[ctx.lab > 0]):
        e = pixset_estimate(ctx, ctx.lab == gid, g=g, tw=tw, layers=layers)
        if e["n_pix"]:
            rows.append(dict(dom=0, grain=int(gid), mineral=ctx.grain_mineral.get(int(gid), ""), kind="grain", **e))
    return zr_systematic(pd.DataFrame(rows), ctx.sess.upb)


# ---- virtual spots
def _disc_pixels(ctx, cy, cx, r_um):
    """Pixels whose centres lie within r_um of the point (cy, cx) given in pixel units."""
    ry, rx = r_um / ctx.dy, r_um / ctx.dx
    y0, y1 = max(int(np.floor(cy - ry)), 0), min(int(np.ceil(cy + ry)) + 1, ctx.ny)
    x0, x1 = max(int(np.floor(cx - rx)), 0), min(int(np.ceil(cx + rx)) + 1, ctx.nx)
    yy, xx = np.mgrid[y0:y1, x0:x1]
    ok = ((yy - cy) * ctx.dy) ** 2 + ((xx - cx) * ctx.dx) ** 2 <= r_um ** 2
    return yy[ok], xx[ok]


def _geodesic_blob(R, seed, k):
    """The k pixels of the region R closest to the seed pixel by steps inside R (8-connected, breadth first). A thin line gives a line."""
    from collections import deque
    ny, nx = R.shape
    seen = {seed}
    out, q = [], deque([seed])
    while q and len(out) < k:
        y, x = q.popleft()
        out.append(y * nx + x)
        for dy_ in (-1, 0, 1):
            for dx_ in (-1, 0, 1):
                yy, xx = y + dy_, x + dx_
                if 0 <= yy < ny and 0 <= xx < nx and R[yy, xx] and (yy, xx) not in seen:
                    seen.add((yy, xx))
                    q.append((yy, xx))
    return np.array(sorted(out)) if len(out) >= k else None


def virtual_spots(ctx, d_um, n, mode="grain", groups=None, seed=0, min_inside=0.8, max_tries=60, g=5, layers=()):
    """Place virtual spots and estimate each one from the pooled pixels under it.
    mode 'map'    n spots with centres uniform over all usable pixels
         'grain'  n spots per grain (groups: grain ids, default all)
         'domain' n spots per domain, footprint at least min_inside inside the domain (groups: domain ids)
         'pixels' n pixel-equivalent spots per domain: the same number of pixels as a round spot of diameter d_um, taken from the domain
                  as a connected blob grown from a random pixel, so a long thin domain gives a line (groups: domain ids)
    Returns a table: group, centre (pixel units), pixels, purity (largest share of one domain among the pixels), main domain, estimates."""
    rng = np.random.default_rng(seed)
    r = d_um / 2.0
    k_equiv = max(int(round(np.pi * r * r / (ctx.dx * ctx.dy))), 3)
    if mode == "map":
        regs = [(0, ctx.region)]
    elif mode == "grain":
        ids = groups if groups is not None else [int(x) for x in np.unique(ctx.lab[ctx.lab > 0])]
        regs = [(i, (ctx.lab == i) & ctx.region) for i in ids]
    else:
        ids = groups if groups is not None else [int(x) for x in ctx.dom_info.dom]
        regs = [(i, ctx.dom == i) for i in ids]
    rows = []
    for gid, R in regs:
        pts = np.argwhere(R)
        if len(pts) == 0:
            continue
        got, tries = 0, 0
        need = n if mode != "map" else n
        while got < need and tries < need * max_tries:
            tries += 1
            py, px = pts[rng.integers(len(pts))]
            cy, cx = py + rng.uniform(-0.5, 0.5), px + rng.uniform(-0.5, 0.5)
            if mode == "pixels":
                idx = _geodesic_blob(R, (int(py), int(px)), k_equiv)
                if idx is None:
                    if tries > 5 * max_tries:
                        break
                    continue
                inside = 1.0
            else:
                yy, xx = _disc_pixels(ctx, cy, cx, r)
                if len(yy) == 0:
                    continue
                inside = float(R[yy, xx].mean())
                if inside < min_inside:
                    continue
                keep = R[yy, xx]
                idx = np.sort((yy[keep] * ctx.nx + xx[keep]))
            if len(idx) < 3:
                continue
            e = pixset_estimate(ctx, idx, g=g, layers=layers)
            dd = ctx.dom.ravel()[idx]
            dd = dd[dd > 0]
            if dd.size:
                vals, cnt = np.unique(dd, return_counts=True)
                purity, main = float(cnt.max() / len(idx)), int(vals[cnt.argmax()])
            else:
                purity, main = np.nan, 0
            rows.append(dict(group=gid, cy=float(cy), cx=float(cx), inside=inside, purity=purity, main_dom=main, **e))
            got += 1
    return zr_systematic(pd.DataFrame(rows), ctx.sess.upb)


# ---- sampling theory and population
def vermeesch_p_miss(n, f):
    """Probability that at least one of the N = 1/f equal fractions of a population is missed by n grains (Vermeesch 2004, as in the provenance
    package): sum over i of (-1)^(i-1) C(N, i) (1 - i f)^n. Exact rational arithmetic, because the alternating sum is unstable in floats."""
    from fractions import Fraction
    from math import comb
    N = int(round(1.0 / f))
    fr = Fraction(1, N)
    return float(sum((-1) ** (i - 1) * comb(N, i) * (1 - i * fr) ** n for i in range(1, N + 1)))


def vermeesch_n(f, P=0.95):
    """Grains needed for probability P that no fraction of at least f of the population is missed (117 for f = 0.05 and P = 0.95)."""
    lo, hi = 1, 4
    while vermeesch_p_miss(hi, f) > 1 - P:
        lo, hi = hi, hi * 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if vermeesch_p_miss(mid, f) > 1 - P:
            lo = mid
        else:
            hi = mid
    return hi


def grains_needed(q, p, P=0.95, m=1):
    """Grains to map so that, with probability P, at least m grains show a domain that exists in a fraction q of the grains and is
    captured by a section with probability p."""
    from scipy.stats import binom
    pr = float(q) * float(p)
    if not 0 < pr <= 1:
        return np.nan
    n = m
    while binom.sf(m - 1, n, pr) < P:
        n += 1
        if n > 1_000_000:
            return np.nan
    return n


def section_capture(core_frac, R_um, pitch_um, min_px=20, reps=100000, seed=0):
    """A round grain of radius R_um with a concentric core of relative radius core_frac, cut at a random depth. Returns the probability that
    the section shows any core and that the core section holds at least min_px pixels."""
    rng = np.random.default_rng(seed)
    h = rng.uniform(-1, 1, reps)
    rc = np.sqrt(np.maximum(core_frac ** 2 - h ** 2, 0)) * R_um
    area = np.pi * rc ** 2 / pitch_um ** 2
    return dict(p_any=float((area > 0).mean()), p_min=float((area >= min_px).mean()))


def capture_curve(table, kind, min_px=20, m=1, nmax=400, reps=2000, seed=0, P=0.95):
    """From the domain table of a real map: the probability that a random draw of n grains from this sample includes at least m grains with
    a domain of that kind of at least min_px pixels, for n = 1 to nmax (bootstrap over grains). Returns (curve table, n for probability P)."""
    d = table[table.kind != "grain"]
    grains = np.sort(d.grain.unique())
    has = np.array([bool(((d.grain == gg) & (d.kind == kind) & (d.n_pix >= min_px)).any()) for gg in grains])
    rng = np.random.default_rng(seed)
    ns = np.arange(1, nmax + 1)
    prob = np.zeros(len(ns))
    if len(grains) == 0:
        return pd.DataFrame(dict(n=ns, p=prob)), np.nan
    draws = rng.integers(0, len(grains), (reps, nmax))
    hit = np.cumsum(has[draws], axis=1)
    prob = (hit >= m).mean(0)
    reach = np.flatnonzero(prob >= P)
    return pd.DataFrame(dict(n=ns, p=prob)), (int(ns[reach[0]]) if reach.size else np.nan)


def pop_select(table, rule="grain", date="age206/238", max_disc=None, min_px=0, disc="disc_da_pct", query=None):
    """Choose the rows that enter a population.

      'grain'     whole-grain pooled date
      'all'       every domain
      'core'      cores, or whole grains with no core
      'youngest' / 'oldest'  the youngest or oldest domain per grain
      'dominant'  the largest domain per grain
      'inner' / 'outer'  the domain with the greatest or smallest mean depth in its grain
      'no_outer'  every domain except the outer one of a zoned grain, so rims (where Pb loss and metamictisation concentrate) are left out

    max_disc drops rows more discordant than that (percent), by the column disc: disc_da_pct (perpendicular Aitchison distance,
    the best behaved filter in Vermeesch 2021), disc_dc_pct or disc_pct (relative age difference).

    query is a pandas query on the table, for example "class_ThU != 'metamorphic-like' and not altered". It is applied first."""
    d = table[np.isfinite(table[date]) & (table.n_pix >= min_px)].copy()
    if date + "_se" in d:
        d = d[np.isfinite(d[date + "_se"]) & (d[date + "_se"] > 0)]
    if max_disc is not None and disc in d:
        d = d[np.abs(d[disc]) <= max_disc]
    if query:
        d = d.query(query, engine="python")
    if rule == "grain":
        return d[d.kind == "grain"]
    d = d[d.kind != "grain"]
    if rule == "core":
        return d[d.kind.isin(["core", "whole", "D1"])]
    if rule == "youngest":
        return d.loc[d.groupby("grain")[date].idxmin()]
    if rule == "oldest":
        return d.loc[d.groupby("grain")[date].idxmax()]
    if rule == "dominant":
        return d.loc[d.groupby("grain").n_pix.idxmax()]
    if rule in ("inner", "outer", "no_outer"):
        dr = d.depth_rel.fillna(0.5) if "depth_rel" in d else pd.Series(0.5, index=d.index)
        d = d.assign(_dr=dr)
        n = d.groupby("grain").dom.transform("count")
        if rule == "inner":
            return d.loc[d.groupby("grain")._dr.idxmax()].drop(columns="_dr")
        if rule == "outer":
            return d.loc[d.groupby("grain")._dr.idxmin()].drop(columns="_dr")
        out = d.loc[d.groupby("grain")._dr.idxmin()].index
        return d[(n == 1) | ~d.index.isin(out)].drop(columns="_dr")
    return d


def pop_bootstrap(sel, date, grid, nboot=200, pdp=False, bw="Silverman", seed=0):
    """Density of the selected dates with a 68 and 95 percent band from a bootstrap over grains (all rows of a grain move together)."""
    se = sel[date + "_se"].to_numpy(float) if (date + "_se") in sel else None
    x = sel[date].to_numpy(float)
    base, _ = kde_curve(x, grid, bw=bw, sigma=se, pdp=pdp)
    gid = sel.grain.to_numpy()
    ug = np.unique(gid)
    rng = np.random.default_rng(seed)
    rows = {g_: np.flatnonzero(gid == g_) for g_ in ug}
    curves = []
    for _ in range(nboot):
        pick = rng.choice(ug, len(ug))
        ii = np.concatenate([rows[p] for p in pick])
        try:
            c, _ = kde_curve(x[ii], grid, bw=bw, sigma=None if se is None else se[ii], pdp=pdp)
            curves.append(c)
        except ValueError:
            continue
    c = np.array(curves)
    if len(c) == 0:
        return base, None, None, None, None
    return base, *np.percentile(c, [2.5, 16, 84, 97.5], axis=0)


def estimator_compare(ctx, sel):
    """The 206Pb/238U date of one pixel set by four estimators: pooled counts (ratio of sums), mean of the pixel ratios, median of the pixel
    ratios and the geometric mean (mean of log ratios, pixels with a zero or negative ratio left out). The gap between the first and the
    others is the bias of working on per-pixel ratios at the count rates of this set."""
    idx = _zr_idx(ctx, sel)
    a, b = ctx.rat["206Pb/238U"]
    iy = idx // ctx.nx
    na, nb = a.ravel()[idx] * ctx.fac["206Pb/238U"][iy], b.ravel()[idx]
    ok = np.isfinite(na) & np.isfinite(nb) & (nb > 0)
    na, nb = na[ok], nb[ok]
    out = dict(n_pix=int(len(na)))
    if len(na) == 0:
        return out
    r = na / nb
    pos = r > 0
    est = {"pooled": na.sum() / nb.sum(), "mean of ratios": r.mean(), "median of ratios": float(np.median(r)),
           "geometric mean": float(np.exp(np.log(r[pos]).mean())) if pos.any() else np.nan}
    for k, v in est.items():
        out[k + " (Ma)"] = float(age_ma(v, "238"))
    if ctx.q and len(na) >= 20:                      # McLean et al. 2016: weighted log ratio of block ratios, with overdispersion
        a_, b_ = a.ravel()[idx][ok], b.ravel()[idx][ok]
        blocks = np.array_split(np.arange(len(na)), min(10, len(na) // 5))
        rb = np.array([na[bb].sum() / nb[bb].sum() if nb[bb].sum() > 0 else np.nan for bb in blocks])
        od = _zr_overdispersion(rb, np.array([a_[bb].sum() for bb in blocks]) / ctx.q, np.array([b_[bb].sum() for bb in blocks]) / ctx.q)
        if od:
            out["weighted block log ratio (Ma)"] = od["age206/238_wlr"]
            out["overdispersion (%)"] = od["overdisp_pct"]
    pm, mm = out["pooled (Ma)"], out["mean of ratios (Ma)"]      # a set with no radiogenic Pb has a pooled date of exactly 0
    out["pooled vs mean of ratios (%)"] = 100 * (mm / pm - 1) if (np.isfinite(pm) and np.isfinite(mm) and pm > 0) else np.nan
    out["pixels with ratio <= 0 (%)"] = float(100 * (~pos).mean())
    if ctx.q:
        out["206Pb ions per pixel"] = float(np.nansum(a.ravel()[idx]) / ctx.q / max(len(idx), 1))
        out["238U ions per pixel"] = float(np.nansum(b.ravel()[idx]) / ctx.q / max(len(idx), 1))
    return out


# ---- concordia age, Aitchison discordance (Vermeesch 2021) and overdispersion of block log ratios (McLean et al. 2016)
def _conc_model(t):
    t = np.asarray(t, float)
    r68 = np.expm1(L238 * t)
    return 1.0 / r68, (np.expm1(L235 * t) / r68) / U8_5


def _zr_concordia(r68, r76, l68, l76, g):
    """Single-set concordia age (Ludwig 1998) in Tera-Wasserburg space from the pooled 206Pb/238U and 207Pb/206Pb, with their covariance from
    the delete-a-block jackknife (the blocks left out one at a time). Also the perpendicular Aitchison distance da to the concordia curve
    (percent, positive above the curve) and the concordia distance dc from the ML composition on it. Returns a dict."""
    from scipy.optimize import minimize_scalar
    out = {}
    ok = np.isfinite(l68) & np.isfinite(l76) & (l68 > 0)
    if ok.sum() < 4 or r68 <= 0 or r76 <= 0:
        return out
    x = np.column_stack([1.0 / l68[ok], l76[ok]])
    m = len(x)
    cov = (m - 1) / m * (x - x.mean(0)).T @ (x - x.mean(0))
    r86 = 1.0 / r68
    with np.errstate(all="ignore"):
        # Aitchison distances work from the measured composition and need no covariance
        t68 = float(age_ma(r68, "238"))
        t76 = float(age_207_206(r76))
        if np.isfinite(t68) and np.isfinite(t76) and t68 > 0:
            dx = np.log(r86) + np.log(np.expm1(L238 * t76))
            dy = np.log(r76) - np.log(np.expm1(L235 * t68) / np.expm1(L238 * t68) / U8_5)
            if dx != 0:
                out["disc_da_pct"] = float(100 * dx * np.sin(np.arctan(dy / dx)))
        if not np.all(np.isfinite(cov)) or np.linalg.det(cov) <= 0:
            return out
        inv = np.linalg.inv(cov)
        d0 = np.array([r86, r76])

        def S(t):
            a, b = _conc_model(t)
            d = d0 - np.array([a, b])
            return float(d @ inv @ d)
        res = minimize_scalar(S, bounds=(1.0, 4500.0), method="bounded", options=dict(xatol=1e-4))
        t = float(res.x)
        h = max(t * 1e-3, 0.05)
        sec = (S(t + h) - 2 * S(t) + S(t - h)) / h ** 2
        out["age_conc"] = t
        out["age_conc_se"] = float(np.sqrt(2.0 / sec)) if sec > 0 else np.nan
        out["conc_chi2"] = float(res.fun)
        a, b = _conc_model(t)
        ex, ey = np.log(r86) - np.log(a), np.log(r76) - np.log(b)
        out["disc_dc_pct"] = float(100 * np.sign(t76 - t68) * np.hypot(ex, ey)) if np.isfinite(t76) else np.nan
    return out


def _zr_overdispersion(rb, s6, s8):
    """Weighted mean of the block log ratios with an extra variance term for scatter beyond Poisson counting (Galbraith's overdispersion, used
    for LA-ICPMS by McLean et al. 2016). rb are block ratios, s6 and s8 the ions of numerator and denominator in each block. Returns the
    overdispersion in percent of the ratio (0 for a set as uniform as counting allows), the weighted log-ratio date and its error."""
    from scipy.optimize import minimize_scalar
    rb, s6, s8 = np.asarray(rb, float), np.asarray(s6, float), np.asarray(s8, float)
    ok = np.isfinite(rb) & (rb > 0) & (s6 > 0) & (s8 > 0)
    if ok.sum() < 3:
        return {}
    x = np.log(rb[ok])
    v = 1.0 / s6[ok] + 1.0 / s8[ok]

    def nll(w):
        vv = v + w * w
        mu = np.sum(x / vv) / np.sum(1 / vv)
        return 0.5 * float(np.sum(np.log(vv) + (x - mu) ** 2 / vv))
    res = minimize_scalar(nll, bounds=(0.0, 2.0), method="bounded", options=dict(xatol=1e-5))
    w = float(res.x) if nll(float(res.x)) < nll(0.0) - 1e-9 else 0.0
    vv = v + w * w
    mu = float(np.sum(x / vv) / np.sum(1 / vv))
    se = float(np.sqrt(1.0 / np.sum(1 / vv)))
    r = float(np.exp(mu))
    t = float(age_ma(r, "238"))
    return {"overdisp_pct": 100 * w, "age206/238_wlr": t, "age206/238_wlr_se": se * r / (L238 * (1 + r))}


# ---- comparing distributions (Vermeesch 2013, Sundell and Saylor 2021)
def dz_compare(x1, x2, grid=None, bw="Silverman"):
    """Compare two sets of dates. D (Kolmogorov-Smirnov) and V (Kuiper) come from the empirical CDFs and are 0 for identical, 1 for disjoint.
    Similarity (Bhattacharyya), Likeness (1 minus Mismatch) and Cross-correlation (R2) come from KDEs on a shared grid, 1 for identical.
    No p values: they depend on the number of dates and not on the size of the difference (Vermeesch 2013)."""
    a, b = np.sort(np.asarray(x1, float)), np.sort(np.asarray(x2, float))
    a, b = a[np.isfinite(a)], b[np.isfinite(b)]
    allx = np.concatenate([a, b])
    F = np.searchsorted(a, allx, side="right") / len(a)
    G = np.searchsorted(b, allx, side="right") / len(b)
    d = F - G
    out = dict(ks_D=float(np.abs(d).max()), kuiper_V=float(max(d.max(), 0) + max((-d).max(), 0)))
    if grid is None:
        pad = 0.1 * max(np.ptp(allx), 1.0)
        grid = np.linspace(allx.min() - pad, allx.max() + pad, 500)
    try:
        f, _ = kde_curve(a, grid, bw=bw)
        g, _ = kde_curve(b, grid, bw=bw)
    except ValueError:                                   # too few distinct dates for a density (a draw of one grain twice)
        out.update(similarity=np.nan, likeness=np.nan, crosscorr_R2=np.nan)
        return out
    f, g = f / f.sum(), g / g.sum()
    out["similarity"] = float(np.sqrt(f * g).sum())
    out["likeness"] = float(1 - 0.5 * np.abs(f - g).sum())
    out["crosscorr_R2"] = float(np.corrcoef(f, g)[0, 1] ** 2)
    return out


def dz_compare_2d(p1, p2, ngrid=48):
    """The same measures for two bivariate sets of points (n by 2: date and a second variable such as U, Th/U or Hf). The CDF measures take
    the largest difference over the four quadrants (Peacock 1983). The KDE measures use a shared ngrid by ngrid grid, with both axes scaled
    to the pooled spread so neither dominates."""
    from scipy.stats import gaussian_kde
    A, B = np.asarray(p1, float), np.asarray(p2, float)
    A, B = A[np.isfinite(A).all(1)], B[np.isfinite(B).all(1)]
    pool = np.vstack([A, B])
    mu, sd = pool.mean(0), pool.std(0)
    sd[sd == 0] = 1
    A, B, pool = (A - mu) / sd, (B - mu) / sd, (pool - mu) / sd
    dmax, vmax = 0.0, 0.0
    for sx in (1, -1):
        for sy in (1, -1):
            fa = np.array([np.mean((sx * (A[:, 0] - p[0]) >= 0) & (sy * (A[:, 1] - p[1]) >= 0)) for p in pool])
            fb = np.array([np.mean((sx * (B[:, 0] - p[0]) >= 0) & (sy * (B[:, 1] - p[1]) >= 0)) for p in pool])
            d = fa - fb
            dmax = max(dmax, float(np.abs(d).max()))
            vmax = max(vmax, float(max(d.max(), 0) + max((-d).max(), 0)))
    out = dict(ks_D=dmax, kuiper_V=vmax)
    lo, hi = pool.min(0) - 0.5, pool.max(0) + 0.5
    gx, gy = np.meshgrid(np.linspace(lo[0], hi[0], ngrid), np.linspace(lo[1], hi[1], ngrid))
    pts = np.vstack([gx.ravel(), gy.ravel()])
    f = gaussian_kde(A.T)(pts)
    g = gaussian_kde(B.T)(pts)
    f, g = f / f.sum(), g / g.sum()
    out["similarity"] = float(np.sqrt(f * g).sum())
    out["likeness"] = float(1 - 0.5 * np.abs(f - g).sum())
    out["crosscorr_R2"] = float(np.corrcoef(f, g)[0, 1] ** 2)
    return out


# ---- pixel quality filter and pixel-level date options
def zr_filter(ctx, min_238=0.0, min_206=0.0, nonpositive=True, age_min=None, age_max=None, apply_to_pooled=False):
    """Decide which pixels count in pixel-level statistics (mean of pixel dates, mean ratio, geometric mean, median, Tera-Wasserburg).
    min_238 and min_206 are ions per pixel after the Morgan background (cps when the counts per ion are unknown). nonpositive drops pixels
    with a zero or negative 206Pb, 238U or ratio. age_min and age_max bound the pixel 206/238 date in Ma.
    Pooled counts are unbiased with every pixel in, so the filter leaves them alone unless apply_to_pooled is set. Filtering on the 206Pb
    counts selects on the outcome and biases the date upwards, so keep min_206 low and prefer min_238."""
    q = ctx.q or 1.0
    n6 = ctx.sig["206Pb"] / q
    n8 = ctx.sig["238U"] / q
    with np.errstate(all="ignore"):
        r = n6 / n8 * ctx.fac["206Pb/238U"][:, None]
        ok = ctx.region & np.isfinite(n6) & np.isfinite(n8) & (n8 >= min_238) & (n6 >= min_206)
        if nonpositive:
            ok &= (n6 > 0) & (n8 > 0) & (r > 0)
        else:
            ok &= n8 != 0
        if age_min is not None or age_max is not None:
            t = age_ma(r, "238")
            if age_min is not None:
                ok &= t >= age_min
            if age_max is not None:
                ok &= t <= age_max
    ctx.pixok = ok
    ctx.filter_pooled = bool(apply_to_pooled)
    ctx.filter = dict(min_238=min_238, min_206=min_206, nonpositive=nonpositive, age_min=age_min, age_max=age_max, apply_to_pooled=bool(apply_to_pooled))
    return dict(usable=int(ctx.region.sum()), kept=int(ok.sum()), dropped_pct=float(100 * (1 - ok.sum() / max(ctx.region.sum(), 1))))


def _zr_pixel_stats(ctx, sel, g=10):
    """Dates from the pixels that pass the filter: mean of the pixel 206/238 dates, their median, the date of the mean ratio, the date of
    the geometric mean ratio (mean of log ratios), and the mean of the pixel 207Pb-corrected dates. Jackknife errors from g spatial blocks."""
    idx = _zr_idx(ctx, sel, pixel=True)
    tot = len(_zr_idx(ctx, sel))
    n = len(idx)
    out = dict(n_pix_good=int(n), frac_pix_good=float(n / tot) if tot else np.nan)
    if n < 3:
        return out
    iy = idx // ctx.nx
    a, b = ctx.rat["206Pb/238U"]
    n6, n8 = a.ravel()[idx], b.ravel()[idx]
    f68 = ctx.fac["206Pb/238U"][iy]
    with np.errstate(all="ignore"):
        r = n6 * f68 / n8
        t = age_ma(r, "238")
    have76 = "207Pb/206Pb" in ctx.rat and "207Pb/206Pb" in ctx.fac
    if have76:
        n7 = ctx.rat["207Pb/206Pb"][0].ravel()[idx]
        f76 = ctx.fac["207Pb/206Pb"][iy]
        with np.errstate(all="ignore"):
            r76 = n7 * f76 / n6
            t7c = common_pb_207(r, r76)[0]

    def stats(m):
        o = {}
        tm = t[m]
        tm = tm[np.isfinite(tm)]
        o["age_pix_mean"] = float(tm.mean()) if tm.size else np.nan
        o["age_pix_median"] = float(np.median(tm)) if tm.size else np.nan
        o["age_ratio_mean"] = float(age_ma(r[m].mean(), "238")) if m.any() else np.nan
        rp = r[m & (r > 0)]
        o["age_geo_mean"] = float(age_ma(np.exp(np.log(rp).mean()), "238")) if rp.size else np.nan
        if have76:
            tc = t7c[m]
            tc = tc[np.isfinite(tc)]
            o["age207c_pix_mean"] = float(tc.mean()) if tc.size else np.nan
        return o
    full = stats(np.ones(n, bool))
    out.update(full)
    ge = int(min(g, n // 2)) if n >= 4 else 0
    if ge >= 3:
        leave = {k: [] for k in full}
        for bl in np.array_split(np.arange(n), ge):
            m = np.ones(n, bool)
            m[bl] = False
            for k, v in stats(m).items():
                leave[k].append(v)
        for k, v in leave.items():
            v = np.array(v)
            out[k + "_se"] = float(np.sqrt((ge - 1) / ge * np.sum((v - v.mean()) ** 2))) if np.isfinite(v).all() else np.nan
    return out


def filter_effect(ctx, sel, min_238=None, min_206=None):
    """What each pixel filter does to the date of a pixel set. Rows: filter, pixels kept, pooled date from all pixels (unchanged), pooled
    date from the kept pixels only, and the pixel-level dates from the kept pixels. A rise in the pooled date as min_206 grows is the
    selection bias of filtering on the numerator. Thresholds default to the 0, 10, 25 and 50th percentiles of the ions per pixel of the set."""
    keep = (ctx.pixok, ctx.filter_pooled, dict(ctx.filter))
    idx = _zr_idx(ctx, sel)
    q = ctx.q or 1.0
    n8 = np.nan_to_num(ctx.sig["238U"].ravel()[idx]) / q
    n6 = np.nan_to_num(ctx.sig["206Pb"].ravel()[idx]) / q
    if min_238 is None:
        min_238 = [float(np.percentile(n8, p)) for p in (0, 10, 25, 50)]
    if min_206 is None:
        min_206 = [float(np.percentile(n6, p)) for p in (10, 25, 50)]
    rows = []
    try:
        base = pixset_estimate(ctx, sel, pix=False)
        for label, kw in [(f"238U >= {m:.3g} ions", dict(min_238=m)) for m in min_238] + [(f"206Pb >= {m:.3g} ions", dict(min_206=m)) for m in min_206]:
            zr_filter(ctx, nonpositive=False, apply_to_pooled=True, **kw)
            e = pixset_estimate(ctx, sel, pix=True)
            rows.append({"filter": label, "pixels kept": e.get("n_pix_good", e["n_pix"]), "pooled, all pixels (Ma)": base["age206/238"],
                         "pooled, kept pixels (Ma)": e["age206/238"], "mean of pixel dates (Ma)": e.get("age_pix_mean", np.nan),
                         "date of mean ratio (Ma)": e.get("age_ratio_mean", np.nan), "date of geometric mean (Ma)": e.get("age_geo_mean", np.nan),
                         "median pixel date (Ma)": e.get("age_pix_median", np.nan)})
    finally:
        ctx.pixok, ctx.filter_pooled, ctx.filter = keep
    return pd.DataFrame(rows)


# ---- domains from date differences: count-based region merging, concentric depth bands, age bands
def _merge_regions(S6, S8, N6, N8, npx, edges, z=3.0, min_rel=0.02, od=0.0, min_px=15, has_q=True):
    """Merge neighbouring regions of a graph until every neighbouring pair differs by more than counting statistics allow.

    Each region holds the scaled 206Pb sum S6 and the 238U sum S8 (the ratio S6/S8 is the pooled ratio), the ions N6 and N8 behind
    them and its pixel count npx.

    The pair statistic is z = |ln ra - ln rb| / sqrt(va + vb) with v = 1/N6 + 1/N8 + od^2. A pair is merged when it is within z
    standard errors or closer than min_rel (relative ratio difference, about the relative date difference). Without ion counts
    (has_q False) the rule is the relative difference alone, at least 5 percent. Regions below min_px pixels then join the
    neighbour they resemble most.

    Returns the root region of every region and the highest merge statistic reached. Run with z = inf, it is the height at which
    the whole graph becomes one region, which is what _null_height calibrates."""
    import heapq
    n = len(S6)
    S6, S8, N6, N8, npx = (np.asarray(a, float).copy() for a in (S6, S8, N6, N8, npx))
    adj = [set() for _ in range(n)]
    for a, b in edges:
        if a != b:
            adj[a].add(b)
            adj[b].add(a)
    alive = np.ones(n, bool)
    ver = np.zeros(n, int)
    root = np.arange(n)
    hmax = 0.0

    def lr(i):
        return np.log(max(S6[i], 1e-12) / max(S8[i], 1e-12))

    def score(i, j):
        dl = abs(lr(i) - lr(j))
        if dl < min_rel:
            return -1.0
        if not has_q:
            return z * dl / max(min_rel, 0.05)
        v = 1 / max(N6[i], 0.5) + 1 / max(N8[i], 0.5) + 1 / max(N6[j], 0.5) + 1 / max(N8[j], 0.5) + 2 * od * od
        return dl / np.sqrt(v)

    def absorb(i, j):                      # j into i
        S6[i] += S6[j]; S8[i] += S8[j]; N6[i] += N6[j]; N8[i] += N8[j]; npx[i] += npx[j]
        alive[j] = False
        root[root == j] = i
        for k in adj[j]:
            adj[k].discard(j)
            if k != i:
                adj[k].add(i)
                adj[i].add(k)
        adj[i].discard(j)
        adj[j] = set()
        ver[i] += 1

    heap = [(score(i, j), i, j, 0, 0) for i in range(n) for j in adj[i] if i < j]
    heapq.heapify(heap)
    while heap:
        s, i, j, vi, vj = heapq.heappop(heap)
        if not (alive[i] and alive[j]) or ver[i] != vi or ver[j] != vj or j not in adj[i]:
            continue
        if s >= z:
            break
        hmax = max(hmax, s)
        absorb(i, j)
        for k in adj[i]:
            heapq.heappush(heap, (score(i, k), min(i, k), max(i, k), ver[min(i, k)], ver[max(i, k)]))
    while True:                            # regions below min_px join their most similar neighbour
        small = [i for i in range(n) if alive[i] and npx[i] < min_px and adj[i]]
        if not small:
            break
        i = min(small, key=lambda t: npx[t])
        j = min(adj[i], key=lambda k: abs(lr(i) - lr(k)))
        absorb(j, i)
    return root, hmax


def _null_height(S6, S8, N6, N8, npx, edges, alpha, nsim, min_rel, od, has_q, seed):
    """Merge statistic that a grain of one uniform age would exceed with probability alpha.

    Merging most-alike-first sorts noise into a low group and a high group, so a fixed z (3, say) splits uniform grains. The
    grain's own counts are redrawn under one ratio (Poisson ions in every tile, the same tile sizes and graph), the graph is
    merged completely, and the 1 - alpha quantile of the highest merge statistic is the threshold. At least 3."""
    rng = np.random.default_rng(int(seed))
    N6t, N8t = max(N6.sum(), 1e-9), max(N8.sum(), 1e-9)
    f6, f8 = S6.sum() / N6t, S8.sum() / N8t
    h = []
    for _ in range(nsim):
        n8 = rng.poisson(np.maximum(N8, 0))
        n6 = rng.poisson(N6t * np.maximum(N8, 0) / N8t)
        _, hm = _merge_regions(n6 * f6, n8 * f8, n6, n8, npx, edges, z=np.inf, min_rel=0.0, od=od, min_px=0, has_q=has_q)
        h.append(hm)
    return max(3.0, float(np.quantile(h, 1 - alpha)))


def _trim_labs(labs, gm, trim_px):
    kept = np.zeros_like(labs)
    for k in np.unique(labs[labs > 0]):
        inner = ndi.binary_erosion((labs == k) | ~gm, iterations=int(trim_px), border_value=1) & (labs == k)
        kept[inner] = k
    for k in np.unique(kept[kept > 0]):
        if (kept == k).sum() < 5:
            kept[kept == k] = 0
    return kept


def _grain_sums(ctx, sl, labs, k):
    """Scaled 206Pb and 238U sums and ions for each label 1..k inside a cropped grain."""
    a, b = ctx.rat["206Pb/238U"]
    iy = np.arange(ctx.ny)[sl[0]][:, None]
    na = np.nan_to_num(a[sl]) * ctx.fac["206Pb/238U"][iy]
    nb = np.nan_to_num(b[sl])
    q = ctx.q or 1.0
    l = labs.ravel()
    S6 = np.bincount(l, na.ravel(), minlength=k + 1)
    S8 = np.bincount(l, nb.ravel(), minlength=k + 1)
    N6 = np.bincount(l, np.nan_to_num(a[sl]).ravel() / q, minlength=k + 1)
    N8 = np.bincount(l, nb.ravel() / q, minlength=k + 1)
    return S6, S8, N6, N8, np.bincount(l, minlength=k + 1).astype(float)


def _emit_domains(ctx, dom, rows, nid, gid, sl, labs, names=None):
    """Write the labels of one grain into the domain image.

    Domains are numbered D1, D2 ... from the lowest pooled 206/238 up, or named by the dict names (label -> kind). A grain with
    one domain is 'whole'."""
    ks = [int(k) for k in np.unique(labs[labs > 0])]
    if names is None:
        S6, S8, *_ = _grain_sums(ctx, sl, labs, max(ks) if ks else 0)
        with np.errstate(all="ignore"):
            ks.sort(key=lambda k: S6[k] / S8[k] if S8[k] > 0 else np.inf)
        names = {k: (f"D{j + 1}" if len(ks) > 1 else "whole") for j, k in enumerate(ks)}
    for k in ks:
        pm = labs == k
        dom[sl][pm] = nid
        rows.append((nid, gid, ctx.grain_mineral.get(gid, ""), names[k], int(pm.sum()), float(pm.sum() * ctx.dx * ctx.dy)))
        nid += 1
    return nid


def _tile_graph(m, t):
    """Square tiles of t by t pixels cut from the mask m, with the tile adjacency from 4-connected pixel neighbours. Returns tile index of
    every pixel (-1 outside), the number of tiles and the edge list."""
    yy, xx = np.indices(m.shape)
    code = (yy // t) * (m.shape[1] // t + 2) + xx // t
    tid = -np.ones(m.shape, int)
    u, inv = np.unique(code[m], return_inverse=True)
    tid[m] = inv
    ed = set()
    for a, b in ((tid[:, :-1], tid[:, 1:]), (tid[:-1, :], tid[1:, :])):
        ok = (a >= 0) & (b >= 0) & (a != b)
        for p, q_ in set(zip(a[ok].tolist(), b[ok].tolist())):
            ed.add((min(p, q_), max(p, q_)))
    return tid, len(u), list(ed)


def domain_merge(ctx, init_px=2, z=None, min_rel=0.02, min_px=15, ids=None, trim_px=0, od_pct=0.0, alpha=0.01, nsim=50):
    """Domains by merging. Each grain is cut into small square tiles. Neighbouring tiles are merged, most alike first, until every
    neighbouring pair of regions differs in pooled 206Pb/238U by more than z standard errors from counting statistics (plus an allowance
    od_pct for scatter beyond counting) and by more than min_rel in relative terms. No smoothing, no assumed number of domains and no
    assumed shape: a core, a mantle and a rim come out when their dates differ, and a grain with no resolvable difference stays whole.
    Domains are numbered from the lowest 206/238 up. trim_px leaves out the pixels next to another domain."""
    dom = np.zeros((ctx.ny, ctx.nx), np.int32)
    rows, nid = [], 1
    notes = ctx.merge_z = {}
    for gid, sl in _grain_boxes(ctx.lab):
        if ids is not None and gid not in ids:
            continue
        gm = ctx.lab[sl] == gid
        m = gm & ctx.region[sl]
        if not m.any():
            continue
        tid, nt, ed = _tile_graph(m, max(int(init_px), 1))
        S6, S8, N6, N8, npx = _grain_sums(ctx, sl, np.where(tid >= 0, tid + 1, 0), nt)
        zz = z if z is not None else _null_height(S6[1:], S8[1:], N6[1:], N8[1:], npx[1:], ed, alpha, nsim, min_rel, od_pct / 100.0, bool(ctx.q), gid)
        notes[gid] = float(zz)
        root, _ = _merge_regions(S6[1:], S8[1:], N6[1:], N8[1:], npx[1:], ed, z=zz, min_rel=min_rel, od=od_pct / 100.0, min_px=min_px, has_q=bool(ctx.q))
        _, rl = np.unique(root, return_inverse=True)
        labs = np.where(tid >= 0, rl[np.clip(tid, 0, None)] + 1, 0).astype(np.int32)
        if trim_px and len(np.unique(labs[labs > 0])) > 1:
            labs = _trim_labs(labs, gm, trim_px)
        nid = _emit_domains(ctx, dom, rows, nid, gid, sl, labs)
    return _finish_domains(ctx, dom, rows)


def domain_profile(ctx, bin_um=None, z=None, min_rel=0.02, min_px=15, ids=None, od_pct=0.0, trim_px=0, alpha=0.01, nsim=50):
    """Concentric bands. Each grain is cut into bins of depth from its edge (bin_um, default the pixel size), and neighbouring bins are merged
    with the same count test as domain_merge. The result is a rim, any number of mantles and a core, as rings, which is the shape growth
    zoning of a grain usually has and uses every pixel of a ring for the test. Kinds: whole, rim and core, or rim, mantle1 ... and core
    counted from the outside in."""
    bin_um = bin_um or min(ctx.dx, ctx.dy)
    dom = np.zeros((ctx.ny, ctx.nx), np.int32)
    rows, nid = [], 1
    notes = ctx.merge_z = {}
    for gid, sl in _grain_boxes(ctx.lab):
        if ids is not None and gid not in ids:
            continue
        gm = ctx.lab[sl] == gid
        m = gm & ctx.region[sl]
        if not m.any():
            continue
        depth = _depth_in_grain(ctx, gm)
        b = np.where(m, np.floor(np.maximum(depth, 0) / bin_um).astype(int), -1)
        u, inv = np.unique(b[m], return_inverse=True)
        tid = -np.ones(m.shape, int)
        tid[m] = inv
        nt = len(u)
        S6, S8, N6, N8, npx = _grain_sums(ctx, sl, np.where(tid >= 0, tid + 1, 0), nt)
        ed = [(i, i + 1) for i in range(nt - 1)]
        zz = z if z is not None else _null_height(S6[1:], S8[1:], N6[1:], N8[1:], npx[1:], ed, alpha, nsim, min_rel, od_pct / 100.0, bool(ctx.q), gid)
        notes[gid] = float(zz)
        root, _ = _merge_regions(S6[1:], S8[1:], N6[1:], N8[1:], npx[1:], ed, z=zz, min_rel=min_rel, od=od_pct / 100.0, min_px=min_px, has_q=bool(ctx.q))
        _, rl = np.unique(root, return_inverse=True)       # root ids rise with bin index, so labels run from the rim inward
        labs = np.where(tid >= 0, rl[np.clip(tid, 0, None)] + 1, 0).astype(np.int32)
        k = int(labs.max())
        names = {1: "whole"} if k == 1 else {j: ("rim" if j == 1 else "core" if j == k else f"mantle{j - 1}") for j in range(1, k + 1)}
        if trim_px and k > 1:
            labs = _trim_labs(labs, gm, trim_px)
        nid = _emit_domains(ctx, dom, rows, nid, gid, sl, labs, names={kk: names[kk] for kk in np.unique(labs[labs > 0])})
    return _finish_domains(ctx, dom, rows)


def domain_agebands(ctx, edges, sigma=1.0, min_px=15, ids=None, trim_px=0):
    """Domains from age intervals you set. The 206/238 date image of each grain is smoothed (counts first, then the ratio) and split at
    the edges (Ma), so edges (700, 1400) give three bands: below 700, 700 to 1400 and above 1400. Use it when the ages you are after
    are known, for example to map one population across all grains. Kinds are A1 (youngest band) up."""
    edges = np.sort(np.asarray(edges, float))
    k = len(edges) + 1
    dom = np.zeros((ctx.ny, ctx.nx), np.int32)
    rows, nid = [], 1
    for gid, sl in _grain_boxes(ctx.lab):
        if ids is not None and gid not in ids:
            continue
        gm = ctx.lab[sl] == gid
        m = gm & ctx.region[sl]
        if not m.any():
            continue
        f = zr_feature(ctx, "pbu", sl, m, sigma)
        with np.errstate(all="ignore"):
            t = age_ma(10.0 ** f, "238")
        ok = m & np.isfinite(t)
        labs = np.zeros(m.shape, np.int32)
        labs[ok] = np.digitize(t[ok], edges) + 1
        if len(np.unique(labs[labs > 0])) > 1:
            labs = _majority(labs, m, k, sigma=max(sigma, 1.0))
            labs = _merge_small(labs, m, min_px)
        miss = m & (labs == 0)
        if miss.any() and (labs > 0).any():
            ind = ndi.distance_transform_edt(labs == 0, return_indices=True)[1]
            labs[miss] = labs[tuple(ind[:, miss])]
        if not labs.any():
            labs[m] = 1
        if trim_px and len(np.unique(labs[labs > 0])) > 1:
            labs = _trim_labs(labs, gm, trim_px)
        nid = _emit_domains(ctx, dom, rows, nid, gid, sl, labs, names={int(j): f"A{int(j)}" for j in np.unique(labs[labs > 0])})
    return _finish_domains(ctx, dom, rows)


# ---- what changes when more grains are measured or a larger area is mapped
def subsample_grains(tab, rule="grain", date="age206/238", ns=(5, 10, 20, 40, 80, 160), reps=200, seed=0, replace=False, max_disc=None, min_px=0, query=None):
    """Draw n grains at random from the mapped population and compare the sample with the whole population (D and likeness). Without
    replacement n stops at the number of grains mapped, where the sample is the population. With replacement, n can go beyond it, which
    shows how a larger sample of a population like this one would behave. Returns the median and the 5 to 95 percent range over reps draws."""
    sel = pop_select(tab, rule, date, max_disc=max_disc, min_px=min_px, query=query)
    gid = sel.grain.to_numpy()
    x = sel[date].to_numpy(float)
    ug = np.unique(gid)
    G = len(ug)
    rows_of = {g_: np.flatnonzero(gid == g_) for g_ in ug}
    rng = np.random.default_rng(seed)
    grid = np.linspace(x.min() - 0.1 * max(np.ptp(x), 1), x.max() + 0.1 * max(np.ptp(x), 1), 300)
    out = []
    import warnings
    warnings.filterwarnings("ignore", message="All-NaN slice")
    for n in ns:
        if n < 2 or (not replace and n > G):
            continue
        D, L = [], []
        for _ in range(reps):
            pick = rng.choice(ug, n, replace=replace)
            xs = x[np.concatenate([rows_of[p] for p in pick])]
            c = dz_compare(xs, x, grid=grid)
            D.append(c["ks_D"]); L.append(c["likeness"])
        D, L = np.array(D), np.array(L)
        out.append(dict(n=int(n), D_med=float(np.median(D)), D_lo=float(np.percentile(D, 5)), D_hi=float(np.percentile(D, 95)),
                        likeness_med=float(np.nanmedian(L)), likeness_lo=float(np.nanpercentile(L, 5)), likeness_hi=float(np.nanpercentile(L, 95))))
    res = pd.DataFrame(out)
    res.attrs["grains_in_population"] = G
    return res


def subsample_windows(ctx, tab, areas_um2, reps=100, aspect=1.0, target=None, min_px=20, date="age206/238", seed=0):
    """Mapping a smaller part of the sample: random rectangular windows of each area (aspect = width / height) placed inside the map. For each
    area: the median number of grains and of domains with at least min_px pixels in the window, the probability that the window holds a domain
    (or, without domains, a grain) dated inside target = (lo, hi) Ma, and the D of the grain dates in the window against all grains in the map.
    The window is clipped to the map, so areas above the mapped area give the whole map."""
    rng = np.random.default_rng(seed)
    gt = tab[tab.kind == "grain"]
    gdate = dict(zip(gt.grain.astype(int), gt[date]))
    full = gt[date].to_numpy(float)
    full = full[np.isfinite(full)]
    dt = tab[tab.kind != "grain"]
    use_dom = len(dt) > 0 and bool((ctx.dom > 0).any())
    tg = None
    if target is not None:
        src = dt if use_dom else gt
        tg = src[np.isfinite(src[date]) & (src[date] >= target[0]) & (src[date] <= target[1])]
    ng = int(ctx.lab.max()) + 1
    nd = int(ctx.dom.max()) + 1
    out = []
    for A in areas_um2:
        w = int(np.clip(round(np.sqrt(A * aspect) / ctx.dx), 1, ctx.nx))
        h = int(np.clip(round(np.sqrt(A / aspect) / ctx.dy), 1, ctx.ny))
        ngr, ndo, hit, D = [], [], [], []
        for _ in range(reps):
            y0 = int(rng.integers(0, ctx.ny - h + 1))
            x0 = int(rng.integers(0, ctx.nx - w + 1))
            sl = (slice(y0, y0 + h), slice(x0, x0 + w))
            rg = ctx.region[sl]
            cg = np.bincount(ctx.lab[sl][rg], minlength=ng)
            gs = np.flatnonzero(cg >= min_px)
            gs = gs[gs > 0]
            ngr.append(len(gs))
            if use_dom:
                cd = np.bincount(ctx.dom[sl][rg], minlength=nd)
                ds = np.flatnonzero(cd >= min_px)
                ds = ds[ds > 0]
                ndo.append(len(ds))
            if tg is not None:
                if use_dom:
                    hit.append(bool(np.isin(tg.dom.to_numpy(), ds).any()))
                else:
                    hit.append(bool(np.isin(tg.grain.to_numpy(), gs).any()))
            xs = np.array([gdate[g_] for g_ in gs if g_ in gdate and np.isfinite(gdate[g_])])
            if len(xs) >= 2 and len(full) >= 2:
                D.append(dz_compare(xs, full)["ks_D"])
        row = dict(area_um2=float(A), width_um=w * ctx.dx, height_um=h * ctx.dy, grains_med=float(np.median(ngr)),
                   grains_lo=float(np.percentile(ngr, 5)), grains_hi=float(np.percentile(ngr, 95)))
        if use_dom:
            row["domains_med"] = float(np.median(ndo))
        if tg is not None:
            row["p_target"] = float(np.mean(hit))
        row["D_med"] = float(np.median(D)) if D else np.nan
        row["D_hi"] = float(np.percentile(D, 95)) if D else np.nan
        out.append(row)
    return pd.DataFrame(out)


# ---- maximum depositional age: the ten methods of Sundell et al. (2024, DZmda) and the maximum likelihood age (Vermeesch 2021)
MDA_METHODS = ("YSG", "YPP", "YGF", "YGC1s", "YGC2s", "Y3Zo", "Y3Za", "TAU", "YSP", "MLA")


def _wmean(t, s):
    w = 1.0 / np.asarray(s, float) ** 2
    m = float(np.sum(w * t) / np.sum(w))
    se = float(np.sqrt(1.0 / np.sum(w)))
    n = len(t)
    mswd = float(np.sum(w * (t - m) ** 2) / (n - 1)) if n > 1 else np.nan
    return m, se, mswd


def mda_mla(t, s, nstart=12):
    """Maximum likelihood age (Galbraith and Laslett 1993, normal errors as in Galbraith 2005 p.107, three parameter form of
    Vermeesch 2021).

    The dates (log scale, relative errors s/t) come from a mixture: a fraction p at one minimum age exp(g), the rest from a normal
    distribution in log age truncated at g (location g, spread sigma).

    Returns age, 1 sigma standard error from the observed information, p, sigma (percent), and the number of dates. The model
    needs about 5 dates or more."""
    from scipy.optimize import minimize
    from scipy.stats import norm
    t, s = np.asarray(t, float), np.asarray(s, float)
    ok = np.isfinite(t) & np.isfinite(s) & (t > 0) & (s > 0)
    t, s = t[ok], s[ok]
    if len(t) < 4:
        return {}
    z, se = np.log(t), s / t
    v0 = se ** 2

    def nll(par):
        g, lp, ls = par
        p = 1 / (1 + np.exp(-lp))
        sg = np.exp(ls)
        v = v0 + sg ** 2
        f1 = norm.pdf(z, g, se)
        m = (z * sg ** 2 + g * v0) / v
        sd = np.sqrt(v0 * sg ** 2 / v)
        f2 = 2 * norm.pdf(z, g, np.sqrt(v)) * norm.sf((g - m) / sd)
        f = p * f1 + (1 - p) * f2
        return -float(np.sum(np.log(np.maximum(f, 1e-300))))

    zs = np.sort(z)
    best = None
    rng = np.random.default_rng(0)
    for k in range(nstart):
        g0 = zs[min(k % 3, len(zs) - 1)] + (0.0 if k < 3 else rng.normal(0, 0.05))
        p0 = [-1.0, 0.0, 1.0][k % 3]
        r = minimize(nll, [g0, p0, np.log(max(np.std(z), 0.02))], method="Nelder-Mead", options=dict(xatol=1e-7, fatol=1e-9, maxiter=4000))
        if best is None or r.fun < best.fun:
            best = r
    g, lp, ls = best.x
    # standard error of g from the numerical Hessian
    h = np.array([1e-4, 1e-3, 1e-3])
    H = np.zeros((3, 3))
    f0 = best.fun
    for i in range(3):
        for j in range(i, 3):
            ei, ej = np.eye(3)[i] * h[i], np.eye(3)[j] * h[j]
            H[i, j] = H[j, i] = (nll(best.x + ei + ej) - nll(best.x + ei - ej) - nll(best.x - ei + ej) + nll(best.x - ei - ej)) / (4 * h[i] * h[j])
    try:
        sg_ = float(np.sqrt(np.linalg.inv(H)[0, 0]))
    except np.linalg.LinAlgError:
        sg_ = np.nan
    if not np.isfinite(sg_):
        sg_ = np.nan
    age = float(np.exp(g))
    return dict(age=age, se=age * sg_ if np.isfinite(sg_) else np.nan, p=float(1 / (1 + np.exp(-lp))), sigma_pct=float(100 * np.exp(ls)), n=int(len(t)))


def _gauss_fit(x, y, mode0):
    """Fit y = a exp(-((x - b) / c)^2) as MATLAB's gauss1 does. Returns mode b and standard deviation c / sqrt(2)."""
    from scipy.optimize import curve_fit
    f = lambda x_, a, b, c: a * np.exp(-((x_ - b) / c) ** 2)
    try:
        popt, _ = curve_fit(f, x, y, p0=[y.max(), mode0, max((x[-1] - x[0]) / 2, 1e-3)], maxfev=5000)
        return float(popt[1]), float(abs(popt[2]) / np.sqrt(2))
    except Exception:
        return np.nan, np.nan


def _pdp(t, s, xint, lo=None, hi=None):
    """Probability density plot of normal dates (1 sigma errors) on a grid, normalised to sum 1 (pdp5.m of DZmda)."""
    from scipy.signal import find_peaks
    lo = max(0.0, float((t - 6 * s).min())) if lo is None else lo
    hi = float((t + 6 * s).max()) if hi is None else hi
    x = np.arange(lo, hi + xint, xint)
    p = np.zeros_like(x)
    for ti, si in zip(t, s):
        p += np.exp(-0.5 * ((x - ti) / si) ** 2) / (si * np.sqrt(2 * np.pi)) * xint
    return x, p / p.sum()


def mda_methods(t, s, sys_pct=0.0, peak_n=2, methods=MDA_METHODS, sort_hi=True, include_youngest=True, xint=0.1):
    """Maximum depositional age by the ten methods of Sundell et al. (2024), ported from the DZmda program (github.com/kurtsundell/DZmda, default
    settings), plus the maximum likelihood age of Vermeesch (2021). t are dates (Ma) and s their 1 sigma errors, sys_pct is added in quadrature
    (percent of the date, for example the scatter of a secondary reference material).
    YSG       the date with the lowest age + 2 sigma (sort_hi) or the lowest date, with its error.
    YPP, YGF  Gaussian fit to the youngest probability density peak that has at least peak_n dates overlapping its mode +- 2 sigma. The fit window runs
              from the peak to the nearest trough on either side. YPP is the fitted mode and YGF the mode with the fitted sigma. peak_n = None uses
              the first peak (YPP) and the fit up to the first trough (YGF).
    YGC1s     weighted mean of the dates, sorted by age + 1 sigma, whose 1 sigma lower bound is below the upper bound of the first.
    YGC2s     the same at 2 sigma, needing 3 or more dates.  Y3Zo is the first three of the YGC2s group, Y3Za the three youngest dates.
    TAU       weighted mean of the dates inside the youngest peak (mode +- 2 sigma of the fit), or below the first trough when peak_n is None.
    YSP       weighted mean of the youngest n dates with the MSWD closest to 1 (n = 2 to N). When include_youngest is False and no MSWD is below 1,
              the youngest date is dropped and the search repeated.
    MLA       maximum likelihood age.
    Errors are 1 sigma, the standard error of the weighted mean without MSWD inflation (as DZmda reports it), and the MSWD is given. Returns a table."""
    from scipy.signal import find_peaks
    t, s = np.asarray(t, float), np.asarray(s, float)
    ok = np.isfinite(t) & np.isfinite(s) & (t > 0) & (s > 0)
    t, s = t[ok], s[ok]
    s = np.sqrt(s ** 2 + (sys_pct / 100 * t) ** 2)
    o = np.argsort(t, kind="stable")
    t, s = t[o], s[o]
    N = len(t)
    rows = []

    def add(name, mda, se, n, mswd=np.nan):
        rows.append(dict(method=name, mda=float(mda), se=float(se), n=int(n), mswd=float(mswd)))

    def none(name):
        add(name, np.nan, np.nan, 0)

    def wm(d, name):
        if len(d) == 0:
            return none(name)
        m, se, ms = _wmean(d[:, 0], d[:, 1])
        add(name, m, se, len(d), ms)

    D = np.column_stack([t, s])

    def sorted_by(k):
        return D[np.argsort(t + k * s, kind="stable")] if sort_hi else D

    def cluster(k):
        d = sorted_by(k)
        hi, lo = d[:, 0] + k * d[:, 1], d[:, 0] - k * d[:, 1]
        if include_youngest:
            fail = np.flatnonzero(~(lo < hi[0]))
            return d[:fail[0] if fail.size else len(d)]
        ov = hi[None, :] > lo[:, None]                   # ov[j, i]: upper bound of i above the lower bound of j (DZmda matrix, transposed)
        need = 1 if k == 1 else 2
        for i in range(len(d) - need):
            if all(ov[i + 1 + q, i] for q in range(need)):
                nxt = np.flatnonzero(~ov[:, i])
                return d[i:nxt[0] if nxt.size else len(d)]
        return d[:0]

    x = pdp = None
    mode = lo2 = hi2 = sd = None
    need_peak = any(m in methods for m in ("YPP", "YGF", "TAU"))
    first_trough = None
    if need_peak and N >= 1:
        x, pdp = _pdp(t, s, xint)
        pk, _ = find_peaks(pdp)
        tr, _ = find_peaks(-pdp)
        first_trough = x[tr[0]] if len(tr) else None
        if peak_n is None:
            if len(tr):
                j = np.flatnonzero(pdp[:tr[0] + 1] > 1e-6 * pdp.max())
                seg = slice(j[0] if j.size else 0, tr[0] + 1)
            else:
                seg = slice(0, len(x))
            mode, sd = _gauss_fit(x[seg], pdp[seg], x[pk[0]] if len(pk) else x[np.argmax(pdp)])
            lo2, hi2 = (mode - 2 * sd, mode + 2 * sd) if np.isfinite(mode) else (None, None)
            n_in = int(((t > lo2) & (t < hi2)).sum()) if lo2 is not None else 0
        else:
            n_in = 0
            for p in (pk if len(pk) else [int(np.argmax(pdp))]):
                if len(tr):
                    dist = np.abs(x[tr] - x[p]).min()
                    w = (x >= x[p] - dist) & (x <= x[p] + dist)
                else:
                    w = np.ones(len(x), bool)
                m_, sd_ = _gauss_fit(x[w], pdp[w], x[p])
                if not np.isfinite(m_):
                    continue
                l_, h_ = m_ - 2 * sd_, m_ + 2 * sd_
                cnt = int(((t + 2 * s > l_) & (t - 2 * s < h_)).sum())
                mode, sd, lo2, hi2, n_in = m_, sd_, l_, h_, cnt
                if cnt >= peak_n:
                    break

    for name in methods:
        if N == 0:
            break
        if name == "YSG":
            d = sorted_by(2)
            add(name, d[0, 0], d[0, 1], 1)
        elif name == "YPP":
            add(name, mode, np.nan, n_in) if mode is not None and np.isfinite(mode) else none(name)
        elif name == "YGF":
            add(name, mode, sd, n_in) if mode is not None and np.isfinite(mode) else none(name)
        elif name == "YGC1s":
            wm(cluster(1), name)
        elif name == "YGC2s":
            d = cluster(2)
            wm(d, name) if len(d) > 2 else none(name)
        elif name == "Y3Zo":
            d = cluster(2)
            wm(d[:3], name) if len(d) > 2 else none(name)
        elif name == "Y3Za":
            wm(D[:3], name) if N >= 3 else none(name)
        elif name == "TAU":
            if peak_n is None:
                wm(D[D[:, 0] < first_trough] if first_trough is not None else D, name)
            elif mode is not None and np.isfinite(mode):
                d = D[(D[:, 0] > lo2) & (D[:, 0] < hi2)]
                wm(d, name) if len(d) >= peak_n else none(name)
            else:
                none(name)
        elif name == "YSP":
            def best(d):
                if len(d) < 2:
                    return None
                ms = [(_wmean(d[:i + 1, 0], d[:i + 1, 1]), i + 1) for i in range(1, len(d))]
                k = int(np.argmin([abs(1 - m[0][2]) for m in ms]))
                return ms[k]
            r = best(D)
            if r is not None and not include_youngest:
                allms = [_wmean(D[:i + 1, 0], D[:i + 1, 1])[2] for i in range(1, N)]
                if min(allms) > 1:                       # drop the youngest date until some group has an MSWD below 1
                    r = None
                    for j in range(1, N - 1):
                        sub = D[j:]
                        ms = [(_wmean(sub[:i + 1, 0], sub[:i + 1, 1]), i + 1) for i in range(1, len(sub))]
                        if ms and min(m[0][2] for m in ms) < 1:
                            r = ms[int(np.argmin([abs(1 - m[0][2]) for m in ms]))]
                            break
            if r is None:
                none(name)
            else:
                add(name, r[0][0], r[0][1], r[1], r[0][2])
        elif name == "MLA":
            r = mda_mla(t, s)
            add(name, r.get("age", np.nan), r.get("se", np.nan), r.get("n", 0))
    return pd.DataFrame(rows)


def mda_vs_n(t, s, ns=(5, 10, 20, 50, 100, 200), reps=30, sys_pct=0.0, methods=MDA_METHODS, seed=0, peak_n=2, xint=0.5):
    """How each MDA method behaves as more grains are measured: n dates drawn at random with replacement from the given dates (and their errors),
    every method applied to each draw. Returns the median and the 16 to 84 percent range of the MDA for every method and n. Methods that depend on the
    youngest tail drift to younger ages as n grows (Vermeesch 2021)."""
    rng = np.random.default_rng(seed)
    t, s = np.asarray(t, float), np.asarray(s, float)
    out = []
    for n in ns:
        res = {m: [] for m in methods}
        for _ in range(reps):
            i = rng.integers(0, len(t), n)
            d = mda_methods(t[i], s[i], sys_pct=sys_pct, peak_n=peak_n, methods=methods, xint=xint)
            for r in d.itertuples():
                res[r.method].append(r.mda)
        for m in methods:
            a = np.array(res[m], float)
            a = a[np.isfinite(a)]
            out.append(dict(method=m, n=int(n), med=float(np.median(a)) if a.size else np.nan, lo=float(np.percentile(a, 16)) if a.size else np.nan,
                            hi=float(np.percentile(a, 84)) if a.size else np.nan, frac_ok=float(a.size / reps)))
    return pd.DataFrame(out)


# ---- systematic and external uncertainty (Quantify tab settings) carried to dates
def _f68(t_ma):
    """d ln t / d ln r for 206Pb/238U dates."""
    x = L238 * np.asarray(t_ma, float)
    with np.errstate(all="ignore"):
        return -np.expm1(-x) / x


def _f75(t_ma):
    x = L235 * np.asarray(t_ma, float)
    with np.errstate(all="ignore"):
        return -np.expm1(-x) / x


def sys_date_pct(kind, t_ma, r76, cfg):
    """Systematic relative uncertainty (percent, 1 sigma) of a date from the reference material ratio uncertainties and the decay constants,
    plus the blanket external reproducibility, all in quadrature. kind is '68' (dates from 206Pb/238U, concordia, Tera-Wasserburg), '75'
    (207Pb/235U) or '76' (207Pb/206Pb, r76 is the measured ratio). Returns an array like t_ma."""
    t = np.asarray(t_ma, float)
    comp = [np.full_like(t, cfg.ext_pct)]
    if kind == "68":
        comp.append(cfg.sys_rm68_pct * _f68(t))
        if cfg.sys_decay:
            comp.append(np.full_like(t, cfg.sys_l238_pct))
    elif kind == "75":
        comp.append(np.hypot(cfg.sys_rm68_pct, cfg.sys_rm76_pct) * _f75(t))
        if cfg.sys_decay:
            comp.append(np.full_like(t, cfg.sys_l235_pct))
    else:
        r = np.broadcast_to(np.asarray(r76, float), t.shape).copy()
        T = np.arange(1.0, 4600.0, 1.0)
        def grid(l38, l35):
            return (np.expm1(l35 * T) / np.expm1(l38 * T)) / U8_5
        base = np.interp(r, grid(L238, L235), T)
        dr = np.abs(np.interp(r * (1 + 0.001), grid(L238, L235), T) - np.interp(r * (1 - 0.001), grid(L238, L235), T)) / 2 / 0.001   # dt / d ln r
        with np.errstate(all="ignore"):
            comp.append(cfg.sys_rm76_pct / 100 * dr / base * 100)
            if cfg.sys_decay:
                a = np.interp(r, grid(L238 * (1 + cfg.sys_l238_pct / 100), L235), T) - base
                b = np.interp(r, grid(L238, L235 * (1 + cfg.sys_l235_pct / 100)), T) - base
                comp.append(np.hypot(a, b) / base * 100)
    return np.sqrt(np.sum(np.square(comp), axis=0))


def _date_kind(col):
    if col in ("age207/235",):
        return "75"
    if col in ("age207/206",):
        return "76"
    return "68"


def zr_systematic(tab, cfg):
    """Add <date>_sys_pct (the systematic and external part, 1 sigma, percent) and <date>_se_tot (internal and systematic in quadrature, Ma) for every
    date column of a domain or spot table that has an internal error <date>_se. The ratio and decay constant settings and the blanket external
    reproducibility come from the Quantify tab (UPbConfig). Concordia and Tera-Wasserburg dates take the 206Pb/238U systematics. Returns the table."""
    if not len(tab):
        return tab
    r76 = tab["r207/206Pb"].to_numpy(float) if "r207/206Pb" in tab else np.full(len(tab), np.nan)
    for col in [c for c in tab.columns if c.startswith("age") and c + "_se" in tab and not c.endswith(("_se", "_sys_pct", "_se_tot"))]:
        t = tab[col].to_numpy(float)
        kind = _date_kind(col)
        sp = sys_date_pct(kind, t, r76, cfg) if kind != "76" else sys_date_pct("76", t, np.where(np.isfinite(r76), r76, np.nan), cfg)
        tab[col + "_sys_pct"] = sp
        se = tab[col + "_se"].to_numpy(float)
        tab[col + "_se_tot"] = np.sqrt(se ** 2 + (sp / 100 * t) ** 2)
    return tab


def with_total_errors(tab):
    """A copy of a table in which every <date>_se is the total (internal plus systematic and external) error, where the total exists."""
    t = tab.copy()
    for c in [c for c in t.columns if c.endswith("_se_tot")]:
        t[c[:-4]] = t[c]
    return t


def upb_ext_estimate(sess, key="206Pb/238U"):
    """Excess scatter of the secondary reference materials: the 206Pb/238U ratios of all their lines against the accepted value, with a common offset and
    a common extra variance fitted by maximum likelihood on top of each line's counting error. Returns dict(tau_pct, date_pct, bias_pct, n):
    tau_pct is the extra scatter in percent of the ratio, date_pct the same in terms of a date (the number to use as external reproducibility)."""
    from scipy.optimize import minimize_scalar
    lines, summ, notes, series = upb_qaqc(sess)
    if not len(lines):
        return {}
    g = lines[(lines.role == "secondary") & (lines.status != "rejected")] if "status" in lines else lines[lines.role == "secondary"]
    ok = [k in g for k in (key, key + "_se", key + "_acc")]
    if not all(ok) or not len(g):
        return {}
    r, se, acc = g[key].to_numpy(float), g[key + "_se"].to_numpy(float), g[key + "_acc"].to_numpy(float)
    m = np.isfinite(r) & np.isfinite(se) & np.isfinite(acc) & (r > 0) & (acc > 0)
    if m.sum() < 4:
        return {}
    e, s = np.log(r[m] / acc[m]), se[m] / r[m]

    def nll(tau):
        v = s ** 2 + tau ** 2
        mu = np.sum(e / v) / np.sum(1 / v)
        return 0.5 * float(np.sum(np.log(v) + (e - mu) ** 2 / v))
    res = minimize_scalar(nll, bounds=(0, 0.2), method="bounded", options=dict(xatol=1e-6))
    tau = float(res.x) if nll(float(res.x)) < nll(0.0) - 1e-9 else 0.0
    v = s ** 2 + tau ** 2
    mu = float(np.sum(e / v) / np.sum(1 / v))
    f = float(np.nanmean(_f68(age_ma(acc[m], "238"))))
    return dict(tau_pct=100 * tau, date_pct=100 * tau * f, bias_pct=100 * mu, n=int(m.sum()))


# ---- depth map, trace-layer mask, MDA by domain
def zr_depth(ctx):
    """Depth (um) from the grain edge for every grain pixel (cached on the context)."""
    if getattr(ctx, "_depth", None) is None:
        d = np.zeros((ctx.ny, ctx.nx))
        for gid, sl in _grain_boxes(ctx.lab):
            m = ctx.lab[sl] == gid
            d[sl][m] = _depth_in_grain(ctx, m)[m]
        ctx._depth = d
    return ctx._depth


def _mask_rule(rule):
    import re
    m = re.match(r"^\s*(.*\S)\s+(>|<|auto)\s*([-+0-9.eE]*)\s*$", rule)
    if not m:
        raise ValueError(f"Cannot read the rule '{rule}'. Use: layer > value, layer < value or layer auto k")
    layer, op, val = m.group(1), m.group(2), m.group(3)
    return layer, op, (float(val) if val else (4.0 if op == "auto" else np.nan))


def zr_mask(ctx, rules=(), grow_px=0, per_grain=False):
    """Leave pixels out of every later calculation because a layer says the beam hit something other than clean zircon: inclusions
    (P, Ca, Al, Fe, LREE high), cracks and alteration, or a high common Pb.

    Each rule is 'layer > value' or 'layer < value' (absolute, in the layer's units), or 'layer auto k'. Auto flags where log10 of
    the layer is more than k robust standard deviations (1.4826 MAD) above its median among the usable pixels of the same mineral
    (of the same grain with per_grain).

    grow_px widens the flagged pixels, because an inclusion spoils the pixels around it. An empty list restores the unmasked
    region. The domain, estimator and population tables made afterwards use the masked region.

    Returns a table of rules with the flagged pixels."""
    base = ctx.region0
    flag = np.zeros_like(base)
    rows = []
    for rule in rules:
        layer, op, val = _mask_rule(rule)
        arr = np.asarray(ctx.sess.get_layer(layer), float)
        f = np.zeros_like(base)
        if op == ">":
            f = np.isfinite(arr) & (arr > val)
        elif op == "<":
            f = np.isfinite(arr) & (arr < val)
        else:
            with np.errstate(all="ignore"):
                lg = np.where(arr > 0, np.log10(np.where(arr > 0, arr, 1)), np.nan)
            groups = [(ctx.lab == g) for g in np.unique(ctx.lab[ctx.lab > 0])] if per_grain else \
                     [np.isin(ctx.lab, [g for g, mn in ctx.grain_mineral.items() if mn == mn_]) for mn_ in sorted(set(ctx.grain_mineral.values()))]
            for gm in groups:
                u = lg[gm & base & np.isfinite(lg)]
                if u.size < 20:
                    continue
                med = np.median(u)
                sd = 1.4826 * np.median(np.abs(u - med))
                if sd > 0:
                    f |= gm & np.isfinite(lg) & (lg > med + val * sd)
        f &= base
        rows.append(dict(rule=rule, flagged_px=int(f.sum()), pct_of_usable=float(100 * f.sum() / max(base.sum(), 1))))
        flag |= f
    if grow_px and flag.any():
        flag = ndi.binary_dilation(flag, structure=np.ones((3, 3), bool), iterations=int(grow_px)) & base
    ctx.excl = flag
    ctx.region = base & ~flag
    if ctx.filter:
        zr_filter(ctx, **ctx.filter)
    else:
        ctx.pixok = ctx.region.copy()
    rows.append(dict(rule="all rules" + (f", grown by {grow_px} px" if grow_px else ""), flagged_px=int(flag.sum()), pct_of_usable=float(100 * flag.sum() / max(base.sum(), 1))))
    return pd.DataFrame(rows)


def mda_compare(tab, date="age206/238", rules=("grain", "all", "inner", "outer", "no_outer", "youngest", "oldest"), methods=MDA_METHODS, sys_pct=0.0,
                peak_n=2, min_px=20, max_disc=None, disc="disc_da_pct", query=None, **kw):
    """The maximum depositional age by every method for several choices of which dates enter: whole grains, every domain, the inner domain of each grain,
    the outer one, everything except the outer domains, the youngest or the oldest domain. A method that gives a younger answer with the outer domains
    in than without is being pulled down by rims. Returns (table with methods in rows and rules in columns, number of dates per rule)."""
    cols, ns = {}, {}
    for rule in rules:
        sel = pop_select(tab, rule, date, max_disc=max_disc, min_px=min_px, disc=disc, query=query)
        ns[rule] = len(sel)
        if len(sel) >= 4 and date + "_se" in sel:
            r = mda_methods(sel[date].to_numpy(float), sel[date + "_se"].to_numpy(float), sys_pct=sys_pct, peak_n=peak_n, methods=methods, **kw)
            cols[rule] = r.set_index("method").mda
        else:
            cols[rule] = pd.Series(np.nan, index=list(methods))
    return pd.DataFrame(cols).loc[list(methods)], pd.Series(ns, name="dates")


# ---- discordia per grain or domain: Pb loss against common Pb
def york_fit(x, y, sx, sy, rho, maxit=100):
    """York (1969, 2004) straight-line fit with correlated errors. Returns slope b, intercept a and their standard errors, the covariance
    between them, MSWD and the weighted mean x of the adjusted points."""
    x, y, sx, sy, rho = (np.asarray(v, float) for v in (x, y, sx, sy, rho))
    wx, wy = 1 / sx ** 2, 1 / sy ** 2
    al = np.sqrt(wx * wy)
    b = np.polyfit(x, y, 1)[0]
    for _ in range(maxit):
        Z = wx * wy / (wx + b * b * wy - 2 * b * rho * al)
        xb, yb = np.sum(Z * x) / Z.sum(), np.sum(Z * y) / Z.sum()
        U, V = x - xb, y - yb
        beta = Z * (U / wy + b * V / wx - (b * U + V) * rho / al)
        bn = np.sum(Z * beta * V) / np.sum(Z * beta * U)
        if abs(bn - b) < 1e-12 * max(abs(b), 1e-12):
            b = bn
            break
        b = bn
    Z = wx * wy / (wx + b * b * wy - 2 * b * rho * al)
    xb, yb = np.sum(Z * x) / Z.sum(), np.sum(Z * y) / Z.sum()
    U, V = x - xb, y - yb
    beta = Z * (U / wy + b * V / wx - (b * U + V) * rho / al)
    xa = xb + beta
    xab = np.sum(Z * xa) / Z.sum()
    sb2 = 1.0 / np.sum(Z * (xa - xab) ** 2)
    a = yb - b * xb
    sa2 = 1.0 / Z.sum() + xab ** 2 * sb2
    S = float(np.sum(Z * (y - b * x - a) ** 2))
    n = len(x)
    return dict(b=float(b), a=float(a), b_se=float(np.sqrt(sb2)), a_se=float(np.sqrt(sa2)), cov_ab=float(-xab * sb2), mswd=S / (n - 2) if n > 2 else np.nan, xbar=float(xab))


def _tw_concordia(t):
    t = np.asarray(t, float)
    x = 1.0 / np.expm1(L238 * t)
    return x, (np.expm1(L235 * t) / np.expm1(L238 * t)) / U8_5


def _line_concordia_roots(a, b, tmin=1.0, tmax=4500.0, n=4500):
    """Ages (Ma) at which the line y = a + b x crosses the Tera-Wasserburg concordia."""
    T = np.linspace(tmin, tmax, n)
    xc, yc = _tw_concordia(T)
    f = yc - a - b * xc
    idx = np.flatnonzero(np.sign(f[:-1]) * np.sign(f[1:]) < 0)
    out = []
    for i in idx:
        out.append(T[i] - f[i] * (T[i + 1] - T[i]) / (f[i + 1] - f[i]))
    return out


def discordia_points(ctx, mask, tile_px=3, min_ions=(5, 2)):
    """Tera-Wasserburg points of the tiles of a pixel set: x = 238U/206Pb, y = 207Pb/206Pb, with Poisson errors and their correlation (both share 206Pb).
    Tiles with fewer than min_ions = (206Pb, 207Pb) ions are left out. Needs the counts per ion."""
    if not ctx.q:
        raise ValueError("Counts per ion are unknown, so the tile errors cannot be given")
    rows, cols = np.flatnonzero(mask.any(1)), np.flatnonzero(mask.any(0))
    if not len(rows):
        return None
    sl = (slice(rows[0], rows[-1] + 1), slice(cols[0], cols[-1] + 1))
    m = mask[sl] & ctx.region[sl]
    if not m.any():
        return None
    tid, nt, _ = _tile_graph(m, max(int(tile_px), 1))
    lab = np.where(tid >= 0, tid + 1, 0)
    a68, b68 = ctx.rat["206Pb/238U"]
    a76, b76 = ctx.rat["207Pb/206Pb"]
    iy = np.arange(ctx.ny)[sl[0]][:, None]
    q = ctx.q
    def sums(arr, fac=None):
        v = np.nan_to_num(arr[sl]) * (fac[iy] if fac is not None else 1.0)
        return np.bincount(lab.ravel(), v.ravel(), minlength=nt + 1)[1:]
    S6, S8 = sums(a68, ctx.fac["206Pb/238U"]), sums(b68)
    S7, S6b = sums(a76, ctx.fac["207Pb/206Pb"]), sums(b76)
    N6, N7, N8 = sums(a68) / q, sums(a76) / q, sums(b68) / q
    with np.errstate(all="ignore"):
        r68, r76 = S6 / S8, S7 / S6b
        ok = (N6 >= min_ions[0]) & (N7 >= min_ions[1]) & (N8 > 0) & (r68 > 0) & (r76 > 0)
        x, y = 1 / r68, r76
        lx, ly = np.sqrt(1 / N6 + 1 / N8), np.sqrt(1 / N7 + 1 / N6)
        sx, sy = x * lx, y * ly
        rho = (1 / N6) / (lx * ly)
    ok &= np.isfinite(x) & np.isfinite(y) & np.isfinite(sx) & np.isfinite(sy)
    return dict(x=x[ok], y=y[ok], sx=sx[ok], sy=sy[ok], rho=np.clip(rho[ok], -0.99, 0.99), n_tiles=int(ok.sum()))


def discordia_fit(pts, nmc=400, seed=0, min_tiles=8):
    """York line through the Tera-Wasserburg tile points and where it meets the concordia. Errors on the intercepts come from sampling the line parameters
    (their covariance scaled by the MSWD when it is above 1). pb_type: 'common Pb' when the line meets the y axis at the Stacey-Kramers 207Pb/206Pb of
    the older intercept within 3 sigma, 'Pb loss' when it does not and a younger intercept exists, 'no trend' when the points are too tight to define a line."""
    out = dict(n_tiles=0 if pts is None else pts["n_tiles"])
    if pts is None or pts["n_tiles"] < min_tiles:
        out["pb_type"] = "too few tiles"
        return out
    x, y = pts["x"], pts["y"]
    spread = (x.max() - x.min()) / np.median(pts["sx"])
    f = york_fit(x, y, pts["sx"], pts["sy"], pts["rho"])
    out.update(slope=f["b"], slope_se=f["b_se"], y_int=f["a"], y_int_se=f["a_se"], mswd=f["mswd"], spread_sigma=float(spread))
    roots = _line_concordia_roots(f["a"], f["b"])
    out["age_upper"] = max(roots) if roots else np.nan
    out["age_lower"] = min(roots) if len(roots) > 1 else np.nan
    cov = np.array([[f["a_se"] ** 2, f["cov_ab"]], [f["cov_ab"], f["b_se"] ** 2]]) * max(1.0, f["mswd"] if np.isfinite(f["mswd"]) else 1.0)
    rng = np.random.default_rng(seed)
    try:
        draws = rng.multivariate_normal([f["a"], f["b"]], cov, nmc)
    except Exception:
        draws = None
    ups, los = [], []
    if draws is not None:
        for a_, b_ in draws:
            r = _line_concordia_roots(a_, b_)
            if r:
                ups.append(max(r))
                if len(r) > 1:
                    los.append(min(r))
    out["age_upper_se"] = float(np.std(ups)) if len(ups) > 10 else np.nan
    out["age_lower_se"] = float(np.std(los)) if len(los) > 10 else np.nan
    if spread < 5:
        out["pb_type"] = "no trend"
    elif np.isfinite(out["age_upper"]) and out["age_upper"] < 3700:
        sk = float(stacey_kramers_76(out["age_upper"]))
        out["common_pb_76"] = sk
        out["y_int_vs_common_sigma"] = (f["a"] - sk) / f["a_se"] if f["a_se"] > 0 else np.nan
        if abs(out["y_int_vs_common_sigma"]) <= 3:
            out["pb_type"] = "common Pb"
        else:
            if np.isfinite(out["age_lower"]):
                out["pb_type"] = "Pb loss"
            elif abs(f["b"]) < 3 * f["b_se"]:
                out["pb_type"] = "Pb loss (recent)"                 # a flat line meets the concordia only at the old end: the lower intercept is near zero
            else:
                out["pb_type"] = "mixing, unclear"
    else:
        out["pb_type"] = "no intercept"
    return out


def discordia_table(ctx, units="grain", tile_px=3, min_tiles=8, min_ions=(5, 2), nmc=300):
    """Discordia of every grain (units='grain') or of every domain (units='domain') in the current domain image."""
    rows = []
    if units == "domain":
        sets = [(int(r.dom), int(r.grain), r.kind, ctx.dom == r.dom) for r in ctx.dom_info.itertuples()]
    else:
        sets = [(0, int(g), "grain", ctx.lab == g) for g in np.unique(ctx.lab[ctx.lab > 0])]
    for dom, g, kind, m in sets:
        try:
            pts = discordia_points(ctx, m, tile_px, min_ions)
            res = discordia_fit(pts, nmc=nmc, min_tiles=min_tiles)
        except ValueError as e:
            res = dict(pb_type=str(e))
        rows.append(dict(dom=dom, grain=g, kind=kind, **res))
    return pd.DataFrame(rows)


# ---- trace-element classification of grains and domains
CHONDRITE_CI = {"La": 0.237, "Ce": 0.613, "Pr": 0.0928, "Nd": 0.457, "Sm": 0.148, "Eu": 0.0563, "Gd": 0.199, "Tb": 0.0361, "Dy": 0.246,
                "Ho": 0.0546, "Er": 0.160, "Tm": 0.0247, "Yb": 0.161, "Lu": 0.0246}            # McDonough and Sun (1995), ppm
CLASS_ELEMENTS = ("Th", "U", "Ti", "La", "Ce", "Pr", "Nd", "Sm", "Eu", "Gd", "Dy", "Yb", "Y", "Hf", "P")


def class_layers(sess):
    """The ppm layers the classification can use: one per element of CLASS_ELEMENTS, the first quantified channel of each element."""
    out = []
    labels = [l for l in sess.labels if sess.is_quantified(l)] if hasattr(sess, "labels") else []
    for el in CLASS_ELEMENTS:
        c = [l for l in labels if element_of(l) == el]
        if c:
            out.append("ppm:" + c[0])
    return out


def _ppm(tab, el):
    cols = [c for c in tab.columns if c.startswith("ppm:") and element_of(c[4:]) == el]
    return tab[cols[0]].to_numpy(float) if cols else np.full(len(tab), np.nan)


def zr_classify(tab, th_meta=0.07, th_mag=0.2, a_sio2=1.0, a_tio2=0.6, lree_i_min=30.0):
    """Trace-element screen of the rows of a domain table that carries ppm columns (make it with the layers from class_layers). Adds Th/U with a class
    (below th_meta metamorphic-like, above th_mag magmatic-like, between ambiguous: Rubatto 2002, Hoskin and Schaltegger 2003), Ti-in-zircon temperature
    (Ferry and Watson 2007, with the SiO2 and TiO2 activities given), Ce/Ce* = Ce_N / sqrt(La_N Pr_N), Eu/Eu* = Eu_N / sqrt(Sm_N Gd_N) (chondrite
    of McDonough and Sun 1995), Yb/Gd and U/Yb, and the LREE index Dy/Nd + Dy/Sm (Bell et al. 2016) with altered = index below lree_i_min.
    The thresholds are indicative and can be changed. Returns a copy of the table."""
    t = tab.copy()
    N = lambda el: _ppm(t, el) / CHONDRITE_CI[el] if el in CHONDRITE_CI else _ppm(t, el)
    with np.errstate(all="ignore"):
        th, u, ti = _ppm(t, "Th"), _ppm(t, "U"), _ppm(t, "Ti")
        t["ThU"] = th / u
        t["class_ThU"] = np.where(~np.isfinite(t.ThU), "", np.where(t.ThU < th_meta, "metamorphic-like", np.where(t.ThU > th_mag, "magmatic-like", "ambiguous")))
        t["Ti_ppm"] = ti
        t["Ti_T_C"] = 4800.0 / (5.711 - np.log10(ti) - np.log10(a_sio2) + np.log10(a_tio2)) - 273.15
        t["Ce_anom"] = N("Ce") / np.sqrt(N("La") * N("Pr"))
        t["Eu_anom"] = N("Eu") / np.sqrt(N("Sm") * N("Gd"))
        t["Yb_Gd"] = _ppm(t, "Yb") / _ppm(t, "Gd")
        t["U_Yb"] = u / _ppm(t, "Yb")
        dy = _ppm(t, "Dy")
        t["LREE_I"] = dy / _ppm(t, "Nd") + dy / _ppm(t, "Sm")
        t["altered"] = np.isfinite(t.LREE_I) & (t.LREE_I < lree_i_min)
        t["Hf_ppm"], t["Y_ppm"] = _ppm(t, "Hf"), _ppm(t, "Y")
    return t


