# ----------------------------------------------------------------------------- utilities
def safe(fn):
    """Show errors in a dialog instead of killing the app. Drops signal args the method does not take."""
    n = len(inspect.signature(fn).parameters) - 1

    @functools.wraps(fn)
    def wrapper(self, *a):
        try:
            return fn(self, *a[:n])
        except (vc.ExprError, vc.CalibError, ValueError, KeyError) as e:
            W.QMessageBox.warning(self, "Vitesse processor", str(e).strip("'\""))
        except Exception as e:  # noqa
            traceback.print_exc()
            W.QMessageBox.critical(self, "Vitesse processor", f"{type(e).__name__}: {e}")
    return wrapper


CMAP_CHOICES = ["viridis", "inferno", "magma", "plasma", "cividis", "gray", "CET-L1", "CET-R1", "CET-D1"]
_LUTS = {}


def make_cmap(name):
    if name == "gray":
        return pg.ColorMap([0, 1], [(0, 0, 0, 255), (255, 255, 255, 255)])
    return pg.colormap.get(name)


def get_lut(name, reverse=False):
    key = (name, reverse)
    if key not in _LUTS:
        lut = make_cmap(name).getLookupTable(0.0, 1.0, 256, alpha=True)
        _LUTS[key] = np.ascontiguousarray(lut[::-1] if reverse else lut, dtype=np.uint8)
    return _LUTS[key]


def display_values(arr, scale):
    a = np.asarray(arr, np.float32)
    with np.errstate(all="ignore"):
        if scale == "log10":
            return np.where(a > 0, np.log10(a), np.nan).astype(np.float32)
        if scale == "sqrt":
            return np.where(a >= 0, np.sqrt(a), np.nan).astype(np.float32)
    return a


def auto_levels(a, p_lo, p_hi):
    f = a[np.isfinite(a)]
    if f.size == 0:
        return 0.0, 1.0
    if f.size > 400000:
        f = f[:: max(f.size // 400000, 1)]
    lo, hi = np.percentile(f, [p_lo, p_hi])
    if hi <= lo:
        hi = lo + max(abs(lo) * 1e-6, 1e-6)
    return float(lo), float(hi)


def to_rgba(a, lut, lo, hi):
    with np.errstate(all="ignore"):
        t = (a - lo) / (hi - lo)
    bad = ~np.isfinite(t)
    idx = (np.clip(np.nan_to_num(t), 0, 1) * 255).astype(np.uint8)
    rgba = lut[idx]
    rgba[bad] = 0
    return rgba


def fmt_num(v):
    if v is None or not np.isfinite(v):
        return ""
    return f"{v:.4g}"


def qcolor(c, a=255):
    return QtGui.QColor(int(c[0]), int(c[1]), int(c[2]), a)


def parse_float(txt, default=None):
    try:
        return float(str(txt).strip())
    except ValueError:
        return default


# ----------------------------------------------------------------------------- small widgets
def draw_box(p, x, b, col, width=0.5, outliers=True, mean=True):
    """A conventional Tukey box-and-whisker at position x: box Q1-Q3, median line, whiskers with caps to the most extreme
    values within 1.5 IQR, outliers as open circles, mean as a diamond."""
    h = width / 2.0
    c = tuple(int(v) for v in col[:3])
    box = QtGui.QPainterPath()
    box.addRect(QtCore.QRectF(x - h, b["q1"], width, max(b["q3"] - b["q1"], 1e-12 * (abs(b["q3"]) + 1.0))))
    it = QtWidgets.QGraphicsPathItem(box)
    it.setPen(pg.mkPen(*c, 255, width=2))
    it.setBrush(pg.mkBrush(*c, 70))
    it.setZValue(5)
    p.addItem(it)
    cap = h * 0.5
    xs = [x, x, x, x, x - cap, x + cap, x - cap, x + cap, x - h, x + h]
    ys = [b["q3"], b["hi"], b["q1"], b["lo"], b["hi"], b["hi"], b["lo"], b["lo"], b["median"], b["median"]]
    wh = pg.PlotCurveItem(x=np.array(xs, float), y=np.array(ys, float), connect="pairs", pen=pg.mkPen(*c, 255, width=2))
    wh.setZValue(6)
    p.addItem(wh)
    md = pg.PlotCurveItem(x=np.array([x - h, x + h]), y=np.array([b["median"]] * 2), pen=pg.mkPen(255, 255, 255, 255, width=3))
    md.setZValue(7)
    p.addItem(md)
    if outliers and len(b["outliers"]):
        o = np.asarray(b["outliers"], float)
        if o.size > 500:
            o = o[np.linspace(0, o.size - 1, 500).astype(int)]
        sc = pg.ScatterPlotItem(x=np.full(o.size, float(x)), y=o, size=7, symbol="o", pen=pg.mkPen(*c, 255, width=1.5), brush=pg.mkBrush(0, 0, 0, 0))
        sc.setZValue(8)
        p.addItem(sc)
    if mean:
        mm = pg.ScatterPlotItem(x=[float(x)], y=[b["mean"]], size=8, symbol="d", pen=pg.mkPen(0, 0, 0, 255), brush=pg.mkBrush(255, 255, 255, 255))
        mm.setZValue(9)
        p.addItem(mm)



class LayerBox(W.QComboBox):
    """Editable combo listing channels, derived layers and ppm layers. Free expressions are allowed."""
    changed = QtCore.pyqtSignal()

    def __init__(self):
        super().__init__()
        self.setEditable(True)
        self.setInsertPolicy(W.QComboBox.InsertPolicy.NoInsert)
        self.setMinimumWidth(120)
        c = self.completer()
        c.setCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)
        c.setFilterMode(Qt.MatchFlag.MatchContains)
        self.activated.connect(lambda _=0: self.changed.emit())
        self.lineEdit().editingFinished.connect(self.changed.emit)

    none_label = None            # set to a text such as "(none)" to make the box optional

    def refill(self, names):
        cur = self.currentText()
        self.blockSignals(True)
        self.clear()
        if self.none_label:
            self.addItem(self.none_label)
        self.addItems(names)
        self.setCurrentText(cur if cur else (self.none_label or (names[0] if names else "")))
        self.blockSignals(False)

    def spec(self):
        t = self.currentText().strip()
        return "" if (self.none_label and t == self.none_label) else t


class ExprCompleter(W.QCompleter):
    """Suggests names for the word being typed in an expression line (Fe -> Fe56, Fe57, Fe56_ppm ...), wherever the cursor is.
    Choosing a suggestion replaces only that word. Function names get an opening bracket."""
    _WORD = re.compile(r"[A-Za-z_][A-Za-z0-9_]*$")

    def __init__(self, edit, funcs=()):
        super().__init__(edit)
        self.edit = edit
        self.funcs = set(funcs)
        self._model = QtCore.QStringListModel(self)
        self.setModel(self._model)
        self.setCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)
        self.setCompletionMode(W.QCompleter.CompletionMode.PopupCompletion)
        self.setMaxVisibleItems(14)
        self.setFilterMode(Qt.MatchFlag.MatchStartsWith)
        edit.setCompleter(self)

    def set_names(self, names):
        seen, out = set(), []
        for n in list(names) + sorted(self.funcs):
            if n not in seen:
                seen.add(n)
                out.append(n)
        self._model.setStringList(out)

    def _word_before_cursor(self, text=None):
        full = self.edit.text()
        t = full if text is None else text
        if t == full:
            t = t[:self.edit.cursorPosition()]
        m = self._WORD.search(t)
        return (m.group(0) if m else ""), (m.start() if m else len(t))

    def splitPath(self, path):
        w, _ = self._word_before_cursor(path)
        return [w if w else "\x00"]               # nothing typed since the last operator: no popup

    def pathFromIndex(self, index):
        name = str(index.data())
        _w, start = self._word_before_cursor()
        t = self.edit.text()
        pos = self.edit.cursorPosition()
        add = "(" if name in self.funcs else ""
        self._new_cursor = start + len(name) + len(add)
        return t[:start] + name + add + t[pos:]

    def eventFilter(self, obj, ev):
        r = super().eventFilter(obj, ev)
        return r


class StackRow(W.QFrame):
    """One layer of the Display stack: on/off, the layer, its colour map, scale and opacity, and buttons to move or remove it."""
    changed = QtCore.pyqtSignal()
    move = QtCore.pyqtSignal(object, int)
    removed = QtCore.pyqtSignal(object)

    def __init__(self, main, spec="", cmap="viridis", scale="log10", opacity=100):
        super().__init__()
        self.setFrameShape(W.QFrame.Shape.StyledPanel)
        v = W.QVBoxLayout(self)
        v.setContentsMargins(6, 4, 6, 4)
        v.setSpacing(3)
        r = W.QHBoxLayout()
        self.on = W.QCheckBox()
        self.on.setChecked(True)
        self.on.setToolTip("Show or hide this layer")
        self.layer = main.new_layer_box()
        self.layer.setCurrentText(spec)
        r.addWidget(self.on)
        r.addWidget(self.layer, 1)
        self.b_up, self.b_dn, self.b_rm = W.QToolButton(), W.QToolButton(), W.QToolButton()
        for b, t, tip in ((self.b_up, "▲", "Move up (drawn later, so nearer the top)"), (self.b_dn, "▼", "Move down"),
                          (self.b_rm, "✕", "Remove this layer")):
            b.setText(t)
            b.setToolTip(tip)
            r.addWidget(b)
        v.addLayout(r)
        r = W.QHBoxLayout()
        self.cmap = W.QComboBox()
        self.cmap.addItems(main.cmaps)
        if cmap in main.cmaps:
            self.cmap.setCurrentText(cmap)
        self.scale = W.QComboBox()
        self.scale.addItems(["linear", "log10", "sqrt"])
        self.scale.setCurrentText(scale)
        self.opacity = W.QSpinBox()
        self.opacity.setRange(0, 100)
        self.opacity.setValue(int(opacity))
        self.opacity.setSuffix(" %")
        self.opacity.setToolTip("Opacity of this layer over the ones below it")
        r.addWidget(self.cmap, 1)
        r.addWidget(self.scale)
        r.addWidget(self.opacity)
        v.addLayout(r)
        self.layer.changed.connect(self._layer_changed)
        self.on.toggled.connect(lambda _c: self.changed.emit())
        self.cmap.currentIndexChanged.connect(lambda _i: self.changed.emit())
        self.scale.currentIndexChanged.connect(lambda _i: self.changed.emit())
        self.opacity.valueChanged.connect(lambda _v: self.changed.emit())
        self.b_up.clicked.connect(lambda: self.move.emit(self, -1))
        self.b_dn.clicked.connect(lambda: self.move.emit(self, 1))
        self.b_rm.clicked.connect(lambda: self.removed.emit(self))
        self._mineral_state()

    def _mineral_state(self):
        mineral = self.layer.spec().startswith("mineral:")
        self.cmap.setEnabled(not mineral)
        self.scale.setEnabled(not mineral)
        self.cmap.setToolTip("A saved mineral is drawn in its own colour" if mineral else "")

    def _layer_changed(self):
        self._mineral_state()
        self.changed.emit()

    def item(self):
        return dict(on=self.on.isChecked(), spec=self.layer.spec(), cmap=self.cmap.currentText(),
                    scale=self.scale.currentText(), opacity=self.opacity.value() / 100.0)


class LayerStack(W.QWidget):
    """Several layers drawn over one another. The first row is the top of the stack."""
    changed = QtCore.pyqtSignal()
    DEFAULT_CMAPS = ("magma", "viridis", "gray", "plasma", "cividis")

    def __init__(self, main):
        super().__init__()
        self.main = main
        self.rows = []
        v = W.QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        note = W.QLabel("First row is the top of the stack. Use the arrows to change the order. Lower the opacity of an upper layer "
                        "to see the ones below through it. Saved minerals can be stacked too, in their own colour.")
        note.setWordWrap(True)
        v.addWidget(note)
        self.box = W.QVBoxLayout()
        self.box.setSpacing(4)
        v.addLayout(self.box)
        r = W.QHBoxLayout()
        self.b_add = W.QPushButton("Add layer")
        self.b_add.clicked.connect(lambda: self.add_row())
        r.addWidget(self.b_add)
        r.addStretch(1)
        v.addLayout(r)

    def add_row(self, spec=None, cmap=None, scale="log10", opacity=100, top=False):
        if spec is None:
            names = self.main.s.layer_names() if self.main.s.map else []
            spec = names[min(len(self.rows), len(names) - 1)] if names else ""
        row = StackRow(self.main, spec, cmap or self.DEFAULT_CMAPS[len(self.rows) % len(self.DEFAULT_CMAPS)], scale, opacity)
        row.changed.connect(self.changed.emit)
        row.move.connect(self.move_row)
        row.removed.connect(self.remove_row)
        self.rows.insert(0 if top else len(self.rows), row)
        self._relayout()
        self.changed.emit()
        return row

    def _relayout(self):
        for r in self.rows:
            self.box.removeWidget(r)
        for r in self.rows:
            self.box.addWidget(r)
        for i, r in enumerate(self.rows):
            r.b_up.setEnabled(i > 0)
            r.b_dn.setEnabled(i < len(self.rows) - 1)

    def move_row(self, row, d):
        i = self.rows.index(row)
        j = i + d
        if 0 <= j < len(self.rows):
            self.rows[i], self.rows[j] = self.rows[j], self.rows[i]
            self._relayout()
            self.changed.emit()

    def remove_row(self, row):
        if row in self.rows:
            self.rows.remove(row)
            self.box.removeWidget(row)
            row.setParent(None)
            row.deleteLater()
            self._relayout()
            self.changed.emit()

    def items(self):
        """Top first."""
        return [r.item() for r in self.rows]

    def clear(self):
        for r in list(self.rows):
            self.rows.remove(r)
            self.box.removeWidget(r)
            r.setParent(None)
            r.deleteLater()

    def prune(self, names):
        """After a rebuild: drop rows whose layer no longer exists."""
        gone = [r for r in self.rows if r.layer.spec() not in names]
        for r in gone:
            self.rows.remove(r)
            self.box.removeWidget(r)
            r.setParent(None)
            r.deleteLater()
        if gone:
            self._relayout()
            self.changed.emit()


class MaskRule(W.QWidget):
    """One condition on a layer: greater than, less than, equal, not equal, inside or outside a range."""
    changed = QtCore.pyqtSignal()

    def __init__(self, main, optional=False):
        super().__init__()
        v = W.QHBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        self.use = W.QCheckBox("and" if optional else "")
        self.use.setChecked(not optional)
        self.use.setVisible(optional)
        self.layer = main.new_layer_box()
        self.op = W.QComboBox()
        self.op.addItems(list(vc.CONDITION_OPS))
        self.a, self.b = W.QLineEdit(), W.QLineEdit()
        for e, ph in ((self.a, "value"), (self.b, "to")):
            e.setPlaceholderText(ph)
            e.setMaximumWidth(78)
        for wd in (self.use, self.layer, self.op, self.a, self.b):
            v.addWidget(wd, 1 if wd is self.layer else 0)
        self.layer.changed.connect(self.changed.emit)
        self.op.currentIndexChanged.connect(self._op_changed)
        self.a.editingFinished.connect(self.changed.emit)
        self.b.editingFinished.connect(self.changed.emit)
        self.use.toggled.connect(lambda _c: self.changed.emit())
        self._op_changed()

    def _op_changed(self, *_):
        two = self.op.currentText() in ("in range", "outside range")
        self.b.setEnabled(two)
        self.a.setPlaceholderText("from" if two else "value")
        self.changed.emit()

    def condition(self):
        """(layer, op, a, b) when the rule is switched on and complete, else None."""
        if not self.use.isChecked():
            return None
        spec, op = self.layer.spec(), self.op.currentText()
        a, b = parse_float(self.a.text()), parse_float(self.b.text())
        if not spec or a is None:
            return None
        if op in ("in range", "outside range") and b is None:
            return None
        return spec, op, a, b


