def fit_list_height(lw, lo=2, hi=20):
    """Make a QListWidget exactly tall enough for its rows (at least lo, at most hi rows)."""
    n = lw.count()
    rh = lw.sizeHintForRow(0) if n else 0
    rh = rh if rh > 0 else lw.fontMetrics().height() + 6
    h = rh * max(lo, min(n, hi)) + 2 * lw.frameWidth() + 4
    lw.setMinimumHeight(h)
    lw.setMaximumHeight(h)


def fit_table_height(tb, lo=1, hi=10):
    """Make a QTableWidget exactly tall enough for its rows (at least lo, at most hi rows, then it scrolls)."""
    n = tb.rowCount()
    rows = max(lo, min(n, hi))
    h = tb.horizontalHeader().height() if tb.horizontalHeader().isVisible() else 0
    h = max(h, tb.horizontalHeader().sizeHint().height())
    for r in range(min(n, hi)):
        h += max(tb.rowHeight(r), 22)
    h += max(rows - n, 0) * 24
    h += 2 * tb.frameWidth() + 4
    tb.setSizePolicy(W.QSizePolicy.Policy.Preferred, W.QSizePolicy.Policy.Fixed)
    tb.setMinimumHeight(h)
    tb.setMaximumHeight(h)
    tb.updateGeometry()


class CheckList(W.QWidget):
    changed = QtCore.pyqtSignal()

    def __init__(self, element_box=False):
        super().__init__()
        v = W.QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        top = W.QHBoxLayout()
        self.filter = W.QLineEdit()
        self.filter.setPlaceholderText("filter")
        self.filter.setClearButtonEnabled(True)
        b_all, b_none = W.QPushButton("All"), W.QPushButton("None")
        for b in (b_all, b_none):
            b.setMaximumWidth(48)
        top.addWidget(self.filter, 1)
        top.addWidget(b_all)
        top.addWidget(b_none)
        v.addLayout(top)
        self.list = W.QListWidget()
        self.list.setUniformItemSizes(True)
        v.addWidget(self.list, 1)
        self.elem_edit = None
        if element_box:
            r = W.QHBoxLayout()
            self.elem_edit = W.QLineEdit()
            self.elem_edit.setPlaceholderText("elements, e.g. Si,Ca,Zr,U,Pb")
            b_keep, b_add = W.QPushButton("Only"), W.QPushButton("Add")
            r.addWidget(self.elem_edit, 1)
            r.addWidget(b_keep)
            r.addWidget(b_add)
            v.addLayout(r)
            b_keep.clicked.connect(lambda: self.check_elements(True))
            b_add.clicked.connect(lambda: self.check_elements(False))
            self.elem_edit.returnPressed.connect(lambda: self.check_elements(True))
        self.filter.textChanged.connect(self._apply_filter)
        b_all.clicked.connect(lambda: self.set_all(CHECKED))
        b_none.clicked.connect(lambda: self.set_all(UNCHECKED))
        self.list.itemChanged.connect(lambda _i: self.changed.emit())

    def set_items(self, specs, checked=None):
        prev = set(self.checked())
        want = prev if checked is None else set(checked)
        self.list.blockSignals(True)
        self.list.clear()
        for s in specs:
            it = W.QListWidgetItem(s)
            it.setFlags(it.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            it.setCheckState(CHECKED if s in want else UNCHECKED)
            self.list.addItem(it)
        self.list.blockSignals(False)
        self._apply_filter()

    def fit_height(self, lo=1, hi=12):
        """Make the whole box (filter row and list) just tall enough for its rows, so no empty space is left under it."""
        fit_list_height(self.list, lo, hi)
        self.layout().invalidate()
        self.layout().activate()
        h = self.layout().sizeHint().height()
        self.setSizePolicy(W.QSizePolicy.Policy.Preferred, W.QSizePolicy.Policy.Fixed)
        self.setMinimumHeight(h)
        self.setMaximumHeight(h)
        self.updateGeometry()

    def items(self):
        return [self.list.item(i).text() for i in range(self.list.count())]

    def checked(self):
        return [self.list.item(i).text() for i in range(self.list.count())
                if self.list.item(i).checkState() == CHECKED]

    def _apply_filter(self):
        t = self.filter.text().lower()
        for i in range(self.list.count()):
            self.list.item(i).setHidden(bool(t) and t not in self.list.item(i).text().lower())

    def set_all(self, state):
        self.list.blockSignals(True)
        for i in range(self.list.count()):
            if not self.list.item(i).isHidden():
                self.list.item(i).setCheckState(state)
        self.list.blockSignals(False)
        self.changed.emit()

    def check_only(self, specs):
        specs = set(specs)
        self.list.blockSignals(True)
        for i in range(self.list.count()):
            it = self.list.item(i)
            it.setCheckState(CHECKED if it.text() in specs else UNCHECKED)
        self.list.blockSignals(False)
        self.changed.emit()

    def check_elements(self, replace):
        els = {e.strip().capitalize() for e in self.elem_edit.text().replace(";", ",").split(",") if e.strip()}
        self.list.blockSignals(True)
        for i in range(self.list.count()):
            it = self.list.item(i)
            hit = vc.element_of(it.text().replace("ppm:", "")) in els
            if hit:
                it.setCheckState(CHECKED)
            elif replace:
                it.setCheckState(UNCHECKED)
        self.list.blockSignals(False)
        self.changed.emit()


# ----------------------------------------------------------------------------- map view
class MapViewBox(pg.ViewBox):
    """ViewBox with drawing tools. Shapes are reported as polygons in view coordinates."""
    shapeFinished = QtCore.pyqtSignal(str, object)
    wandClicked = QtCore.pyqtSignal(float, float)
    outlineFinished = QtCore.pyqtSignal(object)
    outlineRemove = QtCore.pyqtSignal(float, float)
    outlineUndo = QtCore.pyqtSignal()

    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self.mode = "pan"
        self._pts = []
        self._drag0 = None
        self.preview = pg.PlotCurveItem(pen=pg.mkPen((255, 209, 102), width=2))
        self.addItem(self.preview, ignoreBounds=True)
        self.rubber = pg.PlotCurveItem(pen=pg.mkPen((255, 209, 102, 170), width=1, style=Qt.PenStyle.DashLine))
        self.addItem(self.rubber, ignoreBounds=True)
        self.markers = pg.ScatterPlotItem(size=8, pen=pg.mkPen("w"), brush=pg.mkBrush(255, 209, 0))
        self.addItem(self.markers, ignoreBounds=True)
        for it in (self.preview, self.rubber, self.markers):
            it.setZValue(20)          # above the map images, otherwise the shape being drawn is hidden behind them

    def set_mode(self, mode):
        self.mode = mode
        self.cancel()

    def cancel(self):
        self._pts, self._drag0 = [], None
        self.preview.setData([], [])
        self.rubber.setData([], [])
        self.markers.setData([], [])

    def _draw(self, closed=False):
        if not self._pts:
            self.preview.setData([], [])
            self.rubber.setData([], [])
            self.markers.setData([], [])
            return
        p = self._pts + ([self._pts[0]] if closed else [])
        self.preview.setData([q[0] for q in p], [q[1] for q in p])
        if self.mode in ("trace", "polygon", "polyline"):
            self.markers.setData([q[0] for q in self._pts], [q[1] for q in self._pts])
        else:
            self.markers.setData([], [])

    # -- Trace grain: click around a grain
    def finish_trace(self):
        if self.mode == "trace" and len(self._pts) >= 3:
            pts = list(self._pts)
            self.cancel()
            self.outlineFinished.emit(pts)

    def set_cursor(self, x, y):
        if self.mode in ("trace", "polygon") and self._pts:
            last, first = self._pts[-1], self._pts[0]
            self.rubber.setData([last[0], x, first[0]], [last[1], y, first[1]])
        elif self.mode == "polyline" and self._pts:
            last = self._pts[-1]
            self.rubber.setData([last[0], x], [last[1], y])

    def _near_first(self, scene_pos):
        f = self.mapViewToScene(QtCore.QPointF(*self._pts[0]))
        return math.hypot(f.x() - scene_pos.x(), f.y() - scene_pos.y()) <= 12

    def _focus(self):
        sc = self.scene()
        if sc is not None and sc.views():
            sc.views()[0].setFocus()

    def key_action(self, key):
        if self.mode in ("polygon", "polyline"):
            if key == int(Qt.Key.Key_Escape):
                self.cancel()
            elif key in (int(Qt.Key.Key_Return), int(Qt.Key.Key_Enter)):
                self.finish_polygon()
            return
        if self.mode != "trace":
            return
        if key == int(Qt.Key.Key_Escape):
            self.cancel()
        elif key in (int(Qt.Key.Key_Return), int(Qt.Key.Key_Enter)):
            self.finish_trace()
        elif key in (int(Qt.Key.Key_Backspace), int(Qt.Key.Key_Delete)):
            if self._pts:
                self._pts.pop()
                self._draw()
            else:
                self.outlineUndo.emit()

    def finish_polygon(self):
        if self.mode == "polygon" and len(self._pts) >= 3:
            pts = list(self._pts)
            self.cancel()
            self.shapeFinished.emit("polygon", pts)
        elif self.mode == "polyline" and len(self._pts) >= 2:
            pts = list(self._pts)
            self.cancel()
            self.shapeFinished.emit("line", pts)

    def mouseClickEvent(self, ev):
        left = ev.button() == Qt.MouseButton.LeftButton
        if self.mode == "trace":
            if left:
                ev.accept()
                self._focus()
                p = self.mapSceneToView(ev.scenePos())
                if ev.double() or (len(self._pts) >= 3 and self._near_first(ev.scenePos())):
                    self.finish_trace()
                else:
                    self._pts.append((p.x(), p.y()))
                    self._draw()
                return
            if ev.button() == Qt.MouseButton.RightButton:
                ev.accept()
                if self._pts:
                    self._pts.pop()
                    self._draw()
                else:
                    p = self.mapSceneToView(ev.scenePos())
                    self.outlineRemove.emit(p.x(), p.y())
                return
        if left and self.mode in ("polygon", "polyline", "wand"):
            ev.accept()
            self._focus()
            p = self.mapSceneToView(ev.scenePos())
            if self.mode == "wand":
                self.wandClicked.emit(p.x(), p.y())
            elif ev.double():
                self.finish_polygon()
            else:
                self._pts.append((p.x(), p.y()))
                self._draw()
            return
        if ev.button() == Qt.MouseButton.RightButton and self.mode in ("polygon", "polyline") and self._pts:
            ev.accept()
            self._pts.pop()
            self._draw()
            return
        super().mouseClickEvent(ev)

    def mouseDragEvent(self, ev, axis=None):
        if self.mode == "line" and ev.button() == Qt.MouseButton.LeftButton:
            ev.accept()
            p = self.mapToView(ev.pos())
            cur = (p.x(), p.y())
            if ev.isStart():
                self._pts = [cur]
            elif not self._pts:
                return
            else:
                self._pts.append(cur)
            self._draw()
            if ev.isFinish():
                pts = list(self._pts)
                self.cancel()
                if len(pts) >= 2:
                    self.shapeFinished.emit("line", pts)
            return
        if self.mode in ("lasso", "rect", "ellipse") and ev.button() == Qt.MouseButton.LeftButton:
            ev.accept()
            p = self.mapToView(ev.pos())
            cur = (p.x(), p.y())
            if ev.isStart():
                self._drag0 = cur
                self._pts = [cur]
            elif self._drag0 is None:
                return
            elif self.mode == "lasso":
                self._pts.append(cur)
            else:
                x0, y0 = self._drag0
                if self.mode == "rect":
                    self._pts = [(x0, y0), (cur[0], y0), cur, (x0, cur[1])]
                else:
                    t = np.linspace(0, 2 * np.pi, 72, endpoint=False)
                    cx, cy, rx, ry = (x0 + cur[0]) / 2, (y0 + cur[1]) / 2, abs(cur[0] - x0) / 2, abs(cur[1] - y0) / 2
                    self._pts = list(zip(cx + rx * np.cos(t), cy + ry * np.sin(t)))
            self._draw(closed=True)
            if ev.isFinish():
                pts = list(self._pts)
                self.cancel()
                if len(pts) >= 3:
                    self.shapeFinished.emit(self.mode, pts)
            return
        super().mouseDragEvent(ev, axis)


BG_CHOICES = ("black", "white", "transparent")
PLOTS_LIGHT = True       # the plots have a light background: dark ink, and a blue that shows on white


def plot_blue(alpha=255):
    """The blue of histograms and mean lines. Darker on a light plot background, where the pale blue is hard to see."""
    return (25, 75, 165, alpha) if PLOTS_LIGHT else (110, 165, 255, alpha)


GRAPH_BG = ""            # "black" or "white" when chosen in Preferences, else the plots follow the theme


def bg_style(bg):
    """Background choices for any figure: what is painted on screen, what the export starts from, and the text colours."""
    if bg == "white":
        return dict(fill=QtGui.QColor(255, 255, 255), live=(255, 255, 255), fg=(0, 0, 0), halo=(255, 255, 255, 230))
    if bg == "transparent":
        return dict(fill=None, live=(70, 72, 76), fg=(255, 255, 255), halo=(0, 0, 0, 230))
    return dict(fill=QtGui.QColor(0, 0, 0), live=(0, 0, 0), fg=(255, 255, 255), halo=(0, 0, 0, 230))


def style_graphics(gw, bg):
    """Apply a background choice to a GraphicsLayoutWidget: view background, axes, titles, scale bars and colour bars."""
    st = bg_style(bg)
    gw.setBackground(st["live"])
    fg = QtGui.QColor(*st["fg"])
    for it in list(gw.ci.items.keys()):
        if isinstance(it, pg.ColorBarItem):
            it.axis.setPen(fg)
            it.axis.setTextPen(fg)
        elif isinstance(it, pg.PlotItem):
            for ax in ("left", "bottom"):
                it.getAxis(ax).setPen(fg)
                it.getAxis(ax).setTextPen(fg)
            if it.titleLabel.text:
                it.setTitle(it.titleLabel.text, color=QtGui.QColor(*st["fg"]).name(), size=it.titleLabel.opts.get("size", "10pt"))
            for ch in it.vb.childItems():
                if isinstance(ch, MapOverlay):
                    ch.fg, ch.halo = st["fg"], st["halo"]
                    ch.update()


_QMAX = 16777215


def tighten_pair(gw, plot, bar, data_rect, gap=3):
    """Shrink a plot cell to the picture drawn in it, so the colour bar beside it and the scale bar inside it sit against the
    picture and not at the far edge of a wide window. The visible part of the picture does not change.
    Call again after a resize. Returns a function that puts the layout back as it was."""
    vb, lay = plot.vb, gw.ci.layout
    prev = dict(vr=QtCore.QRectF(vb.viewRect()), sp=lay.horizontalSpacing(), pw=plot.maximumWidth(), ph=plot.maximumHeight(),
                bw=bar.maximumWidth() if bar is not None else None, bh=bar.maximumHeight() if bar is not None else None)

    def settle():
        lay.activate()
        W.QApplication.processEvents()

    def undo():
        plot.setMaximumWidth(prev["pw"])
        plot.setMaximumHeight(prev["ph"])
        if bar is not None and prev["bw"] is not None:
            bar.setMaximumWidth(prev["bw"])
            bar.setMaximumHeight(prev["bh"])
        lay.setHorizontalSpacing(prev["sp"])
        vb.setRange(prev["vr"], padding=0)
        settle()

    plot.setMaximumWidth(_QMAX)
    plot.setMaximumHeight(_QMAX)
    if bar is not None:
        bar.setMaximumHeight(_QMAX)
    settle()
    vr, cell = vb.viewRect(), vb.sceneBoundingRect()
    vis = vr.intersected(QtCore.QRectF(data_rect))
    if vis.width() <= 0 or vis.height() <= 0 or vr.width() <= 0 or vr.height() <= 0:
        return undo
    sx, sy = cell.width() / vr.width(), cell.height() / vr.height()
    extra_w, extra_h = plot.geometry().width() - cell.width(), plot.geometry().height() - cell.height()
    plot.setMaximumWidth(int(round(vis.width() * sx + extra_w)))
    plot.setMaximumHeight(int(round(vis.height() * sy + extra_h)))
    lay.setAlignment(plot, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    lay.setHorizontalSpacing(gap)
    if bar is not None:
        bar.setMaximumHeight(int(round(vis.height() * sy)))
        bar.setMaximumWidth(max(int(bar.effectiveSizeHint(Qt.SizeHint.PreferredSize).width()), 40))
        lay.setAlignment(bar, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
    settle()
    vb.setRange(vis, padding=0)
    settle()
    return undo


def render_scene_png(gw, path, bg, k=1.0, crop=False, margin=10):
    """Save exactly what a GraphicsLayoutWidget shows, at k times the screen size, on a black, white or transparent
    background. Transparent leaves every empty pixel and the area around the frames see-through.
    crop=True saves only the rectangle round the drawn items (plus a small margin), not the empty window around them."""
    st = bg_style(bg)
    src = gw.mapToScene(gw.viewport().rect()).boundingRect()
    if crop:
        box = QtCore.QRectF()
        for it in gw.ci.items.keys():
            if it.isVisible():
                box = box.united(it.sceneBoundingRect())
        if box.isValid():
            src = box.adjusted(-margin, -margin, margin, margin).intersected(src)
    w, h = max(int(src.width() * k), 1), max(int(src.height() * k), 1)
    img = QtGui.QImage(w, h, QtGui.QImage.Format.Format_ARGB32)
    img.fill(st["fill"] if st["fill"] is not None else QtGui.QColor(0, 0, 0, 0))
    p = QtGui.QPainter(img)
    p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
    p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing)
    gw.scene().render(p, QtCore.QRectF(0, 0, w, h), src)
    p.end()
    return img.save(path)


class MapOverlay(pg.GraphicsObject):
    """Scale bar and label drawn over the map in screen space (stays put while panning and zooming)."""

    def __init__(self, vb):
        super().__init__(vb)
        self.vb = vb
        self.scale_on, self.length_um, self.show_label, self.label, self.pt = True, 0.0, False, "", 12
        self.fg, self.halo = (255, 255, 255), (0, 0, 0, 230)
        self.setZValue(1000)
        self.setAcceptedMouseButtons(Qt.MouseButton.NoButton)
        vb.sigResized.connect(lambda *_: self.update())
        vb.sigRangeChanged.connect(lambda *_: self.update())

    def boundingRect(self):
        return QtCore.QRectF(self.vb.boundingRect())

    @staticmethod
    def nice_length(raw):
        if not np.isfinite(raw) or raw <= 0:
            return 1.0
        e = 10 ** np.floor(np.log10(raw))
        return float(max(m for m in (1, 2, 5) if m * e <= raw) * e)

    @staticmethod
    def fmt(um):
        return f"{um / 1000:g} mm" if um >= 1000 else f"{um:g} \u00b5m"

    def _text(self, p, x, y, text):
        font = QtGui.QFont()
        font.setPointSizeF(float(self.pt))
        font.setBold(True)
        path = QtGui.QPainterPath()
        path.addText(x, y, font, text)
        p.setPen(QtGui.QPen(QtGui.QColor(*self.halo), 3.2))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QColor(*self.fg))
        p.drawPath(path)

    def paint(self, p, *args):
        r, vr = self.vb.boundingRect(), self.vb.viewRect()
        if vr.width() <= 0 or r.width() <= 0:
            return
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        if self.show_label and self.label:
            self._text(p, r.left() + 14, r.top() + 14 + self.pt * 1.3, self.label)
        if self.scale_on:
            ppu = r.width() / vr.width()                       # screen pixels per micrometre
            length = self.length_um if self.length_um > 0 else self.nice_length(vr.width() * 0.2)
            w = length * ppu
            x0, y0 = r.left() + 16, r.bottom() - 18
            p.setPen(QtGui.QPen(QtGui.QColor(*self.halo), 1.5))
            p.setBrush(QtGui.QColor(*self.fg))
            p.drawRect(QtCore.QRectF(x0, y0 - 5, min(w, r.width() - 32), 6))
            self._text(p, x0, y0 - 10, self.fmt(length))


class MapGraphics(pg.GraphicsLayoutWidget):
    """Graphics widget that can take keyboard focus, so Esc / Enter / Backspace work while tracing a grain."""
    keyAction = QtCore.pyqtSignal(int)

    def __init__(self):
        super().__init__()
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)

    key_hook = None          # set by the main window: called first, returns True when it used the key

    def keyPressEvent(self, ev):
        if self.key_hook is not None and self.key_hook(ev):
            ev.accept()
            return
        if ev.key() in (Qt.Key.Key_Escape, Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Backspace, Qt.Key.Key_Delete):
            self.keyAction.emit(int(ev.key()))
            ev.accept()
            return
        super().keyPressEvent(ev)


class MapView(W.QWidget):
    hovered = QtCore.pyqtSignal(float, float)

    def __init__(self):
        super().__init__()
        lay = W.QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        self.win = MapGraphics()
        lay.addWidget(self.win)
        self.vb = MapViewBox()
        self.win.keyAction.connect(self.vb.key_action)
        self.outline_items = []
        self.plot = self.win.addPlot(row=0, col=0, viewBox=self.vb)
        self.plot.setAspectLocked(True)
        self.plot.hideAxis("left")
        self.plot.hideAxis("bottom")
        self.overlay = MapOverlay(self.vb)
        self.vb.invertY(True)
        self.items = {}
        for name, z in (("base", 0), ("cluster", 4), ("phase", 5), ("cand", 6), ("sep", 6.5), ("stat", 7), ("rev", 7.5)):
            it = pg.ImageItem()
            it.setZValue(z)
            self.plot.addItem(it)
            it.setVisible(False)
            self.items[name] = it
        self.bar = pg.ColorBarItem(values=(0, 1), colorMap=make_cmap("viridis"), interactive=False, width=14)
        self.win.addItem(self.bar, row=0, col=1)
        self.rect = None
        self.base_hidden = False
        self.marker = pg.PlotCurveItem(pen=pg.mkPen((255, 240, 0), width=3))
        self.marker.setZValue(22)
        self.vb.addItem(self.marker, ignoreBounds=True)
        self.marker_text = pg.TextItem(color=(255, 255, 255), anchor=(0.5, 1.0), fill=pg.mkBrush(0, 0, 0, 190))
        self.marker_text.setZValue(23)
        self.vb.addItem(self.marker_text, ignoreBounds=True)
        self.set_marker(None)
        self.plot.scene().sigMouseMoved.connect(self._moved)

    def set_geometry(self, geom):
        left, top, w, h = geom.rect()
        self.rect = QtCore.QRectF(left, top, w, h)

    def set_image(self, name, rgba):
        it = self.items[name]
        if rgba is None:
            it.setVisible(False)
            return
        it.setImage(rgba, autoLevels=False)
        it.setRect(self.rect)
        it.setVisible(not (name == "base" and self.base_hidden))

    def set_base_hidden(self, hidden):
        """Hide the layer map (and its colour bar) so only the phase / mineral overlay shows."""
        self.base_hidden = bool(hidden)
        it = self.items["base"]
        it.setVisible(not hidden and it.image is not None)
        self.bar.setVisible(not hidden)

    def set_outlines(self, polys):
        for it in self.outline_items:
            self.vb.removeItem(it)
        self.outline_items = []
        for i, pts in enumerate(polys):
            xs = [q[0] for q in pts] + [pts[0][0]]
            ys = [q[1] for q in pts] + [pts[0][1]]
            c = pg.PlotCurveItem(xs, ys, pen=pg.mkPen((0, 230, 255), width=2))
            c.setZValue(8)
            self.vb.addItem(c, ignoreBounds=True)
            lab = pg.TextItem(str(i + 1), color=(255, 255, 255), anchor=(0.5, 0.5))
            lab.setPos(float(np.mean([q[0] for q in pts])), float(np.mean([q[1] for q in pts])))
            lab.setZValue(9)
            self.vb.addItem(lab, ignoreBounds=True)
            self.outline_items += [c, lab]

    def pix_to_view(self, r, c, ny, nx):
        """View coordinates of a position given in (row, col) pixel units of an ny x nx map image."""
        return (self.rect.left() + (c + 0.5) * self.rect.width() / nx, self.rect.top() + (r + 0.5) * self.rect.height() / ny)

    def set_marker(self, centre, radius=0.0, text=""):
        """A ring and a label that point at one place on the map. centre None hides them."""
        if centre is None:
            self.marker.setData([], [])
            self.marker_text.setVisible(False)
            return
        th = np.linspace(0, 2 * np.pi, 80)
        self.marker.setData(centre[0] + radius * np.cos(th), centre[1] + radius * np.sin(th))
        self.marker_text.setText(text)
        self.marker_text.setPos(centre[0], centre[1] - radius)
        self.marker_text.setVisible(True)

    def set_bar(self, lut, lo, hi, label=""):
        cm = pg.ColorMap(np.linspace(0, 1, len(lut)), lut)
        self.bar.setColorMap(cm)
        self.bar.setLevels((lo, hi))

    def fit(self):
        self.vb.autoRange()

    def _moved(self, pos):
        if self.rect is not None and self.plot.sceneBoundingRect().contains(pos):
            p = self.vb.mapSceneToView(pos)
            self.vb.set_cursor(p.x(), p.y())
            self.hovered.emit(p.x(), p.y())


# ----------------------------------------------------------------------------- selection tools
class HeightGrip(W.QFrame):
    """A thin bar under a widget. Dragging it down makes the widget taller, up makes it shorter."""

    def __init__(self, target, lo=140, hi=900):
        super().__init__()
        self.target, self.lo, self.hi = target, lo, hi
        self.setFixedHeight(7)
        self.setCursor(Qt.CursorShape.SplitVCursor)
        self.setToolTip("Drag to change the height of the plot")
        self.setStyleSheet("HeightGrip { border-top: 1px solid palette(mid); border-bottom: 1px solid palette(mid); background: palette(button); }")
        self._y = None

    def mousePressEvent(self, e):
        self._y = e.globalPosition().y()
        self._h = self.target.height()

    def mouseMoveEvent(self, e):
        if self._y is not None:
            h = int(self._h + e.globalPosition().y() - self._y)
            self.target.setFixedHeight(max(self.lo, min(self.hi, h)))

    def mouseReleaseEvent(self, e):
        self._y = None


class ThresholdTool(W.QWidget):
    def __init__(self, main):
        super().__init__()
        self.main = main
        f = W.QVBoxLayout(self)
        r = W.QHBoxLayout()
        self.layer = main.new_layer_box()
        self.scale = W.QComboBox()
        self.scale.addItems(["log10", "linear"])
        r.addWidget(W.QLabel("Layer"))
        r.addWidget(self.layer, 1)
        r.addWidget(self.scale)
        f.addLayout(r)
        self.plot = pg.PlotWidget()
        self.plot.setFixedHeight(260)
        self.plot.setMenuEnabled(False)
        self.curve = pg.PlotDataItem(stepMode="center", fillLevel=0, brush=plot_blue(120), pen=plot_blue())
        self.plot.addItem(self.curve)
        self.region = pg.LinearRegionItem()
        self.plot.addItem(self.region)
        f.addWidget(self.plot)
        f.addWidget(HeightGrip(self.plot))
        r2 = W.QHBoxLayout()
        self.lo, self.hi = W.QLineEdit(), W.QLineEdit()
        for e in (self.lo, self.hi):
            e.setMaximumWidth(70)
        b_clear = W.QPushButton("Reset")
        b_clear.setToolTip("Back to the whole histogram, the starting selection range and no preview")
        r2.addWidget(W.QLabel("from"))
        r2.addWidget(self.lo)
        r2.addWidget(W.QLabel("to"))
        r2.addWidget(self.hi)
        r2.addStretch(1)
        r2.addWidget(b_clear)
        f.addLayout(r2)
        self._busy = False
        b_clear.clicked.connect(self.reset)
        self.layer.changed.connect(self.load_layer)
        self.scale.currentIndexChanged.connect(self.load_layer)
        self.region.sigRegionChanged.connect(self.region_changed)
        self.lo.editingFinished.connect(self.fields_edited)
        self.hi.editingFinished.connect(self.fields_edited)

    def _log(self):
        return self.scale.currentText() == "log10"

    def reset(self):
        """Whole histogram in view, the selection range back to its starting values, and no preview on the map."""
        self.load_layer()
        self.plot.autoRange()
        self.main.set_preview(None)

    @safe
    def load_layer(self):
        s = self.main.s
        if not s.map or not self.layer.spec():
            return
        arr = s.get_layer(self.layer.spec())
        v = arr[np.isfinite(arr) & s.map.valid]
        if self._log():
            v = np.log10(v[v > 0])
        if v.size < 2:
            return
        hist, edges = np.histogram(v, bins=160)
        self.curve.setData(edges, hist)
        self._busy = True
        self.region.setRegion((float(np.percentile(v, 60)), float(v.max())))
        self._busy = False
        self.region_changed()

    def redraw_hist(self):
        """Redraw the histogram after the data changed (a fill, new quantification) and keep the cutoffs as they are."""
        s = self.main.s
        if not s.map or not self.layer.spec():
            return
        try:
            arr = s.get_layer(self.layer.spec())
        except Exception:
            return
        v = arr[np.isfinite(arr) & s.map.valid]
        if self._log():
            v = np.log10(v[v > 0])
        if v.size < 2:
            return
        hist, edges = np.histogram(v, bins=160)
        self.curve.setData(edges, hist)
        self.update_preview()

    def _actual(self, x):
        return 10 ** x if self._log() else x

    def region_changed(self):
        lo, hi = self.region.getRegion()
        self.lo.setText(f"{self._actual(lo):.5g}")
        self.hi.setText(f"{self._actual(hi):.5g}")
        if not self._busy:
            self.update_preview()

    def fields_edited(self):
        lo, hi = parse_float(self.lo.text()), parse_float(self.hi.text())
        if lo is None or hi is None:
            return
        if self._log():
            if lo <= 0 or hi <= 0:
                return
            lo, hi = np.log10(lo), np.log10(hi)
        self.region.setRegion((lo, hi))

    def mask(self):
        lo, hi = parse_float(self.lo.text()), parse_float(self.hi.text())
        arr = self.main.s.get_layer(self.layer.spec())
        return vc.threshold_mask(arr, lo, hi)

    @safe
    def update_preview(self):
        if self.main.s.map and self.layer.spec():
            self.main.set_preview(self.mask())

    @safe
    def apply(self):
        self.main.selection_apply(self.mask())
        self.main.set_preview(None)


class RulesTool(W.QWidget):
    def __init__(self, main):
        super().__init__()
        self.main = main
        v = W.QVBoxLayout(self)
        v.addWidget(W.QLabel("Pixels must satisfy these conditions:"))
        self.table = W.QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(["Layer", "Op", "Value"])
        self.table.horizontalHeader().setSectionResizeMode(0, W.QHeaderView.ResizeMode.Stretch)
        v.addWidget(self.table)
        r = W.QHBoxLayout()
        self.comb = W.QComboBox()
        self.comb.addItems(["AND", "OR"])
        b_add, b_del = W.QPushButton("Add rule"), W.QPushButton("Remove rule")
        r.addWidget(W.QLabel("Combine"))
        r.addWidget(self.comb)
        r.addStretch(1)
        r.addWidget(b_add)
        r.addWidget(b_del)
        v.addLayout(r)
        r2 = W.QHBoxLayout()
        b_prev, b_apply = W.QPushButton("Preview"), W.QPushButton("Keep as selection")
        r2.addWidget(b_prev)
        r2.addWidget(b_apply)
        v.addLayout(r2)
        b_add.clicked.connect(self.add_row)
        b_del.clicked.connect(self.del_row)
        b_prev.clicked.connect(self.preview)
        b_apply.clicked.connect(self.apply)
        self.add_row()

    def add_row(self):
        r = self.table.rowCount()
        self.table.insertRow(r)
        lb = self.main.new_layer_box()
        lb.refill(self.main.s.layer_names() if self.main.s.map else [])
        op = W.QComboBox()
        op.addItems([">", ">=", "<", "<="])
        val = W.QLineEdit("0")
        self.table.setCellWidget(r, 0, lb)
        self.table.setCellWidget(r, 1, op)
        self.table.setCellWidget(r, 2, val)

    def del_row(self):
        r = self.table.currentRow()
        if r < 0:
            r = self.table.rowCount() - 1
        if r >= 0:
            self.table.removeRow(r)

    def mask(self):
        conds = []
        for r in range(self.table.rowCount()):
            lb, op, val = (self.table.cellWidget(r, c) for c in range(3))
            v = parse_float(val.text())
            if v is None:
                raise ValueError(f"Rule {r + 1}: value is not a number")
            conds.append((self.main.s.get_layer(lb.spec()), op.currentText(), v))
        return vc.rules_mask(conds, self.comb.currentText())

    @safe
    def preview(self):
        self.main.set_preview(self.mask())

    @safe
    def apply(self):
        self.main.selection_apply(self.mask())
        self.main.set_preview(None)


class BiplotTool(W.QWidget):
    """Scatter (2-D histogram) of two layers. Draw a gate around a population to select its pixels."""

    def __init__(self, main):
        super().__init__()
        self.main = main
        self.gate = None
        v = W.QVBoxLayout(self)
        g = W.QGridLayout()
        self.xl, self.yl = main.new_layer_box(), main.new_layer_box()
        self.xt, self.yt = W.QComboBox(), W.QComboBox()
        for c in (self.xt, self.yt):
            c.addItems(list(vc.TRANSFORMS))
        self.bins = W.QSpinBox()
        self.bins.setRange(40, 500)
        self.bins.setValue(180)
        g.addWidget(W.QLabel("X"), 0, 0)
        g.addWidget(self.xl, 0, 1)
        g.addWidget(self.xt, 0, 2)
        g.addWidget(W.QLabel("Y"), 1, 0)
        g.addWidget(self.yl, 1, 1)
        g.addWidget(self.yt, 1, 2)
        g.addWidget(W.QLabel("bins"), 2, 0)
        g.addWidget(self.bins, 2, 1)
        b_plot = W.QPushButton("Plot")
        g.addWidget(b_plot, 2, 2)
        v.addLayout(g)
        self.vb = MapViewBox()
        self.plot = pg.PlotWidget(viewBox=self.vb)
        self.plot.setMinimumHeight(240)
        self.img = pg.ImageItem()
        self.plot.addItem(self.img)
        self.gate_curve = pg.PlotCurveItem(pen=pg.mkPen((0, 220, 255), width=2))
        self.plot.addItem(self.gate_curve)
        v.addWidget(self.plot, 1)
        r = W.QHBoxLayout()
        self.grp = W.QButtonGroup(self)
        for i, (name, mode) in enumerate((("Pan", "pan"), ("Polygon", "polygon"), ("Lasso", "lasso"),
                                          ("Rect", "rect"), ("Ellipse", "ellipse"))):
            b = W.QToolButton()
            b.setText(name)
            b.setCheckable(True)
            b.setChecked(mode == "polygon")
            self.grp.addButton(b, i)
            b.clicked.connect(lambda _=False, m=mode: self.vb.set_mode(m))
            r.addWidget(b)
        self.vb.set_mode("polygon")
        v.addLayout(r)
        r2 = W.QHBoxLayout()
        b_clear, b_apply = W.QPushButton("Clear gate"), W.QPushButton("Apply gate to selection")
        r2.addWidget(b_clear)
        r2.addWidget(b_apply)
        v.addLayout(r2)
        b_plot.clicked.connect(self.draw)
        b_clear.clicked.connect(self.clear)
        b_apply.clicked.connect(self.apply)
        self.vb.shapeFinished.connect(self.on_shape)
        self.xl.changed.connect(self.draw)
        self.yl.changed.connect(self.draw)

    def _tvals(self):
        s = self.main.s
        fl = self.main.sel_floor.value()
        tx = vc.transform(s.get_layer(self.xl.spec()), self.xt.currentText(), fl)
        ty = vc.transform(s.get_layer(self.yl.spec()), self.yt.currentText(), fl)
        return tx, ty

    @safe
    def draw(self):
        s = self.main.s
        if not s.map or not self.xl.spec() or not self.yl.spec():
            return
        tx, ty = self._tvals()
        ok = np.isfinite(tx) & np.isfinite(ty) & s.map.valid
        H, xe, ye = np.histogram2d(tx[ok], ty[ok], bins=self.bins.value())
        lut = get_lut("magma")
        a = np.log10(H.T + 1.0)
        rgba = to_rgba(a, lut, 0.0, max(float(a.max()), 1e-3))
        rgba[H.T == 0] = 0
        self.img.setImage(rgba, autoLevels=False)
        self.img.setRect(QtCore.QRectF(xe[0], ye[0], xe[-1] - xe[0], ye[-1] - ye[0]))
        self.plot.setLabel("bottom", f"{self.xt.currentText()}({self.xl.spec()})")
        self.plot.setLabel("left", f"{self.yt.currentText()}({self.yl.spec()})")
        self.vb.autoRange()
        if self.gate is not None:
            self.apply_gate_preview()

    def on_shape(self, kind, pts):
        self.gate = pts
        self.apply_gate_preview()

    @safe
    def apply_gate_preview(self):
        pts = self.gate
        self.gate_curve.setData([p[0] for p in pts] + [pts[0][0]], [p[1] for p in pts] + [pts[0][1]])
        self.main.set_preview(self.mask())

    def mask(self):
        tx, ty = self._tvals()
        inside = vc.points_in_polygon(tx.ravel(), ty.ravel(), self.gate).reshape(tx.shape)
        return inside & np.isfinite(tx) & np.isfinite(ty)

    def clear(self):
        self.gate = None
        self.gate_curve.setData([], [])
        self.vb.cancel()
        self.main.set_preview(None)

    @safe
    def apply(self):
        if self.gate is None:
            raise ValueError("Draw a gate on the plot first")
        self.main.selection_apply(self.mask())
        self.main.set_preview(None)


class AutoStack(W.QStackedWidget):
    """A stacked widget that is only as tall as the page being shown."""

    def __init__(self):
        super().__init__()
        self.currentChanged.connect(lambda _i: self.updateGeometry())

    def sizeHint(self):
        w = self.currentWidget()
        return w.sizeHint() if w is not None else super().sizeHint()

    def minimumSizeHint(self):
        w = self.currentWidget()
        return w.minimumSizeHint() if w is not None else super().minimumSizeHint()


def collapsible(title, inner, open_=False):
    g = W.QGroupBox(title)
    g.setCheckable(True)
    v = W.QVBoxLayout(g)
    v.setContentsMargins(6, 4, 6, 4)
    v.addWidget(inner)
    inner.setVisible(open_)
    g.setChecked(open_)
    g.toggled.connect(inner.setVisible)
    return g


# ----------------------------------------------------------------------------- minerals
RECIPE_KEY = "mineral_recipes"
UNASSIGNED = "__unassigned__"
DEFAULT_TICKED = ("Zircon", "Monazite", "Apatite", "Titanite", "Rutile", "Garnet")


def load_recipes():
    rec = {k: dict(high=list(v["high"]), low=list(v["low"])) for k, v in vc.MINERAL_RECIPES.items()}
    try:
        raw = QtCore.QSettings("LASS", "VitProcessor").value(RECIPE_KEY, "")
        for k, v in (json.loads(raw) if raw else {}).items():
            rec[k] = dict(high=list(v.get("high", [])), low=list(v.get("low", [])))
    except Exception:
        pass
    return rec


