    # ------------------------------------------------------------ housekeeping
    def on_map_built(self):
        self.user_cuts = {}
        self.disc_labels = None
        self.sig = None
        self.sig_table.setRowCount(0)
        self.l_status.setText("")
        self.d_table.setRowCount(0)
        self.incl_labels = None
        self.i_table.setRowCount(0)
        self.i_comp_table.setRowCount(0)
        self.i_status.setText("")
        self.i_count.setText("")
        self.d_elems.setText("")
        self.l_elems.setText("")
        self.refresh_domains()
        self.load_recipe()

    def refresh_recipe_lists(self):
        cur = self.mineral.currentText()
        self.mineral.blockSignals(True)
        self.mineral.clear()
        self.mineral.addItems(list(self.recipes))
        self.mineral.setCurrentText(cur if cur else next(iter(self.recipes), ""))
        self.mineral.blockSignals(False)
        ticked = {self.bulk.item(i).text() for i in range(self.bulk.count()) if self.bulk.item(i).checkState() == CHECKED}
        first = not self.bulk.count()
        self.bulk.clear()
        for n in self.recipes:
            it = W.QListWidgetItem(n)
            it.setFlags(it.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            it.setCheckState(CHECKED if (n in DEFAULT_TICKED if first else n in ticked) else UNCHECKED)
            self.bulk.addItem(it)

    def refresh_domains(self):
        names = list(self.main.s.phases)
        for combo, default in ((self.domain, UNASSIGNED), (self.d_domain, UNASSIGNED), (self.l_domain, UNASSIGNED)):
            cur = combo.currentData() if combo.count() else default
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("unassigned pixels", UNASSIGNED)
            combo.addItem("whole map", None)
            for n in names:
                combo.addItem(f"inside {n}", n)
            idx = combo.findData(cur)
            combo.setCurrentIndex(idx if idx >= 0 else 0)
            combo.blockSignals(False)
        cur = self.i_host.currentText()
        self.i_host.blockSignals(True)
        self.i_host.clear()
        self.i_host.addItems(names)
        j = self.i_host.findText(cur)
        if j < 0:
            j = max(next((k for k, n in enumerate(names) if "zircon" in n.lower()), 0), 0)
        self.i_host.setCurrentIndex(j)
        self.i_host.blockSignals(False)
        cur = self.d_host.currentText()
        self.d_host.blockSignals(True)
        self.d_host.clear()
        self.d_host.addItem("(anywhere)")
        self.d_host.addItems(names)
        i = self.d_host.findText(cur)
        self.d_host.setCurrentIndex(max(i, 0))
        self.d_host.blockSignals(False)

    def domain_mask(self, combo, exclude=()):
        key = combo.currentData()
        s = self.main.s
        if key is None:
            return None
        if key == UNASSIGNED:
            return s.unassigned(exclude)
        ph = s.phases.get(key)
        return ph.mask if ph is not None else None

    # ------------------------------------------------------------ rule table
    def _name(self):
        return self.mineral.currentText().strip()

    def _default_cut(self, el, kind):
        uc = self.user_cuts.get(self._name(), {}).get((el, kind))
        if uc is not None:
            return uc
        s = self.main.s
        if s.map and el and s.element_labels(el):
            return s.auto_cutoff(el)
        return None

    def add_row(self, el="", kind="high", cut="auto"):
        s = self.main.s
        r = self.table.rowCount()
        self.table.insertRow(r)
        eb = W.QComboBox()
        eb.setEditable(True)
        eb.addItems(s.elements() if s.map else [])
        eb.setCurrentText(el)
        kb = W.QComboBox()
        kb.addItems(["high", "low"])
        kb.setCurrentText(kind)
        cb = W.QLineEdit()
        if cut == "auto":
            cut = self._default_cut(el, kind)
        cb.setText("" if cut is None else f"{cut:.5g}")
        self.table.setCellWidget(r, 0, eb)
        self.table.setCellWidget(r, 1, kb)
        self.table.setCellWidget(r, 2, cb)
        eb.currentTextChanged.connect(lambda _t, w=eb: self.element_changed(w))
        kb.currentIndexChanged.connect(lambda _i, w=kb: self.kind_changed(w))
        cb.editingFinished.connect(lambda w=cb: self.cut_edited(w))

    def _row_of(self, widget, col):
        for r in range(self.table.rowCount()):
            if self.table.cellWidget(r, col) is widget:
                return r
        return -1

    def del_row(self):
        r = self.table.currentRow()
        if r < 0:
            r = self.table.rowCount() - 1
        if r >= 0:
            self.table.removeRow(r)
            self.update_preview()

    def element_changed(self, eb):
        if self._busy:
            return
        r = self._row_of(eb, 0)
        if r < 0:
            return
        el = eb.currentText().strip()
        kind = self.table.cellWidget(r, 1).currentText()
        if self.main.s.map and self.main.s.element_labels(el):
            c = self._default_cut(el, kind)
            self.table.cellWidget(r, 2).setText("" if c is None else f"{c:.5g}")
            self.table.setCurrentCell(r, 0)
            self.show_hist()
            self.update_preview()

    def kind_changed(self, kb):
        self.update_preview()

    def cut_edited(self, cb):
        if self._busy:
            return
        r = self._row_of(cb, 2)
        if r < 0:
            return
        val = parse_float(cb.text())
        if val is not None and val > 0:
            el = self.table.cellWidget(r, 0).currentText().strip()
            kind = self.table.cellWidget(r, 1).currentText()
            self.user_cuts.setdefault(self._name(), {})[(el, kind)] = val
            self.table.setCurrentCell(r, 0)
            self.show_hist()
        self.update_preview()

    def rules(self):
        out = []
        for r in range(self.table.rowCount()):
            el = self.table.cellWidget(r, 0).currentText().strip()
            kind = self.table.cellWidget(r, 1).currentText()
            txt = self.table.cellWidget(r, 2).text().strip()
            if not el:
                continue
            if not txt:
                out.append((el, kind, None))
                continue
            val = parse_float(txt)
            if val is None or val <= 0:
                raise ValueError(f"Rule {r + 1}: the cutoff must be a positive number")
            out.append((el, kind, val))
        return out

    def load_recipe(self):
        name = self._name()
        rec = self.recipes.get(name)
        if rec is None:
            return
        self._busy = True
        self.table.setRowCount(0)
        for el in rec["high"]:
            self.add_row(el, "high")
        for el in rec["low"]:
            self.add_row(el, "low")
        self._busy = False
        if self.table.rowCount():
            self.table.setCurrentCell(0, 0)
        if getattr(self.main, "assign_name", None) is not None:
            self.main.assign_name.setCurrentText(name)
        self.show_hist()
        self.update_preview()

    def reset_cutoffs(self):
        self.user_cuts.pop(self._name(), None)
        self._busy = True
        for r in range(self.table.rowCount()):
            el = self.table.cellWidget(r, 0).currentText().strip()
            kind = self.table.cellWidget(r, 1).currentText()
            c = self._default_cut(el, kind)
            self.table.cellWidget(r, 2).setText("" if c is None else f"{c:.5g}")
        self._busy = False
        self.show_hist()
        self.update_preview()

    def show_hist(self):
        s = self.main.s
        r = self.table.currentRow()
        if not s.map or r < 0:
            self.curve.setData([0, 1], [0])
            return
        el = self.table.cellWidget(r, 0).currentText().strip()
        if not s.element_labels(el):
            self.curve.setData([0, 1], [0])
            return
        arr = s.element_layer(el)
        v = arr[np.isfinite(arr) & s.map.valid & (arr > 0)]
        if v.size < 2:
            return
        hist, edges = np.histogram(np.log10(v), bins=140)
        self.curve.setData(edges, hist)
        cut = parse_float(self.table.cellWidget(r, 2).text())
        self._busy = True
        if cut is not None and cut > 0:
            self.line.setValue(math.log10(cut))
        self._busy = False
        self.plot.setLabel("bottom", f"log10 {el} counts")

    def line_moved(self):
        if self._busy:
            return
        r = self.table.currentRow()
        if r < 0:
            return
        val = 10 ** self.line.value()
        cb = self.table.cellWidget(r, 2)
        cb.setText(f"{val:.5g}")
        el = self.table.cellWidget(r, 0).currentText().strip()
        kind = self.table.cellWidget(r, 1).currentText()
        self.user_cuts.setdefault(self._name(), {})[(el, kind)] = val
        self.update_preview()

    # ------------------------------------------------------------ masks
    def clean(self, m):
        if self.speck.value() > 1:
            m = vc.morph(m, "remove_small", 1, self.speck.value())
        if self.shrink.value() > 0:
            m = vc.morph(m, "erode", self.shrink.value())
        return m & self.main.s.map.valid

    def mask(self):
        s = self.main.s
        if not s.map:
            raise ValueError("Build a map first")
        rules = self.rules()
        miss = s.recipe_missing(rules)
        if miss:
            raise ValueError(f"Not in the map: {', '.join(miss)}. Rebuild the map with those channels or remove the rule.")
        dom = self.domain_mask(self.domain, exclude=(self._name(),))
        return self.clean(s.recipe_mask(rules, dom))

    def update_preview(self):
        if self._busy or not self.main.s.map:
            return
        try:
            m = self.mask()
        except ValueError as e:
            self.status.setText(str(e))
            self.main.set_preview(None)
            return
        self.main.set_preview(m)
        self.status.setText(f"{self._name() or 'preview'}: {int(m.sum()):,} px match (cyan preview on the map)")

    # ------------------------------------------------------------ recipes
    @safe
    def save_recipe(self):
        name = self._name()
        if not name:
            raise ValueError("Give the recipe a name")
        high = [r[0] for r in self.rules() if r[1] == "high"]
        low = [r[0] for r in self.rules() if r[1] == "low"]
        if not high and not low:
            raise ValueError("Add at least one rule")
        self.recipes[name] = dict(high=high, low=low)
        self._store_recipes()
        self.refresh_recipe_lists()
        self.mineral.setCurrentText(name)
        self.main.statusBar().showMessage(f"Recipe '{name}' saved")

    @safe
    def delete_recipe(self):
        name = self._name()
        if name not in self.recipes:
            raise ValueError("No such recipe")
        if name in vc.MINERAL_RECIPES:
            d = vc.MINERAL_RECIPES[name]
            self.recipes[name] = dict(high=list(d["high"]), low=list(d["low"]))
            msg = f"'{name}' restored to the built-in recipe"
        else:
            del self.recipes[name]
            msg = f"Recipe '{name}' deleted"
        self._store_recipes()
        self.refresh_recipe_lists()
        self.load_recipe()
        self.main.statusBar().showMessage(msg)

    def _store_recipes(self):
        user = {k: v for k, v in self.recipes.items()
                if k not in vc.MINERAL_RECIPES or vc.MINERAL_RECIPES[k] != v}
        QtCore.QSettings("LASS", "VitProcessor").setValue(RECIPE_KEY, json.dumps(user))

    # ------------------------------------------------------------ learn from a lassoed grain
    def _typed_elements(self, edit):
        s = self.main.s
        els = []
        for e in re.split(r"[,\s;]+", edit.text()):
            e = e.strip().capitalize()
            if e and e not in els and s.element_labels(e):
                els.append(e)
        return els

    def _lasso_elements(self):
        return self._typed_elements(self.l_elems) or self.main.s.elements()

    @safe
    def learn(self, keep_ref=False, from_selection=False):
        s = self.main.s
        if not s.map:
            raise ValueError("Build a map first")
        if keep_ref and self.sig is not None:
            ref = self.sig["ref"]
        elif self.main.outlines and not from_selection:
            ref = np.logical_or.reduce([o["mask"] for o in self.main.outlines])
        else:
            ref = self.main.cand
            if ref is None or not ref.any():
                raise ValueError("Trace a grain first: press 'Trace a grain' and click around it")
            ref = ref.copy()
        els = self._lasso_elements()
        if len(els) < 2:
            raise ValueError("The map needs at least two elements to compare")
        fl = float(self.l_floor.value())
        logs = [s.element_log(e, fl) for e in els]
        med, sp, n_ref, n_core, contrast = vc.learn_signature(logs, ref, rest=s.map.valid & ~ref)
        self.sig = dict(els=els, med=med, spread=sp, ref=ref, n_ref=n_ref, n_core=n_core, contrast=contrast)
        t = self.sig_table
        t.blockSignals(True)
        t.setRowCount(len(els))
        for i, e in enumerate(els):
            chk = W.QTableWidgetItem()
            chk.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsUserCheckable)
            chk.setCheckState(CHECKED if contrast is None or contrast[i] >= self.l_contrast.value() else UNCHECKED)
            t.setItem(i, 0, chk)
            for c, txt in ((1, e), (2, f"{10 ** med[i]:.4g}"), (4, "" if contrast is None else f"{contrast[i]:.1f}")):
                it = W.QTableWidgetItem(txt)
                it.setFlags(Qt.ItemFlag.ItemIsEnabled)
                t.setItem(i, c, it)
            it = W.QTableWidgetItem("")
            it.setFlags(Qt.ItemFlag.ItemIsEnabled)
            t.setItem(i, 3, it)
        t.blockSignals(False)
        self._fill_ranges()
        t.resizeColumnsToContents()
        nuse = sum(t.item(i, 0).checkState() == CHECKED for i in range(len(els)))
        self.l_status.setText(f"Typical composition taken from {n_core:,} of the {n_ref:,} lassoed px (the rest differed strongly: "
                              f"inclusions, cracks, edges, noise). {nuse} of {len(els)} elements ticked as diagnostic.")
        self.lasso_changed()

    def outlines_changed(self, keep_sig=False):
        n = len(self.main.outlines)
        px = sum(int(o["mask"].sum()) for o in self.main.outlines)
        self.o_label.setText(f"{n} outline{'s' if n != 1 else ''}, {px:,} px" if n else "No outlines")
        if n:
            self.learn(False)
        elif not keep_sig:
            self.sig = None
            self.sig_table.setRowCount(0)
            self.l_status.setText("")
            self.main.set_preview(None)

    def retick(self):
        sig = self.sig
        if sig is None or sig["contrast"] is None:
            return
        t = self.sig_table
        t.blockSignals(True)
        for i in range(len(sig["els"])):
            t.item(i, 0).setCheckState(CHECKED if sig["contrast"][i] >= self.l_contrast.value() else UNCHECKED)
        t.blockSignals(False)
        self.lasso_changed()

    def _fill_ranges(self):
        sig = self.sig
        if sig is None:
            return
        tol, mw = self.l_tol.value(), self.l_width.value()
        t = self.sig_table
        t.blockSignals(True)
        for i in range(len(sig["els"])):
            half = max(tol * sig["spread"][i], mw)
            t.item(i, 3).setText(f"{10 ** (sig['med'][i] - half):.3g} to {10 ** (sig['med'][i] + half):.3g}")
        t.blockSignals(False)

    def lasso_masks(self):
        """-> (mineral mask, enclosed inclusion mask)"""
        s = self.main.s
        sig = self.sig
        if sig is None:
            raise ValueError("Trace a grain first: press 'Trace a grain' and click around it")
        use = [i for i in range(len(sig["els"])) if self.sig_table.item(i, 0).checkState() == CHECKED]
        if not use:
            raise ValueError("Tick at least one element")
        fl = float(self.l_floor.value())
        logs = [s.element_log(sig["els"][i], fl) for i in use]
        misses = int(math.ceil(self.l_miss.value() / 100.0 * len(use) - 1e-9))
        m = vc.signature_match(logs, sig["med"][use], sig["spread"][use], self.l_tol.value(), self.l_width.value(),
                               misses) & s.map.valid
        name, iname = self.main.save_name(), self.l_inc_name.text().strip()
        dom = self.domain_mask(self.l_domain, exclude=(name,))
        if dom is not None:
            m &= dom
        if self.l_conn.isChecked():
            m = vc.keep_touching(m, sig["ref"])
        m = vc.fill_small_holes(m, self.l_gap.value())
        holes = ndi.binary_fill_holes(m) & ~m & s.map.valid & s.unassigned(exclude=(iname,))
        mineral = ndi.binary_fill_holes(m) & s.map.valid if self.l_fill.isChecked() else m
        return self.clean(mineral), self.clean(holes)

    def lasso_changed(self):
        self._fill_ranges()
        if self.sig is None or not self.main.s.map:
            return
        try:
            mineral, inc = self.lasso_masks()
        except ValueError as e:
            self.l_status.setText(str(e))
            return
        self.main.set_preview(inc if self.l_show.currentIndex() == 1 else mineral)
        base = self.l_status.text().split("  |  ")[0]
        self.l_status.setText(f"{base}  |  mineral {int(mineral.sum()):,} px, enclosed inclusions {int(inc.sum()):,} px")

    @safe
    def save_lasso_inclusions(self):
        s = self.main.s
        name = self.l_inc_name.text().strip()
        if not name:
            raise ValueError("Give the inclusion phase a name")
        _, inc = self.lasso_masks()
        if not inc.any():
            raise ValueError("No enclosed inclusions found. Lower 'Smallest inclusion' or tighten the tolerance")
        if name in s.phases:
            inc = inc | s.phases[name].mask
        s.set_phase(name, inc, color=vc.MINERAL_COLORS.get(name))
        self.main.refresh_phases()
        self.main.statusBar().showMessage(f"{name}: {int(s.phases[name].mask.sum()):,} px saved as a phase")

    # ------------------------------------------------------------ several minerals
    @safe
    def run_all(self):
        s = self.main.s
        if not s.map:
            raise ValueError("Build a map first")
        names = [self.bulk.item(i).text() for i in range(self.bulk.count()) if self.bulk.item(i).checkState() == CHECKED]
        if not names:
            raise ValueError("Tick at least one mineral")
        taken = np.zeros(s.map.valid.shape, bool)
        for n, ph in s.phases.items():
            if n not in names:
                taken |= ph.mask
        found, skipped = [], []
        W.QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            for n in names:
                rec = self.recipes[n]
                uc = self.user_cuts.get(n, {})
                rules = [(e, "high", uc.get((e, "high"))) for e in rec["high"]] + [(e, "low", uc.get((e, "low"))) for e in rec["low"]]
                if not rules:
                    continue
                miss = s.recipe_missing(rules)
                if miss:
                    skipped.append(f"{n} (needs {', '.join(miss)})")
                    continue
                m = self.clean(s.recipe_mask(rules, ~taken))
                if m.any():
                    s.set_phase(n, m, color=vc.MINERAL_COLORS.get(n))
                    taken |= m
                    found.append(f"{n} {int(m.sum()):,}")
                elif n in s.phases:
                    s.delete_phase(n)
        finally:
            W.QApplication.restoreOverrideCursor()
        self.main.set_preview(None)
        self.main.refresh_phases()
        msg = "Found (px): " + (", ".join(found) if found else "nothing")
        if skipped:
            msg += ".  Skipped: " + "; ".join(skipped)
        self.status.setText(msg)
        self.main.statusBar().showMessage(msg)
        left = int(s.unassigned().sum())
        self.status.setText(msg + f".  Unassigned: {left:,} px")

    # ------------------------------------------------------------ find inclusions (host subtracted)
    INCL_HOW = (("Not host: host tracer fraction is below", "hostfrac"), ("Foreign signal, all elements together, is above", "foreign"),
                ("Outlier score (an unusual mix) is above", "outlier"), ("A PCA component", "pc"),
                ("An unmixed (NMF) component", "nmf"), ("One element stands out (z)", "z"))

