    def refill_interf_note(self):
        try:
            self.m_note.setText("The ticked interference correction hg204 already removed 204Hg from the counts, so the Morgan method skips its own "
                                "Hg step and only removes the additive Pb background. Fit k206 and k207 again whenever you change the ticks."
                                if vc.hg_already_stripped(self.s) else "")
        except Exception:
            pass
        try:
            rules = self.win.s.interf.rules
            on = [r for r in rules if r.enabled]
            if not rules:
                t = "Interference corrections: none learned yet (Calibrate tab, Interferences page)."
            elif not on:
                t = f"Interference corrections: none ticked of {len(rules)} proposed (Calibrate tab, Interferences page)."
            else:
                t = (f"Interference corrections in the map: {len(on)} ticked ({', '.join(r.id for r in on[:6])}{'...' if len(on) > 6 else ''}). "
                     "They act on counts, before drift and ppm. Change them on the Interferences page and rebuild the map.")
            if vc.interf_stale(self.s):
                t += " The ticks differ from the ones the map was built with: rebuild on the Interferences page, then calibrate again."
            self.interf_note.setText(t)
        except Exception:
            pass

    def sync_strategy(self, r, r76=None):
        """Show a strategy that was applied from code (the accuracy workflow) in the U-Pb page."""
        if not r:
            return
        self._fill_upb()
        for k in range(self.ut.rowCount()):
            nm = self.ut.item(k, 0).text()
            self.ut.cellWidget(k, 1).setCurrentText("primary" if (nm in r["primary"] or (r76 and nm in r76["primary"])) else
                                                    "secondary" if nm in r["heldout"] else "unused")
        self.refill_interf_note()

    def refill(self):
        self.refill_interf_note()
        s = self.s
        if not s.map:
            return
        assigned = sorted({sl.info.rm for sl in s.standards if sl.info.rm})       # as set in the Import and group tab
        rms = [r for r in assigned if s.rm_table.get(r)]
        miss = [r for r in assigned if r not in rms]
        self.rm_note.setText(("No standards are assigned yet. In the Import and group tab, set the role of the standard lines and choose "
                              "their reference material." if not assigned else "")
                             + (f"No accepted element values for {', '.join(miss)}: add them under Reference materials." if miss else ""))
        cur = set(self.rm_list.checked()) if self.rm_list.items() else set(s.quant.rms or rms)
        self.rm_list.set_items(rms, cur & set(rms) or set(rms))
        self.rm_list.fit_height()
        chans = list(s.labels)
        want = set(self.ch_list.checked()) if self.ch_list.items() else set(s.quant.channels)
        self.ch_list.set_items(chans, want & set(chans))
        for cb in (self.rev_ch, self.rev_is):
            cur = cb.currentText()
            cb.blockSignals(True)
            cb.clear()
            cb.addItems(([""] if cb is self.rev_is else []) + chans)
            cb.setCurrentText(cur)
            cb.blockSignals(False)
        self._fill_minerals()
        self._fill_upb()

    def _fill_minerals(self):
        s = self.s
        old = {}
        for r in range(self.mt.rowCount()):
            old[self.mt.item(r, 0).text()] = (self.mt.cellWidget(r, 1).currentText(), self.mt.item(r, 2).text(),
                                              self.mt.cellWidget(r, 3).value())
        names = list(s.phases)
        self.mt.setRowCount(0)
        self.mt.setRowCount(len(names))
        for r, n in enumerate(names):
            it = W.QTableWidgetItem(n)
            it.setFlags(Qt.ItemFlag.ItemIsEnabled)
            self.mt.setItem(r, 0, it)
            mq = s.quant.minerals.get(n)
            if n in old:
                meth, txt, tot = old[n]
            elif mq:
                meth, txt, tot = mq.method, ", ".join(f"{a}={b:g}" for a, b in mq.internal), mq.total
            else:
                meth, tot = "off", 100.0
                p = vc.preset_is(n)
                ch = vc.element_channel(s, p[0]) if p else None
                txt = f"{ch}={p[1]:g}" if ch else ""
            cb = W.QComboBox()
            cb.addItems(["off", "internal", "onepoint", "sum"])
            cb.setCurrentText(meth)
            cb.setToolTip("internal: ratio to an internal standard. onepoint: cps per ppm of the standards. sum: oxide sum to a total")
            self.mt.setCellWidget(r, 1, cb)
            self.mt.setItem(r, 2, W.QTableWidgetItem(txt))
            self.mt.setCellWidget(r, 3, _spin(1, 100, tot, 1, 1))
        self.mt.resizeColumnToContents(0)
        self.mt.resizeRowsToContents()
        fit_table_height(self.mt, 1, 8)

    @staticmethod
    def _parse_pairs(txt, chans):
        out = []
        for part in txt.replace(";", ",").split(","):
            part = part.strip()
            if not part:
                continue
            if "=" not in part:
                raise ValueError(f"'{part}': write the internal standard as channel=ppm, e.g. 29Si=153200")
            a, b = part.split("=", 1)
            a = a.strip()
            if a not in chans:
                raise ValueError(f"Channel {a} is not in the map. Keep it when building the map or pick another channel")
            out.append((a, float(b)))
        return out

    def collect_trace(self):
        s = self.s
        c = s.quant
        rms = self.rm_list.checked()
        if not rms:
            raise ValueError("Tick at least one reference material")
        c.rms = [] if len(rms) == len(self.rm_list.items()) else rms
        c.drift = self.q_drift.currentData()
        c.z = self.q_z.value()
        c.rm_tol = self.q_tol.value() / 100
        c.is_win = int(self.q_win.value())
        c.max_corr = float(self.q_maxcorr.value())
        mins = {}
        for r in range(self.mt.rowCount()):
            meth = self.mt.cellWidget(r, 1).currentText()
            if meth == "off":
                continue
            name = self.mt.item(r, 0).text()
            inc = [e.strip().capitalize() for e in self.sum_els.text().replace(";", ",").split(",") if e.strip()]
            pairs = self._parse_pairs(self.mt.item(r, 2).text(), s._chan) if meth == "internal" else []
            if meth == "internal" and not pairs:
                raise ValueError(f"{name}: give an internal standard such as 29Si=153200")
            mins[name] = vc.MineralQuant(meth, pairs, self.mt.cellWidget(r, 3).value(), inc)
        c.minerals = mins
        ox = {}
        for part in self.sum_oxides.text().replace(";", ",").split(","):
            if "=" in part:
                a, b = (x.strip() for x in part.split("=", 1))
                if vc.parse_oxide(b) is None:
                    raise ValueError(f"'{b}' is not an oxide formula such as Fe2O3")
                ox[a] = b
        c.oxides = ox
        c.channels = self.ch_list.checked()

    @safe
    def apply_trace(self):
        self.collect_trace()
        s = self.s
        if not s.quant.minerals:
            raise ValueError("Choose a method for at least one mineral in the table")
        if not s.quant.channels:
            raise ValueError("Tick the channels that should get ppm: layers")
        s.invalidate()
        self.win.refresh_layer_boxes()
        self.win.refresh_export_lists()
        self.win.thr_tool.redraw_hist()
        self.win.refresh_display()
        self.rev_note.setText(f"Made {len(s.quant.channels)} ppm: layers for {', '.join(s.quant.minerals)}. "
                              "Pick them in any layer list.")

    @safe
    def apply_all(self):
        """Trace element concentrations and U-Pb in one step. A part that is not set up is skipped, and the note says why."""
        s = self.s
        done, skipped = [], []
        opt_note = ""
        if self.all_opt.isChecked():
            for f in (self.collect_trace, self.collect_upb):          # the optimiser scores what is set up now
                try:
                    f()
                except ValueError:
                    pass
            try:
                res = self.win.interf_panel._optimize(apply_strategy=not self.all_keep.isChecked())
                opt_note = f"Optimised first: kept {res['winner']}. "
            except (ValueError, vc.CalibError) as e:
                opt_note = f"Optimisation skipped ({e}). "
        try:
            self.collect_trace()
            if not s.quant.minerals:
                raise ValueError("no mineral has a method")
            if not s.quant.channels:
                raise ValueError("no channels are ticked")
            done.append(f"{len(s.quant.channels)} ppm: layers for {', '.join(s.quant.minerals)}")
        except ValueError as e:
            skipped.append(f"trace elements ({e})")
        try:
            self.collect_upb()
            if not s.upb.minerals:
                raise ValueError("no minerals are ticked")
            done.append(f"U-Pb layers for {', '.join(s.upb.minerals)}")
        except ValueError as e:
            skipped.append(f"U-Pb ({e})")
        if not done:
            raise ValueError("Nothing is set up. " + "; ".join(skipped))
        s.invalidate()
        self.win.refresh_layer_boxes()
        self.win.refresh_export_lists()
        self.win.thr_tool.redraw_hist()
        self.win.refresh_display()
        self.refill_interf_note()
        self.all_note.setText(opt_note + "Made " + " and ".join(done) + "." + (f" Skipped: {'; '.join(skipped)}." if skipped else ""))

    def _review_args(self):
        self.collect_trace()
        lab = self.rev_ch.currentText()
        if not lab:
            raise ValueError("Pick the channel to review")
        is_ = self.rev_is.currentText()
        if not is_:
            for mq in self.s.quant.minerals.values():
                if mq.method == "internal" and mq.internal:
                    is_ = mq.internal[0][0]
                    break
        meth = "internal" if is_ else "onepoint"
        return lab, is_, meth

    @safe
    def review(self):
        lab, is_, _m = self._review_args()
        rows, notes, curve = vc.quant_review(self.s, lab, is_)
        self.rev_note.setText(f"{lab}" + (f" / {is_}" if is_ else " (cps per ppm)") + ". " + " ".join(notes))
        p = self.rev_plot
        p.clear()
        p.setLabel("left", "relative sensitivity" if is_ else "cps per ppm")
        p.setLabel("bottom", "minutes into the session")
        t0 = min((r["time"] for r in rows if np.isfinite(r["time"])), default=0.0)
        rmn = sorted({r["rm"] for r in rows})
        for i, rm in enumerate(rmn):
            col = pg.intColor(i, max(3, len(rmn)))
            for st, filled in (("used", True), ("rejected", False)):
                pts = [r for r in rows if r["rm"] == rm and r["status"] == st and np.isfinite(r["value"])]
                if pts:
                    p.addItem(pg.ScatterPlotItem([(r["time"] - t0) / 60 for r in pts], [r["value"] for r in pts], size=9,
                                                 pen=pg.mkPen(col, width=2), brush=pg.mkBrush(col) if filled else pg.mkBrush(None),
                                                 name=rm if filled else None))
        if curve is not None:
            tt = np.linspace(min(r["time"] for r in rows), max(r["time"] for r in rows), 80)
            try:
                p.plot((tt - t0) / 60, curve(tt), pen=pg.mkPen("k", width=2))
            except Exception:
                pass
        tb = self.rev_tab
        tb.setSortingEnabled(False)
        tb.setColumnCount(6)
        tb.setHorizontalHeaderLabels(["Line", "RM", "Value", "Residual %", "Status", "Your choice"])
        tb.setRowCount(len(rows))
        self.rev_plot.setVisible(True)
        tb.setVisible(True)
        ov = self.s.quant.line_override
        for r, row in enumerate(sorted(rows, key=lambda x: x["time"])):
            res = row.get("residual_pct", np.nan)
            vals = [row["name"], row["rm"], row["value"], res, row["status"] + (f": {row['reason']}" if row["reason"] else "")]
            for c, x in enumerate(vals):
                it = NumItem(x)
                if c == 4:
                    it.setForeground(QtGui.QColor(STATUS_COL.get(row["status"], "#000000")))
                tb.setItem(r, c, it)
            cb = W.QComboBox()
            cb.addItems(["auto", "use", "skip"])
            cb.setCurrentText({True: "use", False: "skip"}.get(ov.get(row["member"]), "auto"))
            cb.setEnabled(bool(row["status"] != "off" and np.isfinite(row["value"])))
            cb.currentTextChanged.connect(lambda txt, m=row["member"]: self._override(m, txt))
            tb.setCellWidget(r, 5, cb)
        tb.resizeColumnsToContents()
        tb.resizeRowsToContents()
        fit_table_height(tb, 1, 14)

    def _override(self, member, txt):
        ov = self.s.quant.line_override
        if txt == "auto":
            ov.pop(member, None)
        else:
            ov[member] = txt == "use"
        self.s.invalidate()
        self.review()
        self.win.refresh_display()

    @safe
    def open_trace_qa(self):
        self.collect_trace()
        d = getattr(self, "tqa", None)
        if d is None or not d.isVisible():
            d = self.tqa = TraceQADialog(self.win)
        d.refresh()
        d.show()
        d.raise_()

    @safe
    def open_offsets(self):
        lab, is_, meth = self._review_args()
        labs = self.s.quant.channels or [lab]
        d = OffsetDialog(self.win, labs, meth, is_)
        self._offset_dlg = d
        d.show()

    @safe
    def recovery(self):
        lab, is_, meth = self._review_args()
        labs = self.s.quant.channels or [lab]
        df = vc.quant_recovery(self.s, labs, meth, is_)
        if df is None or len(df) == 0:
            self.rev_note.setText("No reference material has accepted values for these channels.")
            return
        ho = vc.quant_recovery_loo(self.s, labs, meth, is_)
        df = df.rename(columns={"recovery_pct": "recovery_in_calibration_pct"})
        if len(ho):
            df = df.merge(ho[["rm", "channel", "recovery_pct"]].rename(columns={"recovery_pct": "recovery_held_out_pct"}), on=["rm", "channel"], how="left")
        self.rec_tab.deleteLater()
        self.rec_tab = _table(df.round(3))
        fit_table_height(self.rec_tab, 1, 14)
        self.rev_tab.parentWidget().layout().addWidget(self.rec_tab)
        self.rev_note.setText("Recovery is the concentration the calibration gives each standard, over its accepted value (100 % is perfect). "
                              "In calibration: the standard helped set the calibration, so it recovers itself. Held out: the calibration was made without it, "
                              "from the other reference materials of its kind. The held-out column is the one to trust. "
                              "Lines that were rejected from the calibration still count here.")

