    def fill_groups(self):
        c = self.ctx
        self.sgrp.clear()
        self.sgrp.addItem("all")
        if c is None:
            return
        mode = self.smode.currentIndex()
        for r in c.dom_info.itertuples():
            self.sgrp.addItem(f"domain {r.dom}: grain {r.grain} {r.kind}", int(r.dom))

    @safe
    def place_spots(self):
        c = self._need()
        mode = ("map", "grain", "domain", "pixels")[self.smode.currentIndex()]
        if mode in ("domain", "pixels") and not len(c.dom_info):
            raise ValueError("Find domains first, or choose Anywhere / Within each grain")
        grp = self.sgrp.currentData()
        groups = [grp] if (grp is not None and mode in ("domain", "pixels")) else None
        self.spots = vc.virtual_spots(c, self.sd_um.value(), self.sn.value(), mode, groups=groups, seed=self.sseed.value(), min_inside=self.sin.value(), layers=self._layers())
        sp = self.spots
        if not len(sp):
            self.snote.setText("No spot fitted. Make the spot smaller or the domains larger.")
            return
        self.spot_item.setData(x=sp.cx.to_numpy() + 0.5, y=sp.cy.to_numpy() + 0.5, size=self.sd_um.value() / c.dx)
        cols = [x for x in ("group", "n_pix", "purity", "main_dom", "age206/238", "age206/238_se", "mswd_blocks", "age207c", "disc_pct") if x in sp]
        self._set_table(self.sp_holder, sp[cols])
        pure = (sp.purity > 0.97).mean()
        self.snote.setText(f"{len(sp)} spots of {self.sd_um.value():g} um ({int(round(sp.n_pix.median()))} pixels). {100 * pure:.0f} % lie wholly in one domain, "
                           f"{100 * (sp.purity < 0.8).mean():.0f} % are mixed (largest domain under 80 % of the pixels).")
        g = self.sglw
        g.clear()
        p = g.addPlot()
        st = bg_style("white")
        sc = pg.ScatterPlotItem(sp.purity.to_numpy(float) * 100, sp["age206/238"].to_numpy(float), size=7,
                                brush=pg.mkBrush(40, 90, 200, 160), pen=pg.mkPen(None))
        p.addItem(sc)
        p.setLabel("bottom", "share of the spot in its main domain (%)")
        p.setLabel("left", "206/238 date (Ma)")
        p.showGrid(x=True, y=True, alpha=0.2)
        style_graphics(g, "white")

    @safe
    def clear_spots(self):
        self.spot_item.clear()
        self.spots = pd.DataFrame()

    @safe
    def save_spots(self):
        if not len(self.spots):
            return
        p, _ = W.QFileDialog.getSaveFileName(self, "Save spots", "virtual_spots.csv", "CSV (*.csv)")
        if p:
            self.spots.to_csv(p, index=False)

