    def _ptab(self):
        return vc.with_total_errors(self.tab) if self.perr.currentIndex() == 0 else self.tab

    @safe
    def refresh_pop(self, *_a):
        if not len(self.tab):
            return
        date = self.pdate.currentText()
        if date not in self.tab:
            self.pnote.setText(f"{date} is not in the table. Tick the Tera-Wasserburg option on the Domains tab and find domains again.")
            return
        md = self.pmaxd.value() or None
        sel = vc.pop_select(self._ptab(), self.pkeys[self.prule.currentIndex()], date, max_disc=md, min_px=self.ppx.value(),
                            disc=("disc_da_pct", "disc_pct")[self.pdisc.currentIndex()], query=self.pquery.text().strip() or None)
        self.psel = sel
        g = self.pglw
        g.clear()
        if len(sel) < 3:
            self.pnote.setText(f"{len(sel)} dates selected, too few for a density.")
            return
        x = sel[date].to_numpy(float)
        grid = np.linspace(max(0, x.min() * 0.8 - 50), x.max() * 1.2 + 50, 400)
        nb = self.pn.value()
        base, l95, l68, h68, h95 = vc.pop_bootstrap(sel, date, grid, nboot=nb, pdp=self.ppdp.isChecked()) if nb else (vc.kde_curve(x, grid, sigma=sel[date + "_se"].to_numpy(float) if date + "_se" in sel else None, pdp=self.ppdp.isChecked())[0], None, None, None, None)
        p = g.addPlot()
        if l95 is not None:
            a1, a2 = p.plot(grid, l95, pen=None), p.plot(grid, h95, pen=None)
            p.addItem(pg.FillBetweenItem(a1, a2, brush=pg.mkBrush(120, 120, 220, 50)))
            b1, b2 = p.plot(grid, l68, pen=None), p.plot(grid, h68, pen=None)
            p.addItem(pg.FillBetweenItem(b1, b2, brush=pg.mkBrush(120, 120, 220, 90)))
        p.plot(grid, base, pen=pg.mkPen("k", width=2))
        p.addItem(pg.ScatterPlotItem(x, np.full(len(x), -0.02 * float(np.nanmax(base))), size=5, pen=pg.mkPen(None), brush=pg.mkBrush(200, 50, 50, 140)))
        p.setLabel("bottom", f"{date} (Ma)")
        p.setLabel("left", "density")
        p.showGrid(x=True, y=True, alpha=0.2)
        style_graphics(g, "white")
        txt = (f"{len(sel)} dates from {sel.grain.nunique()} grains. Bands: 68 and 95 % of {nb} bootstrap resamples of whole grains." if nb else f"{len(sel)} dates from {sel.grain.nunique()} grains.")
        if len(self.spots) >= 5 and date in self.spots:
            sd_ = self.spots[date].to_numpy(float)
            sd_ = sd_[np.isfinite(sd_)]
            if len(sd_) >= 5:
                c = vc.dz_compare(x, sd_)
                txt += (f" Against the {len(sd_)} virtual spots: Kolmogorov-Smirnov D {c['ks_D']:.2f}, Kuiper V {c['kuiper_V']:.2f}, similarity {c['similarity']:.2f}, "
                        f"likeness {c['likeness']:.2f}, cross-correlation R2 {c['crosscorr_R2']:.2f} (0 for D and V is identical, 1 for the others).")
                lay = [l for l in self._layers() if l in sel and l in self.spots]
                if lay:
                    a1 = np.c_[x, np.log10(np.clip(sel[lay[0]].to_numpy(float), 1e-9, None))]
                    a2 = np.c_[self.spots[date].to_numpy(float), np.log10(np.clip(self.spots[lay[0]].to_numpy(float), 1e-9, None))]
                    c2 = vc.dz_compare_2d(a1, a2)
                    txt += f" With {lay[0]} as the second axis: D {c2['ks_D']:.2f}, V {c2['kuiper_V']:.2f}, likeness {c2['likeness']:.2f}, R2 {c2['crosscorr_R2']:.2f}."
        self.pnote.setText(txt)

    @safe
    def save_pop(self):
        if not len(self.psel):
            return
        p, _ = W.QFileDialog.getSaveFileName(self, "Save selected dates", "zircon_population.csv", "CSV (*.csv)")
        if p:
            self.psel.to_csv(p, index=False)

