    def _fill_widget(self):
        """Replace null (fill gaps): the controls, built once for the Import tab."""
        g = W.QWidget()
        gf = W.QFormLayout(g)
        gf.setContentsMargins(0, 0, 0, 0)
        self.fill_method = W.QComboBox()
        self.fill_method.addItems(["mean", "median", "weighted mean"])
        self.fill_shape = W.QComboBox()
        self.fill_shape.addItems(["square", "circle"])
        self.fill_x, self.fill_y = W.QSpinBox(), W.QSpinBox()
        for sp in (self.fill_x, self.fill_y):
            sp.setRange(1, 501)
            sp.setValue(5)
        self.fill_surr = W.QCheckBox("only fill nulls surrounded by data (not touching the map edge)")
        self.fill_passes = W.QSpinBox()
        self.fill_passes.setRange(1, 50)
        self.fill_scope = W.QComboBox()
        self.fill_scope.addItems(["Displayed layer only", "All layers (global)"])
        self.fill_scope.setCurrentIndex(1)
        b_fill, b_undo = W.QPushButton("Replace null"), W.QPushButton("Restore original")
        b_fill.clicked.connect(self.replace_null_clicked)
        b_undo.clicked.connect(self.restore_null_clicked)
        r = W.QHBoxLayout()
        r.addWidget(self.fill_x)
        r.addWidget(W.QLabel("x"))
        r.addWidget(self.fill_y)
        r.addWidget(W.QLabel("pixels"))
        r.addStretch(1)
        self.fill_auto = W.QCheckBox("Replace null")
        self.fill_auto.setToolTip("Fill gaps automatically after every map build, in all layers, with the settings under the arrow")
        self.fill_auto.setChecked(True)
        gf.addRow("Method", self.fill_method)
        gf.addRow("Shape", self.fill_shape)
        gf.addRow("Window", r)
        gf.addRow("Passes", self.fill_passes)
        gf.addRow(self.fill_surr)
        gf.addRow("Apply to", self.fill_scope)
        r2 = W.QHBoxLayout()
        r2.addWidget(b_fill)
        r2.addWidget(b_undo)
        gf.addRow(r2)
        self.fill_msg = W.QLabel("")
        self.fill_msg.setWordWrap(True)
        gf.addRow(self.fill_msg)
        return g

    # -- centre: map + toolbar
    def _center_panel(self):
        w = W.QWidget()
        v = W.QVBoxLayout(w)
        v.setContentsMargins(2, 2, 2, 2)
        bar = W.QHBoxLayout()
        self.tool_grp = W.QButtonGroup(self)
