        for i, (name, mode, tip) in enumerate((
                ("Pan", "pan", "Drag to pan, wheel to zoom, right-drag to zoom axes"),
                ("Wand", "wand", "Click a pixel: select connected pixels with a similar signature in the Key elements"),
                ("Polygon", "polygon", "Click vertices, double-click to close, right-click removes the last vertex"),
                ("Lasso", "lasso", "Drag freehand"))):
            b = W.QToolButton()
            b.setText(name)
            b.setToolTip(tip)
            b.setCheckable(True)
            b.setChecked(mode == "pan")
