    def sync_find_layers(self):
        """The layer boxes under 'Find a mineral' start from the layer shown on the Minerals tab map."""
        sp = self.min_layer.spec() if getattr(self, "min_layer", None) is not None else ""
        thr, bi = getattr(self, "thr_tool", None), getattr(self, "bi_tool", None)
        if not sp or thr is None or bi is None:
            return
        if thr.layer.spec() != sp:
            thr.layer.setCurrentText(sp)
            if self.s.map:
                thr.load_layer()
        if bi.xl.spec() != sp:
            bi.xl.setCurrentText(sp)

    def _layer_changed(self, *_):
        sp = self.disp_layer.spec()
        if getattr(self, "min_match", None) is not None and self.min_match.isChecked() and sp and not sp.startswith("mineral:"):
            self.min_layer.setCurrentText(sp)          # the Minerals tab follows the Display layer while they are matched
            self.sync_find_layers()
        self.manual_chk.blockSignals(True)
        self.manual_chk.setChecked(False)
        self.manual_chk.blockSignals(False)
        self.refresh_display()

    def _levels_edited(self):
        if parse_float(self.man_lo.text()) is not None and parse_float(self.man_hi.text()) is not None:
            self.manual_chk.blockSignals(True)
            self.manual_chk.setChecked(True)
            self.manual_chk.blockSignals(False)
        self.refresh_display()

