    def _find_group(self, dispw=None):
        g = W.QGroupBox("1. Find pixels")
        v = W.QVBoxLayout(g)
        if dispw is not None:
            v.addWidget(dispw)
        self.method_box = W.QComboBox()           # holds the choice. The buttons below drive it
        self.method_btns = []
        grid = W.QGridLayout()
        for i, (text, key, short, tip) in enumerate((
                ("Click around a grain (learns its composition)", "trace", "Click a grain", "Click around one grain. The program learns its composition and finds the rest"),
                ("Recipe (elements high or low)", "recipe", "Recipe", "Elements high or low, from a stored mineral recipe"),
                ("Threshold one layer", "threshold", "Threshold", "Cut one layer at a level"),
                ("Rules on layers", "rules", "Rules", "Combine rules on several layers"),
                ("Biplot (draw on a scatter plot)", "biplot", "Biplot", "Draw a region on a scatter plot of two layers"),
                ("Wand or draw a shape", "draw", "Wand / draw", "Wand, polygon and lasso"),
                ("Group what is left (inclusions, unknown minerals)", "discover", "Group what's left", "Group the pixels no mineral has claimed. Choose a host mineral to find inclusions inside it, or leave it on all to look for unknown minerals"),
                ("Find inclusions in a host (subtract the host: threshold, outliers, PCA, unmixing)", "incl", "Find inclusions", "Subtract the host crystal from every pixel, then threshold what is left, look for unusual mixes, or decompose it with PCA or unmixing. Works on raw counts"))):
            self.method_box.addItem(text, key)
            b = W.QPushButton(short)
            b.setCheckable(True)
            b.setToolTip(tip)
            b.clicked.connect(lambda _=False, k=i: self.method_box.setCurrentIndex(k))
            grid.addWidget(b, i // 4, i % 4)
            self.method_btns.append(b)
        v.addLayout(grid)
        self.method_box.setVisible(False)
        self.method_stack = AutoStack()
        mt = self.min_tool
        for page in (mt.page_trace, mt.page_recipe, self.thr_tool, self.rules_tool, self.bi_tool, self._draw_page(), mt.page_discover, mt.page_incl):
            self.method_stack.addWidget(page)
        v.addWidget(self.method_stack)
        self.method_box.currentIndexChanged.connect(lambda i: self.method_changed(i))
        i0 = self.method_box.findData("threshold")                 # opens on thresholding one layer
        self.method_box.blockSignals(True)
        self.method_box.setCurrentIndex(i0)
        self.method_box.blockSignals(False)
        self.method_stack.setCurrentIndex(i0)
        self._sync_method_btns()
        return g

